local _, ns = ...
local E = ns.DB.entries
E["npc:ahanu"] = {t="npc",n="Ahanu",z="thunderbluff",s="Ahanu is a tauren merchant operating within Hewa's Armory on the lower rise of Thunder Bluff. He crafts and trades leather armor to travelers and young braves setting out across Mulgore and the wider plains. He also helps newly arrived couriers navigate the bluffs when delivering messages from nearby settlements.",h="Ahanu is a tauren merchant operating within Hewa's Armory on the lower rise of Thunder Bluff.",sec={{t="Merchant of Hewa's Armory",b="Situated amidst the leatherworking stalls and armories of Thunder Bluff's lower rise, Ahanu provides vital equipment to those who make their living across Kalimdor's grasslands. Together with companions like Jahan Hawkwing and Varg Windwhisper, he represents the everyday tradesfolk who keep the tauren capital supplied with durable cured and tanned hide gear. For travelers fresh off a wind rider from Bloodhoof Village, Ahanu frequently serves as a first point of contact in the grand city, receiving deliveries and directing messengers toward the local flight roosts.",sp=0}},faq={{q="Who is Ahanu?",a="Ahanu is a tauren merchant residing on the lower rise of Thunder Bluff inside Hewa's Armory. He sells leather armor and assists couriers arriving in the capital from Bloodhoof Village.",al={"ahanu npc","ahanu lore","who is ahanu"}},{q="What does Ahanu sell?",a="He sells various basic pieces of cured and tanned leather armor, including jerkins, belts, boots, and bracers designed for hunters, rogues, and young adventurers.",al={"ahanu goods","ahanu wares","ahanu vendor"}},{q="Where in Thunder Bluff can I find him?",a="Ahanu is located inside Hewa's Armory on Thunder Bluff's lower rise, near other armorers, leatherworkers, and weapon smiths.",al={"ahanu location","where is ahanu","ahanu map"}},{q="What quests involve Ahanu?",a="Young Horde adventurers are sent to deliver goods to him via wind rider in 'Ride to Thunder Bluff', after which he points them back to Tal, the city's wind rider master.",al={"ahanu quests","ride to thunder bluff ahanu"}}},ang={["race:Tauren"]="For young tauren braves making their very first journey away from Bloodhoof Village, Ahanu offers both familiar hospitality and essential hides for the road."},kw={"ahanu","hewa's armory","jahan hawkwing","leather armor","mulgore","thunder bluff"},rel={"quest:6362","quest:6363","zone:thunderbluff","npc:jahan-hawkwing","topic:tauren"},src={"Ahanu"}}
E["npc:bluff-runner-windstrider"] = {t="npc",n="Bluff Runner Windstrider",z="thunderbluff",s="Bluff Runner Windstrider is a wandering tauren messenger roaming the mesas of Thunder Bluff. He carries urgent dispatches across the city, directing Horde adventurers toward distant frontiers like Ashenvale, Feralas, and the Plaguelands.",h="Bluff Runner Windstrider is a wandering tauren messenger roaming the mesas of Thunder Bluff.",sec={{t="A Messenger on the Mesas",b="Thunder Bluff's soaring plateaus require swift feet to keep its leaders and visitors informed, and Bluff Runner Windstrider fills that vital role. Continually jogging the rope bridges and pathways of the tauren capital, he acts as a town crier and dispatch runner. When key outposts across Kalimdor or the Eastern Kingdoms require reinforcements, Windstrider flags down passing champions to carry word and take up the call to arms.",sp=0},{t="Calls to the Frontier",b="Windstrider's dispatches range far beyond Mulgore's serene borders. He directs hunters northward into Ashenvale to join the Warsong Clan's logging efforts, points hardened scouts south toward Camp Mojache in deep Feralas, and relays grave warnings regarding the ongoing undead menace in the Western Plaguelands. Through him, the tribal heart of Mulgore stays bound to the wider conflicts of the Horde.",sp=0}},faq={{q="Who is Bluff Runner Windstrider?",a="Bluff Runner Windstrider is a tauren messenger who wanders Thunder Bluff. He is responsible for sharing news and rallying capable Horde travelers to assist with urgent campaigns across Azeroth.",al={"windstrider npc","bluff runner","who is windstrider"}},{q="Where can I find Bluff Runner Windstrider?",a="Windstrider does not stand in a single place. He is constantly jogging along the bridges and terraces of Thunder Bluff, often circling between the central mesa and neighboring rises.",al={"windstrider location","where is bluff runner","find windstrider"}},{q="What quests does Windstrider offer?",a="He offers breadcrumb quests that point growing adventurers toward distant contested regions, including the Ashenvale hunt, the establishment of Camp Mojache in Feralas, and calls to arms in the Plaguelands.",al={"windstrider quests","what does he give","bluff runner tasks"}},{q="Why is he called a 'Bluff Runner'?",a="Tauren rely on agile, endurance-trained runners to convey messages across the rugged mesas, cliffs, and suspended bridges of Thunder Bluff where mounted travel can be cumbersome or slow.",al={"what is a bluff runner","bluff runner title"}}},ang={["faction:Horde"]="Windstrider serves as a vital bridge between the peaceful plains of Mulgore and the bloody fronts where the Horde fights for resources and survival.",["race:Tauren"]="Traditional runners like Windstrider keep the dispersed tribes and central elders connected without relying on modern machinery or foreign post networks."},kw={"ashenvale","bluff runner","camp mojache","messenger","mulgore","thunder bluff","windstrider"},rel={"zone:thunderbluff","topic:tauren","topic:horde","quest:235","zone:ashenvale","subzone:camp-mojache"},src={"Bluff Runner Windstrider"}}
E["npc:dendrite-starblaze"] = {t="npc",n="Dendrite Starblaze",z="thunderbluff",s="Dendrite Starblaze is a night elf druid residing in the sacred village of Nighthaven within Moonglade. Serving the Cenarion Circle, he acts as a vital mentor and guide for budding druids of both night elf and tauren descent. Through him, practitioners are summoned to the holy grove to master essential rites such as cleansing toxins and communing with nature's forms.",h="Dendrite Starblaze is a night elf druid residing in the sacred village of Nighthaven within Moonglade.",sec={{t="A Guide in the Sacred Haven",b="Perched within Nighthaven, Dendrite Starblaze represents the nonpartisan, enduring spirit of the Cenarion Circle. When novice druids learn to attune their spirits to Teleport: Moonglade, Dendrite is among the first to welcome them upon arrival. He bridges the gap between ancient Kaldorei tradition and the emerging path of the tauren, treating all who heed the call of the wild as kin beneath the boughs of the sacred haven.",sp=0},{t="Trials of the Wild",b="Dendrite's primary duty involves initiating druidic apprentices into the deeper mysteries of nature. He directs novices through the trials required to understand poison and pestilence, sending them to examine tainted waters and discover herbal curatives. He also oversees the steps that lead druids to the water trials, testing their patience and endurance beneath the surface before granting communion with aquatic forms.",sp=0}},faq={{q="Who is Dendrite Starblaze?",a="Dendrite Starblaze is a night elf druid and Cenarion Circle mentor located in Nighthaven within Moonglade. He guides developing druids through vital class trials and training.",al={"dendrite starblaze","who is dendrite","starblaze moonglade"}},{q="Why does a night elf train Horde tauren?",a="The Cenarion Circle stands outside the political factions of the Alliance and Horde. In Moonglade, night elves and tauren practice the druidic arts together under ancient oaths of brotherhood, leaving worldly conflicts beyond the mountain passes.",al={"why does dendrite train horde","dendrite tauren druid","cross faction druid mentor"}},{q="What quests does Dendrite Starblaze offer?",a="Dendrite oversees several foundational druid class trials. These include quests to master venom and disease curing, as well as trials leading toward the communion required for aquatic form.",al={"dendrite quests","starblaze quest list"}},{q="Where can Dendrite Starblaze be found?",a="He is located in Nighthaven, the settlement situated on the northern shores of Lake Elune'ara in Moonglade.",al={"dendrite location","where is starblaze","dendrite starblaze map"}},{q="How do young druids reach Dendrite for the first time?",a="Novice druids are taught the spell Teleport: Moonglade by their racial trainers around their tenth circle of training. Casting this sends them directly to Moonglade, where Dendrite awaits their arrival.",al={"how to get to dendrite","teleport to moonglade quest"}},{q="Can non-druid adventurers interact with him?",a="Non-druids can visit Nighthaven and speak with Dendrite, but he does not offer training, trials, or quests to those outside the Cenarion Circle's druidic traditions.",al={"non druid dendrite","can warrior talk to starblaze"}}},ang={["class:Druid"]="Dendrite Starblaze is one of your principal guides upon first teleporting to Moonglade, instructing you in curing sickness and pursuing aquatic forms.",["race:Tauren"]="For Shu'halo druids visiting Moonglade from Mulgore, Dendrite serves as living proof that the Cenarion Circle's bond transcends the feud between the Horde and the Alliance.",["race:NightElf"]="Dendrite preserves the classical rites of Kaldorei nature stewardship, welcoming Kaldorei initiates into the Cenarion order at Nighthaven."},kw={"aquatic form","cenarion circle","curing the sick","dendrite starblaze","druid","lessons anew","moonglade","night elf","nighthaven"},rel={"subzone:nighthaven","quest:5921","quest:6121","quest:6124","quest:6125","quest:31","quest:5932","quest:5931"},src={"Dendrite Starblaze"}}
E["npc:falla-sagewind"] = {t="npc",n="Falla Sagewind",z="thunderbluff",s="Falla Sagewind is a reclusive tauren mystic perched high upon a rocky peak overlooking the central Barrens. Stationed between the Crossroads and the Lushwater Oasis, she studies the natural and mystical anomalies troubling the surrounding land. Adventurers probing the twisted corruption seeping from the nearby Wailing Caverns often seek her guidance.",h="Falla Sagewind is a reclusive tauren mystic perched high upon a rocky peak overlooking the central Barrens.",sec={{t="Watcher of the High Crag",b="Falla Sagewind makes her camp far above the dust and bustle of the Barrens trails, situated on a secluded summit just southwest of the Crossroads. From this vantage, she keeps a solemn watch over the fragile savannas below, observing the sudden shifts in wildlife behavior and the encroaching corruption rising from the subterranean fissures of the Wailing Caverns. Her solitary vigil separates her from the daily trade of the Crossroads, positioning her as an observant hermit tuned to the spirits and the land's silent wounds.",sp=0},{t="The Waking Nightmare",b="When strange, pulsating shards are pulled from the mutated beasts of the Barrens, wise travelers are directed to climb the crags toward Falla. She aids in interpreting the twisted magics unraveling the natural order of the oases. Recognizing the grim signs of the Emerald Dream turning foul beneath the earth, she guides heroes toward deeper answers concerning the slumbering Druids of the Fang and the spreading nightmare taking root within the region.",sp=1}},faq={{q="Who is Falla Sagewind?",a="Falla Sagewind is a solitary tauren mystic residing on a high cliff southwest of the Crossroads in the Barrens. She watches over the land and assists travelers seeking to understand the strange magical afflictions spreading across the region.",al={"who is falla sagewind","who is falla","falla sagewind lore"}},{q="Where can I find Falla Sagewind?",a="She is located atop a steep mountain peak directly southwest of the Crossroads and north of the Lushwater Oasis. Reaching her camp requires winding up the rocky pathways ascending from the surrounding savanna.",al={"falla sagewind location","where is falla","how to reach falla sagewind"}},{q="Why is Falla Sagewind interested in the Wailing Caverns?",a="Falla monitors the balance of nature in the Barrens. When mutated beasts and corrupted remnants such as glowing shards appear around the Lushwater Oasis, she helps trace the foul source back to the corrupted druids resting inside the Wailing Caverns.",al={"falla wailing caverns","why does falla care about the oasis","falla glowing shard"}},{q="Is Falla Sagewind affiliated with any clan or family?",a="She carries the Sagewind surname, a name associated with other notable tauren such as Hunter Sagewind and Tahu Sagewind. While a familial connection is likely given tauren naming traditions, she keeps mostly to herself upon her overlook.",al={"sagewind family","who are the sagewinds","is falla related to tahu"}},{q="What quests involve Falla Sagewind?",a="Falla is involved in the investigations surrounding the Wailing Caverns, notably turning in or continuing quests like The Glowing Shard and In Nightmares, which delve into the dark dream corrupting the local oases.",al={"falla sagewind quests","quests from falla","in nightmares quest"}},{q="Can Alliance players interact with Falla Sagewind?",a="As a member of the tauren allied with the Horde, Falla Sagewind is naturally aligned with Thunder Bluff and the Crossroads. Alliance adventurers venturing into the heart of the Barrens will find her hostile.",al={"is falla sagewind hostile","falla alliance friendly"}}},ang={["race:Tauren"]="Falla Sagewind exemplifies the tauren duty of quiet stewardship over the earth, watching for spiritual rot from high places while her brethren defend the roads below.",["class:Druid"]="Druids will recognize Falla as a crucial ally in tracking down the tragic descent of Naralex and the Druids of the Fang within the Wailing Caverns.",["faction:Horde"]="Falla aids the Horde by interpreting strange omens and corrupted relics brought back by scouts from the contested savannas of the Barrens."},kw={"barrens","crossroads","falla","glowing shard","lushwater oasis","nightmares","sagewind","tauren","wailing caverns"},rel={"quest:6981","quest:3369","subzone:lushwater-oasis","subzone:crossroads","topic:tauren"},src={"Falla Sagewind"}}
E["npc:innkeeper-pala"] = {t="npc",n="Innkeeper Pala",z="thunderbluff",s="Innkeeper Pala manages the Cat and the Shaman, the bustling tavern situated on the lower tier of Thunder Bluff. She offers visiting adventurers a hearthstone binding, cold drinks, and a place to rest between journeys across Mulgore and beyond.",h="Innkeeper Pala manages the Cat and the Shaman, the bustling tavern situated on the lower tier of Thunder...",sec={{t="Hospitality on the Lower Rise",b="Perched on the lower rise of Thunder Bluff's sweeping mesas, Innkeeper Pala tends the hearth at the Cat and the Shaman. The establishment serves as one of the primary gathering points for travelers stepping off the central lifts or arriving from the sprawling plains of Mulgore. Holding a steady vigil over her common room, Pala ensures that weary warriors, wandering druids, and visiting allies of the Horde find a dependable shelter, a warm drink, and a familiar home away from home.",sp=0}},faq={{q="Where can I find Innkeeper Pala?",a="Pala is stationed inside the Cat and the Shaman tavern, which sits on the lower rise of Thunder Bluff, close to the city's main lifts.",al={"pala location","where is pala","innkeeper pala map"}},{q="What services does she provide to travelers?",a="Like other innkeepers across Kalimdor, Pala can bind your hearthstone to the Cat and the Shaman so you can return instantly. She also sells simple food and drinks to replenish health and mana.",al={"pala services","can i bind hearthstone thunder bluff","what does pala sell"}},{q="What is the name of her tavern?",a="Her tavern is called the Cat and the Shaman, an establishment serving the constant stream of Horde travelers moving through the city's lower tier.",al={"cat and the shaman","thunder bluff lower inn name","pala inn name"}}},ang={["race:Tauren"]="For tauren returning home from the frontiers of Kalimdor, Pala provides a familiar, welcoming face beneath the towering totems of the central mesas.",["faction:Horde"]="Orcs, trolls, and Forsaken visiting Mulgore find Pala's inn to be a comfortable base of operations right by the lifts."},kw={"cat and the shaman","hearthstone","innkeeper","innkeeper pala","mulgore","pala","thunder bluff"},rel={"zone:thunderbluff","zone:mulgore","topic:tauren","topic:horde","quest:5923","quest:8357"},src={"Innkeeper Pala"}}
E["npc:klannoc-macleod"] = {t="npc",n="Klannoc Macleod",z="thunderbluff",s="Klannoc Macleod is a rugged human warrior residing on Fray Island, situated off the eastern shores of the Barrens. Renowned as an arbiter of martial prowess, he tests aspiring brawlers from both the Alliance and the Horde who seek to master combat stances. Those who earn his respect are directed further inland toward greater trials of strength.",h="Klannoc Macleod is a rugged human warrior residing on Fray Island, situated off the eastern shores of the...",sec={{t="The Master of Fray Island",b="Isolated on Fray Island off the coast of the Merchant Coast in the Barrens, Klannoc Macleod oversees a brutal proving ground for seasoned fighters. Despite being human, Klannoc stands apart from the typical political squabbles of the Alliance and Horde, judging contenders solely by their grit, blade work, and resolve under fire.",sp=0},{t="The Affray",b="Warriors directed to Fray Island are subjected to Macleod's trial: the Affray. Contenders step onto a raised iron grating to endure relentless waves of eager brawlers while Klannoc watches. Those who withstand the onslaught and defeat his chosen champion earn his seal of approval, proving they possess the temperament necessary for berserker training.",sp=0}},faq={{q="Who is Klannoc Macleod?",a="Klannoc Macleod is a veteran human warrior dwelling on Fray Island, just off the coast of the Barrens. He acts as an instructor and trial master for warriors striving to test their limits and unlock new techniques.",al={"who is klannoc","klannoc macleod lore","fray island guy"}},{q="Where can I find Klannoc Macleod?",a="Klannoc is located on Fray Island, a rocky isle off the eastern coast of the Barrens, southeast of the Merchant Coast and Ratchet. You must swim across the open water to reach his camp.",al={"klannoc location","where is fray island","how to get to klannoc"}},{q="Why does a human talk to Horde players on Fray Island?",a="Klannoc operates outside the traditional Alliance and Horde conflict. As an independent combat master, he cares only for martial discipline and warrior ethos, willingly testing any contender who arrives with a proper recommendation.",al={"is klannoc hostile horde","why is klannoc neutral","horde klannoc"}},{q="What is the Affray?",a="The Affray is a trial of endurance held on Fray Island. A warrior must stand atop Klannoc's combat platform and defeat waves of challengers culminating in a battle against Big Will, proving they have the ferocity needed for advanced warrior techniques.",al={"the affray quest","fray island trial","klannoc trial"}},{q="Why send warriors to Klannoc Macleod?",a="Warrior trainers across Azeroth refer their most promising students to Klannoc to undergo a trial of martial fortitude, necessary to prepare them for the fierce focus of the Berserker Stance.",al={"warrior quest fray island","why visit klannoc","berserker stance quest"}},{q="Who does Klannoc send you to after the Affray?",a="After proving your mettle in the Affray, Klannoc directs warriors north to the Alterac Mountains, near Tarren Mill, to seek out Bath'rah the Windwatcher for further guidance.",al={"after klannoc","the windwatcher quest","who is the windwatcher"},sp=1}},ang={["class:Warrior"]="Klannoc Macleod is a crucial figure in a warrior's journey, testing your endurance and ferocity in the Affray before guiding you toward mastering the Berserker Stance.",["faction:Horde"]="Though he is human, Klannoc remains indifferent to faction rivalries, welcoming Horde fighters who come seeking trial and honor on his isolated island.",["faction:Alliance"]="Alliance warriors must venture far into Kalimdor's waters off the Barrens coast to find Klannoc and prove their combat readiness on Fray Island."},kw={"barrens","berserker","fray island","islander","klannoc","macleod","the affray","warrior"},rel={"subzone:fray-island","quest:1719","quest:1718","quest:1791","zone:barrens","quest:887"},src={"Klannoc Macleod"}}
E["npc:lieutenant-lisande"] = {t="npc",n="Lieutenant Lisande",z="thunderbluff",s="Lieutenant Lisande is an emissary of the Argent Dawn stationed upon the high mesas of Thunder Bluff. As a human operating openly in tauren lands, she serves as a liaison against the shared existential threat of the Scourge.",h="Lieutenant Lisande is an emissary of the Argent Dawn stationed upon the high mesas of Thunder Bluff.",sec={{t="An Unlikely Envoy",b="While human faces are rare across the windblown heights of Thunder Bluff, the Argent Dawn transcends traditional faction enmities. Lieutenant Lisande serves the holy order by watching for signs of the Lich King's taint even in remote Kalimdor. When undead forces stir on the plains below, she rallies brave Horde champions to ride out and investigate the encroaching menace before it can defile the sacred earth.",sp=0}},faq={{q="Why is a human standing in Thunder Bluff?",a="Lisande represents the Argent Dawn, a neutral organization dedicated solely to eliminating the Scourge. Because the Dawn welcomes both Alliance and Horde races into its ranks, its liaisons are granted diplomatic entry into capital cities to coordinate defenses against the undead.",al={"human in thunder bluff","why is Lisande here","is she hostile"}},{q="What is the Argent Dawn's interest in Mulgore?",a="The reach of the Lich King threatens every corner of Azeroth, not just the Eastern Kingdoms. Lisande monitors any sign of necromantic activity or invading Scourge forces threatening the peace of Mulgore, ensuring local defenders are alert to the danger.",al={"scourge in mulgore","why thunder bluff","undead in tauren lands"}},{q="What tasks does Lieutenant Lisande give out?",a="Lisande directs adventurers to descend from the bluffs to investigate Scourge incursions sighted around the surrounding territory, tasking them with reporting back so the Dawn can assess the scale of the threat.",al={"lisande quest","what does lisande do","investigate quest"}}},ang={["race:Tauren"]="Though Lisande is an outsider, the tauren respect the Argent Dawn's dedication to purifying the land from the vile corruption of the undead.",["faction:Horde"]="Lisande stands as a reminder that the war against the Scourge requires pragmatism and occasional cooperation with neutral human orders."},kw={"argent dawn","lieutenant lisande","lisande","mulgore","scourge","scourge invasion","thunder bluff"},rel={"topic:argent-dawn","quest:9264","zone:thunderbluff","topic:scourge"},src={"Lieutenant Lisande"}}
E["npc:magatha-grimtotem"] = {t="npc",n="Magatha Grimtotem",z="thunderbluff",s="Magatha Grimtotem is the matriarch of the Grimtotem tribe and the Elder Crone of Thunder Bluff. A formidable shaman and political schemer, she resides on Elder Rise while continually challenging Cairne Bloodhoof's vision for the tauren nation.",h="Magatha Grimtotem is the matriarch of the Grimtotem tribe and the Elder Crone of Thunder Bluff.",sec={{t="The Matriarch of Elder Rise",b="Magatha rose to absolute authority over the Grimtotem through an arranged union followed by the sudden, fatal climbing accident of her mate. Operating from Elder Rise with her personal retinue and bodyguards, she stands as the undisputed political and spiritual leader of her reclusive tribe. Unlike Cairne Bloodhoof, Magatha preaches tauren dominance, viewing other mortal races as intruders upon Kalimdor who ought to be eradicated or swept aside.",sp=0},{t="A Curious Alliance",b="Despite her open disdain for non-tauren, Magatha was among the earliest advocates for admitting the Forsaken into the Horde. She claims the tauren can teach the undead spiritual balance and guide them toward reclaiming their humanity. In practice, however, Magatha collaborates directly with the Royal Apothecary Society beneath Thunder Bluff, consulting figures like Apothecary Zamah on practical alchemy and arcane relic studies.",sp=0},{t="Political Machinations",b="Behind a facade of wise counsel, Magatha actively works to weaken Cairne's authority while testing the defenses of potential threats. She dispatches adventurers into deep hazards—from probing trogg forces in Ragefire Chasm to hunting down the vengeful spirit Arikara. Every task she assigns serves to either consolidate Grimtotem leverage or prepare for the day she can supplant the Bloodhoof dynasty entirely.",sp=1}},faq={{q="Who is Magatha Grimtotem?",a="Magatha is the elder crone and matriarch of the Grimtotem tribe. A gifted shaman since childhood, she assumed total rule of her clan following her husband's suspicious death. She resides on Elder Rise in Thunder Bluff, where she serves as Cairne Bloodhoof's primary political rival.",al={"magatha backstory","who is the elder crone","elder crone thunder bluff"}},{q="Why does Magatha support the Forsaken?",a="Ostensibly, Magatha believes tauren traditions and shamanic understanding can guide the Forsaken back toward humanity. However, many suspect her friendship with the Royal Apothecary Society is driven by a desire for esoteric alchemical secrets and political allies outside Cairne's loyal inner circle.",al={"magatha and undead","why magatha likes forsaken","magatha apothecary zamah"}},{q="What is Magatha's relationship with Cairne Bloodhoof?",a="Magatha views Cairne as soft, naive, and unfit to lead the united tauren. While Cairne advocates coexistence within the Horde and peace across Kalimdor, Magatha believes the Grimtotem should reclaim ancestral lands by force and eliminate foreign intruders.",al={"magatha vs cairne","does magatha hate cairne","cairne and magatha"}},{q="What was the mission in Ragefire Chasm?",a="Magatha sent an emissary named Maur into Ragefire Chasm beneath Orgrimmar to negotiate with the resident troggs. The troggs killed Maur instead, prompting Magatha to send Horde adventurers into the cavern to retrieve Maur's satchel and butcher the troggs in retribution.",al={"magatha ragefire quest","why magatha sent maur","lost satchel magatha"}},{q="Who is Arikara?",a="Arikara is a vengeful wind serpent spirit said to seek retribution against the tauren people. Magatha claims Arikara seeks vengeance directly against Cairne Bloodhoof and tasks capable champions with using enchanted agave to summon and slay the beast.",al={"serpent of vengeance","arikara quest","magatha arikara"}},{q="Where can Magatha Grimtotem be found?",a="Magatha resides inside the large main tent atop Elder Rise in Thunder Bluff, attended by her servant Rahauro and two stoic Grimtotem guards.",al={"magatha location","where is magatha","magatha elder rise"}}},ang={["race:Tauren"]="Every tauren knows of the Grimtotem's dark reputation, making Magatha's presence on Elder Rise an uneasy reminder of the ideological divide threatening their united tribes.",["race:Undead"]="Forsaken travelers find a surprisingly warm reception from the Elder Crone, who actively consults the Royal Apothecary Society in the Pools of Vision.",["class:Shaman"]="Magatha is undeniably one of the most powerful shamans on Kalimdor, commanding primal elements with an authority few living tauren can rival.",["faction:Horde"]="While Magatha offers valuable aid and council against regional threats, her fierce clan loyalty and open contempt for other races make her an untrustworthy comrade."},kw={"arikara","bloodhoof","cairne","elder crone","elder rise","grimtotem","magatha","ragefire","thunder bluff","zamah"},rel={"npc:cairne-bloodhoof","topic:grimtotem-tribe","subzone:elder-rise","quest:1063","quest:1064","quest:5088","quest:5722","quest:853"},src={"Magatha Grimtotem"}}
E["npc:maur-raincaller"] = {t="npc",n="Maur Raincaller",z="thunderbluff",s="Maur Raincaller is a tauren resident found residing in Bloodhoof Village in Mulgore. Connected to the natural and spiritual life of the plains, he assists the village elders and watches over local matters affecting the herds and wild beasts.",h="Maur Raincaller is a tauren resident found residing in Bloodhoof Village in Mulgore.",sec={{t="A Resident of Bloodhoof Village",b="Situated near the heart of Bloodhoof Village on the shores of Lake Stonebull, Maur Raincaller serves his community by attending to regional ecological and beast-related concerns. Like many who bear the mantle of Raincaller, he pays close attention to the balance of the elements and wildlife across the fertile plains of Mulgore. When rogue striders like Mazzranache cause trouble for the local settlements and herders, Maur turns to capable young travelers to step in and restore harmony.",sp=0}},faq={{q="Who is Maur Raincaller?",a="Maur Raincaller is a tauren living in Bloodhoof Village within the verdant grasslands of Mulgore. He acts as a local quest giver, tasking adventurers with managing unruly wildlife in the surrounding area.",al={"maur raincaller role","who is maur","maur raincaller lore"}},{q="Where can I find Maur Raincaller?",a="He can be found standing outdoors among the tepees and hearth fires of Bloodhoof Village, situated just south of Thunder Bluff along the eastern bank of Lake Stonebull.",al={"maur raincaller location","where is maur","maur coords"}},{q="What trouble is Maur dealing with?",a="Maur deals with issues caused by disruptive wild creatures roaming the plains of Mulgore, notably directing adventurers to deal with Mazzranache, a particularly large and troublesome plainstrider.",al={"maur raincaller quest","mazzranache problem","what does maur want"}}},ang={["race:Tauren"]="For young tauren stepping out of Camp Narache, Maur provides an opportunity to protect your people's ancestral lands from wandering predators and disruptive beasts.",["class:Hunter"]="Maur provides an early hunting test against notable beasts like Mazzranache, testing your ability to track and handle dangerous quarry on the open plains."},kw={"bloodhoof village","maur raincaller","mazzranache","mulgore","plainstrider","tauren"},rel={"quest:766","subzone:bloodhoof-village","zone:mulgore","topic:tauren"},src={"Maur Raincaller"}}
E["npc:melor-stonehoof"] = {t="npc",n="Melor Stonehoof",z="thunderbluff",s="Melor Stonehoof is a veteran tauren huntsman stationed atop Hunter Rise in Thunder Bluff. As a mentor in the ways of the hunt, he tests the tracking prowess and mettle of Horde hunters by sending them after the most dangerous predatory beasts across the Barrens and Thousand Needles.",h="Melor Stonehoof is a veteran tauren huntsman stationed atop Hunter Rise in Thunder Bluff.",sec={{t="A Mentor of the Wilds",b="Perched upon the breezy expanse of Hunter Rise, Melor Stonehoof observes the plains below with a practiced eye. The art of the hunt is sacred to the tauren, entwined with survival, spiritual balance, and respect for nature's greatest predators. Melor ensures that those who carry bow and blade in the name of the Horde understand this balance, directing promising stalkers to master their craft through trials against legendary beasts.",sp=0},{t="Trials of the Hunt",b="Melor challenges hunters to seek out legendary and elusive beasts that terrorize the wild. He directs trackers across the plains of the Barrens, from aiding the huntress Sergra Darkthorn at the Crossroads to pursuing Steelsnap, a cunning and vicious hyena in Thousand Needles. Through these trials, hunters prove they can outsmart and outfight the deadliest creatures of central Kalimdor.",sp=0},{t="The Monsters of Distant Lands",b="For those whose skills exceed the Barrens, Melor points toward far-off lands. He charges seasoned hunters with bringing down beasts of terrifying strength, including Deadmire, an ancient crocolisk lurking in the swamps of Dustwallow Marsh, and the savage yeti Frostmaw of the Alterac Mountains. Each hunt serves to test whether a stalker has truly mastered the Hunter's Way.",sp=0}},faq={{q="Where can I find Melor Stonehoof?",a="Melor Stonehoof is located on Hunter Rise in the city of Thunder Bluff. Hunter Rise is the easternmost elevated mesa of the tauren capital, accessible via rope bridges from the central totem mesa.",al={"melor stonehoof location","where is melor","melor stonehoof coords"}},{q="What quests does Melor Stonehoof offer?",a="Melor offers a series of hunting challenges aimed at mid-level adventurers. These include directing players to Sergra Darkthorn in the Barrens, hunting the ferocious hyena Steelsnap, and tracking down formidable beasts farther afield, such as the crocolisk Deadmire in Dustwallow Marsh and the yeti Frostmaw in the Alterac Mountains.",al={"melor quests","what does melor do","melor stonehoof questline"}},{q="Why does Melor send hunters after Steelsnap?",a="Steelsnap is a notoriously vicious and cunning hyena stalking Thousand Needles. Melor sends capable hunters to track and slay her as a test of skill, endurance, and courage in the wild.",al={"why kill steelsnap","steelsnap quest lore"}},{q="What is Deadmire?",a="Deadmire is an unusually large and aggressive crocolisk that prowls the swamps of Dustwallow Marsh. Melor challenges hunters to slay it as a rite of prowess.",al={"who is deadmire","deadmire lore","deadmire beast"}},{q="Do you need to be a hunter class to take his quests?",a="No. While his trials represent the philosophy of the hunter's way and are thematic for the hunter class, Melor offers his hunting contracts to any capable adventurer fighting for the Horde.",al={"melor hunters only","can other classes do melor quests"}},{q="Who is Sergra Darkthorn, and why does Melor send you to her?",a="Sergra Darkthorn is an orc huntress stationed at the Crossroads in the Barrens. Melor directs promising hunters to her so they can aid in subduing the unruly predators of the plains and learn from another veteran of the wild.",al={"melor sergra connection","sergra darkthorn quest"}}},ang={["class:Hunter"]="Melor is one of the quintessential quest givers for Horde hunters, guiding you through rites of tracking that embody the sacred hunter's path.",["race:Tauren"]="Stationed high upon Hunter Rise, Melor exemplifies your people's deep reverence for the hunt as both a trial of strength and an act of balance with the Earth Mother.",["faction:Horde"]="Melor ensures that warriors and stalkers throughout the Horde are hardened against the wild beasts that endanger settlements from Mulgore to Thousand Needles."},kw={"deadmire","frostmaw","hunter rise","hunter's way","melor","sergra darkthorn","steelsnap","stonehoof","thunder bluff"},rel={"subzone:hunter-rise","zone:thunderbluff","quest:861","quest:1131","quest:1205","quest:860","quest:1130","topic:tauren"},src={"Melor Stonehoof"}}
E["npc:miles-welsh"] = {t="npc",n="Miles Welsh",z="thunderbluff",s="Miles Welsh is a Forsaken priest trainer residing deep within the Pools of Vision beneath Thunder Bluff. He offers spiritual instruction and shadow discipline to priests traversing the tauren capital.",h="Miles Welsh is a Forsaken priest trainer residing deep within the Pools of Vision beneath Thunder Bluff.",sec={{t="A Shadow in the Caverns",b="Miles Welsh stands far from the plague-scarred ruins of Lordaeron, making his home in the humid, spirit-laden grotto beneath Thunder Bluff known as the Pools of Vision. As a Forsaken priest, he instructs travelers who channel divine and shadowy energies. His presence in the heart of Mulgore reflects the tenuous diplomatic ties binding the Forsaken to the Horde, sharing sanctuary with tauren mystics and shamans while guiding acolytes in the arts of shadow and faith.",sp=0}},faq={{q="Who is Miles Welsh?",a="Miles Welsh is an undead priest trainer stationed in the Pools of Vision under Thunder Bluff, assisting Horde priests with their training and specialized disciplines.",al={"miles welsh role","who is miles welsh","miles welsh priest trainer"}},{q="Where can I find Miles Welsh?",a="He is located in the Pools of Vision, an underground cavern system beneath the Spirit Rise in Thunder Bluff, accessed through a cave entrance on the mesa.",al={"miles welsh location","where is miles welsh","how to find miles welsh"}},{q="Why is an undead priest trainer in Thunder Bluff?",a="The Forsaken and the tauren are allies within the Horde. The tauren, notably Magatha Grimtotem, advocated for admitting the Forsaken into the faction, allowing emissaries and trainers like Miles Welsh to offer their services in Mulgore.",al={"why forsaken in thunder bluff","undead priest in tauren city"}},{q="What abilities does he teach?",a="Miles Welsh trains general priest spells and assists Forsaken and troll acolytes seeking specialized racial teachings, such as Devouring Plague, Touch of Weakness, or Shadowguard.",al={"priest spells thunder bluff","what does miles welsh teach"}}},ang={["class:Priest"]="For priests traveling through Kalimdor, Miles Welsh is one of the few places in central horde territories to study new spells and advance spiritual training.",["race:Undead"]="Miles provides a familiar, cold face from Lordaeron in an otherwise earthy and sun-drenched tauren capital."},kw={"devouring plague","forsaken","miles welsh","pools of vision","priest trainer","spirit rise","thunder bluff"},rel={"subzone:pools-of-vision","zone:thunderbluff","topic:forsaken","quest:5644","quest:5643"},src={"Miles Welsh"}}
E["npc:rau-cliffrunner"] = {t="npc",n="Rau Cliffrunner",z="thunderbluff",s="Rau Cliffrunner is a tauren scout and scholar stationed high atop Freewind Post in Thousand Needles. Dedicated to protecting his people from regional threats, he studies the history and origins of the hostile Galak centaur through their ancient relics. Working closely with allies in Thunder Bluff, Rau coordinates ventures into dangerous enemy strongholds across the canyon.",h="Rau Cliffrunner is a tauren scout and scholar stationed high atop Freewind Post in Thousand Needles.",sec={{t="Watcher of the Canyons",b="Perched on the perilous bluffs of Freewind Post, Rau Cliffrunner maintains a watchful eye over the sweeping, sun-scorched expanse of Thousand Needles. The tauren outpost serves as a crucial Horde sanctuary in an otherwise hostile territory teeming with ferocious predators, quilboar, and aggressive centaur clans. Rau acts as both an outpost organizer and a dedicated investigator, keen on neutralizing emerging threats before they can overwhelm the vulnerable mesa settlements.",sp=0},{t="Secrets of the Galak",b="Rau's primary obsession lies in the ancient origins of the centaur—a race that has waged brutal war against the tauren for generations. After discovering that the local Galak tribe guarded a sacred relic tracing back to the dawn of their kind, Rau sought a method to bypass the relic's mystical protections. In league with Zangen Stonehoof in Thunder Bluff, Rau obtained sacred moonwell water from Ashenvale to douse the eternal flame at Splithoof Hold, allowing adventurers to retrieve the enigmatic Cloven Hoof for his study.",sp=1}},faq={{q="Where can I find Rau Cliffrunner?",a="Rau Cliffrunner resides atop Freewind Post, the prominent mesa outpost located in the middle of Thousand Needles.",al={"rau cliffrunner location","where is rau","where is rau cliffrunner"}},{q="What is Rau Cliffrunner investigating?",a="Rau is investigating the origins and mystical traditions of the centaur. He seeks the Cloven Hoof, an ancient tribal relic held by the Galak centaur within Splithoof Crag, hoping its strange energies will shed light on the historic enemies of the tauren.",al={"rau cliffrunner purpose","what does rau want","why does rau want the hoof"}},{q="Why does Rau need moonwell water?",a="The Galak centaur keep their ancient relic behind an eternal mystical fire. Rau learned that pure water drawn from a night elven moonwell in Ashenvale possesses the sacred power needed to extinguish the brazier's flame and breach its ward.",al={"rau moonwell water","sacred flame moonwell","why moonwell water"}},{q="Who is working with Rau Cliffrunner in Thunder Bluff?",a="Zangen Stonehoof, stationed in the Hunter Rise of Thunder Bluff, works directly with Rau. Zangen coordinates the retrieval of the Ashenvale moonwell water before directing trusted Horde travelers down to Rau at Freewind Post.",al={"rau ally","zangen and rau","who sent me to rau"}},{q="What is the Cloven Hoof?",a="The Cloven Hoof is a primordial centaur artifact preserved by the Galak clan in Splithoof Hold. Dating back to the creation of the centaur race, it radiates unusual energy that Rau intends to decipher.",al={"cloven hoof relic","what is the hoof","centaur relic thousand needles"}},{q="Does Rau Cliffrunner belong to a specific tauren tribe?",a="No specific tribe is recorded for Rau. He is a tauren warrior of Thunder Bluff stationed at Freewind Post, and nothing ties his surname to a named tribe.",al={"rau cliffrunner tribe","what tribe is rau"}}},ang={["race:Tauren"]="For the tauren, understanding the centaur is a matter of cultural survival; Rau's study into centaur beginnings seeks insight into the ancestral conflict that nearly drove the Shu'halo to extinction.",["faction:Horde"]="Rau's efforts help secure Freewind Post, an isolated Horde bastion critical for maintaining supply lines between the Southern Barrens and Tanaris."},kw={"cloven hoof","freewind post","galak","rau cliffrunner","sacred flame","splithoof crag","splithoof hold","thousand needles","zangen stonehoof"},rel={"subzone:freewind-post","zone:thousandneedles","npc:zangen-stonehoof","quest:1195","subzone:splithoof-hold","subzone:splithoof-crag","topic:centaur","topic:tauren"},src={"Rau Cliffrunner"}}
E["npc:tal"] = {t="npc",n="Tal",z="thunderbluff",s="Tal is the primary wind rider master of Thunder Bluff, tending the city's aerial roost high above the plains of Mulgore. He provides seasoned wyverns to Horde travelers looking to traverse the vast reaches of Kalimdor.",h="Tal is the primary wind rider master of Thunder Bluff, tending the city's aerial roost high above the plains...",sec={{t="Keeper of the High Roost",b="Perched upon the central mesa of Thunder Bluff, Tal manages the vital aerial thoroughfare connecting the tauren capital to the rest of the Horde. From his perch, he tends to the loyal wind riders, or wyverns, ensuring they are healthy, well-fed, and prepared for long-distance journeys across Kalimdor's rugged landscapes. Whether sending messengers down to Bloodhoof Village or dispatching scouts across the Barrens to Orgrimmar, Tal maintains an indispensable lifeline that keeps the towering mesa city in constant touch with its allies.",sp=0}},faq={{q="What role does Tal play in Thunder Bluff?",a="Tal is Thunder Bluff's wind rider master. He oversees the roost atop the bluffs, caring for the winged beasts and chartering flights across Kalimdor for members of the Horde.",al={"who is tal","tal flight master","what does tal do"}},{q="Where does Tal send travelers?",a="Tal connects Thunder Bluff to points across central and southern Kalimdor, including nearby Bloodhoof Village, the Crossroads, Orgrimmar, and distant wilderness outposts.",al={"where can tal fly","tal destinations","thunder bluff flight paths"}},{q="Why are wind riders used instead of traditional mounts?",a="Thunder Bluff's sheer cliff faces and extreme elevation make ground travel slow and winding. Flying mounts such as wind riders provide swift, direct travel into and out of the towering mesa city without needing to traverse the elevators.",al={"why wyverns","thunder bluff flying beasts"}}},ang={["race:Tauren"]="For tauren venturing beyond their ancestral pastures, Tal provides the quickest and safest passage from their high bluffs into the broader world.",["faction:Horde"]="Tal maintains one of the Horde's key transit hubs in Kalimdor, directly linking the tauren capital with the Crossroads and Orgrimmar."},kw={"flight master","mulgore","roost","tal","thunder bluff","wind rider master","wyvern"},rel={"zone:thunderbluff","zone:mulgore","quest:6363","quest:6364","subzone:bloodhoof-village","zone:orgrimmar","subzone:crossroads","topic:tauren"},src={"Tal"}}
E["npc:turak-runetotem"] = {t="npc",n="Turak Runetotem",z="thunderbluff",s="Turak Runetotem is a revered tauren druid trainer residing in the Hall of Elders atop Thunder Bluff's Elder Rise. Serving as a trusted assistant to Archdruid Hamuul Runetotem, he guides novice tauren along the sacred paths of nature and balance. Through Turak, young druids undertake foundational trials to commune with spirits and master animal aspects.",h="Turak Runetotem is a revered tauren druid trainer residing in the Hall of Elders atop Thunder Bluff's Elder...",sec={{t="Voice of the Earthmother",b="Within the serene confines of the Hall of Elders, Turak Runetotem stands as one of the Horde's foremost druidic mentors. Renowned for his deep patience and balanced demeanor, he assists Archdruid Hamuul Runetotem in reviving the ancient druidic arts among the tauren people. Turak ensures that every aspiring druid honors the will of the Earthmother, teaching that physical power must always be grounded in spiritual respect and harmony with nature.",sp=0},{t="The Path of the Claw",b="When a fledgling druid is prepared to embrace animal forms, Turak directs them into the wider world. He initiates their communion with the Cenarion Circle, teaching the art of teleporting across Kalimdor to the sacred haven of Moonglade. Recalling the bewilderment and intensity of his own youthful audience with the Great Bear Spirit, Turak tests his students' courage by sending them to face Lunaclaw and obtain the strength of body and heart needed to walk the Path of the Claw.",sp=0},{t="Guardians of Balance",b="Turak's guidance expands beyond primal combat forms to environmental stewardship. Recognizing the creeping decay and corrupted natural wells across the Barrens, he tasks his disciples with cleansing poisons affecting the land near the Crossroads. Through these trials, along with the arduous rituals beneath the tides to awaken the aquatic form, Turak shapes novices into enduring protectors capable of healing Azeroth's deepest wounds.",sp=0}},faq={{q="Where can I find Turak Runetotem?",a="Turak Runetotem is located on Elder Rise in Thunder Bluff, stationed inside the tent of the Hall of Elders alongside Archdruid Hamuul Runetotem.",al={"turak location","where is turak runetotem","turak runetotem thunder bluff"}},{q="What role does Turak play for new druids?",a="He serves as the primary quest giver and instructor for young tauren druids. He teaches them to commune with Moonglade, unlocks their Bear and Aquatic forms through sacred trials, and instructs them in curing natural poisons.",al={"what does turak teach","turak druid trainer","turak role"}},{q="What is Turak's connection to Moonglade?",a="Turak teaches novice druids the spell to teleport directly to the sacred grove of Moonglade, directing them to the Cenarion Circle's representative, Dendrite Starblaze, for advanced spiritual guidance.",al={"turak moonglade","how does turak know dendrite","teleport moonglade turak"}},{q="How is Turak related to Archdruid Hamuul Runetotem?",a="Both belong to the venerable Runetotem tribe. Turak serves directly under Archdruid Hamuul as one of his most trusted assistants and teachers in the Hall of Elders.",al={"is turak related to hamuul","hamuul and turak"}},{q="Why does Turak send druids to the Crossroads?",a="Turak sends students to investigate and neutralize natural toxins threatening the environment around the Crossroads, preparing them to master the power to cure poison permanently.",al={"turak crossroads","turak poison quest","power over poison"}},{q="What was Turak's personal experience with the Great Bear Spirit?",a="Turak openly shares that when he first walked the path to become a Druid of the Claw, his communion with the Great Bear Spirit was bewildering yet profoundly intense, an experience that deepened his reverence for the form.",al={"turak bear spirit","turak path of the claw"}}},ang={["class:Druid"]="For tauren druids, Turak Runetotem is the pillar of early training, granting the ability to teleport to Moonglade and testing aspirants until they earn their Bear and Aquatic forms.",["race:Tauren"]="As a member of the Runetotem tribe, Turak embodies the revival of druidic customs among the tauren following the Third War, helping his people reclaim their ancient harmony with the Earthmother.",["faction:Horde"]="Turak plays a vital part in anchoring nature magic within the Horde, training guardians capable of combating blights, environmental corruption, and the lingering scars across Kalimdor."},kw={"aquatic form","bear form","dendrite starblaze","druid","elder rise","hall of elders","hamuul","lunaclaw","moonglade","runetotem","thunder bluff","turak"},rel={"subzone:elder-rise","zone:thunderbluff","npc:dendrite-starblaze","quest:6001","quest:5921","quest:6125","quest:31","topic:druid"},src={"Turak Runetotem"}}
E["npc:zangen-stonehoof"] = {t="npc",n="Zangen Stonehoof",z="thunderbluff",s="Zangen Stonehoof is a tauren keeper situated at the High Rise bonfire in the heart of Thunder Bluff. Dutiful and revered among his peers, he faithfully tends to the central flames each evening while coordinating efforts to aid his distant kin across Kalimdor.",h="Zangen Stonehoof is a tauren keeper situated at the High Rise bonfire in the heart of Thunder Bluff.",sec={{t="Keeper of the High Rise Flame",b="Perched on the High Rise of Thunder Bluff, Zangen Stonehoof maintains the central communal bonfire that overlooks the city's highest bluffs. As twilight falls over Mulgore, Zangen kindles the fire, providing warmth and an enduring beacon for the tribes assembled beneath High Chieftain Cairne Bloodhoof. Beyond keeping the flames alight, he maintains ties with allies beyond Mulgore's mesa, acting as a liaison for spiritual and ritual endeavors taking place across the continent.",sp=0},{t="Aiding the Cliffrunners",b="Zangen acts as an intermediary for Rau Cliffrunner, an associate stationed south in Thousand Needles. When Rau required the mystical waters of a night elf moonwell for sacred rituals, Zangen enlisted dependable Horde adventurers to brave the contested forests of Ashenvale. By securing the filled phial from the ancient groves and dispatching it south to Freewind Post, Zangen plays a quiet but pivotal part in preserving ancient rites and assisting scattered tauren posts.",sp=0}},faq={{q="Who is Zangen Stonehoof?",a="Zangen Stonehoof is a tauren resident of Thunder Bluff found beside the large central bonfire on the High Rise. He tends the fire each evening and assists distant kin by organizing aid and courier tasks across Kalimdor.",al={"who is zangen","zangen stonehoof","what does zangen do"}},{q="What does Zangen do with the bonfire?",a="Every evening around nightfall, Zangen lights the great bonfire situated in front of him on the High Rise, providing light and warmth to the upper terrace of the bluff.",al={"why is zangen near the fire","zangen bonfire","lighting the fire"}},{q="Why does Zangen need moonwell water from Ashenvale?",a="Zangen acts on behalf of Rau Cliffrunner, who is stationed at Freewind Post in Thousand Needles. Rau requires water from an Ashenvale moonwell for a sacred ritual, and Zangen tasks capable travelers with obtaining it and carrying it southward.",al={"zangen moonwell quest","the sacred flame","why moonwell water"}},{q="Where can Zangen Stonehoof be found?",a="He stands in the center of the High Rise in Thunder Bluff, right next to the communal fire pit on the upper mesa.",al={"zangen location","find zangen stonehoof","where is zangen"}}},ang={["race:Tauren"]="Zangen embodies the interconnectedness of the tribes, linking Mulgore's civic center directly to distant kin like the Cliffrunners out in Thousand Needles.",["faction:Horde"]="For travelers visiting the great mesa of Thunder Bluff, Zangen offers a point of contact for venturing outward into contested regions like Ashenvale."},kw={"bonfire","high rise","moonwell water","rau cliffrunner","the sacred flame","thunder bluff","zangen stonehoof"},rel={"subzone:high-rise","zone:thunderbluff","npc:rau-cliffrunner","quest:1195","zone:ashenvale","zone:thousandneedles","topic:tauren","topic:horde"},src={"Zangen Stonehoof"}}
E["quest:1063"] = {t="quest",n="The Elder Crone",z="thunderbluff",s="The Elder Crone is a Horde summons directing adventurers from the scarred crags of Stonetalon Mountains to the towering mesa of Thunder Bluff. Seeking spiritual guidance to mend Stonetalon's enraged elements, Seereth Stonebreak sends emissaries to consult the influential tauren elder Magatha Grimtotem on Elder Rise.",h="The Elder Crone is a Horde summons directing adventurers from the scarred crags of Stonetalon Mountains to...",sec={{t="Cry from Stonetalon",b="In the crags of Stonetalon Mountains, goblin deforestation and mining ventures have enraged the local elemental spirits. Seereth Stonebreak, recognizing that raw force alone cannot quell the land's spiritual anguish, concludes that the wisdom of elder shamans is needed. Aware of few tribal leaders by name, Seereth knows of Magatha Grimtotem, an elder reputed for her deep knowledge and commanding presence.",sp=0},{t="Audience on Elder Rise",b="Magatha holds court upon the heights of Elder Rise in Thunder Bluff, where shamanic and spiritual affairs congregate. Though the Grimtotem tribe maintains a precarious, often confrontational relationship with Cairne Bloodhoof's leadership, Magatha is recognized as a formidable elder whose counsel carries immense weight across the Horde. Adventurers arrive not knowing that bringing Stonetalon's troubles to her doorstep will redirect their efforts toward far darker remedies.",sp=0},{t="A Pragmatic Alliance",b="Upon hearing of the elemental turmoil, Magatha does not turn solely to traditional tauren rituals. Instead, she routes the problem toward the Forsaken alchemists dwelling within the city. Her willingness to entangle the Horde's newest, most cynical allies in Kalimdor's spiritual matters reveals her cunning and unconventional approach to power and problem-solving.",sp=1}},faq={{q="Who sends me to find Magatha?",a="Seereth Stonebreak, stationed in the Stonetalon Mountains, gives you this task after you combat the Venture Company goblin invaders tearing through the mountain forests.",al={"quest giver","who starts this","seereth stonebreak"}},{q="Where is Magatha Grimtotem located?",a="Magatha Grimtotem resides in Thunder Bluff atop the Elder Rise, which is the northeastern bluff connected to the central mesa by wooden bridges.",al={"magatha location","where is magatha","elder rise"}},{q="Why is Seereth asking an elder tauren for help?",a="The destructive goblin industrial efforts in Stonetalon have deeply disturbed the regional spirits. Seereth realizes military force alone cannot heal the land and that true spiritual guidance is required to calm the agitated elements.",al={"why elder crone","why consult magatha"}},{q="Who is Magatha Grimtotem?",a="Magatha is the matriarch and elder crone of the Grimtotem tribe. While her tribe is known for being fiercely aggressive and skeptical of the united Horde, Magatha maintains a seat of prominent political and spiritual influence atop Thunder Bluff.",al={"elder crone lore","who is the elder crone","magatha background"}},{q="What happens after speaking with Magatha?",a="Magatha listens to your report of Stonetalon's plight and immediately sends you to consult with the Forsaken emissaries residing on the nearby pools of Elder Rise in the quest Forsaken Aid.",al={"what next","quest follow up"},sp=1},{q="Why is this quest called 'The Elder Crone'?",a="The title refers directly to Magatha Grimtotem herself. Among both her own clan and the wider tauren people, she is widely known as the Elder Crone due to her advanced age, potent shamanic knowledge, and matriarchal authority.",al={"why crone","elder crone title"}}},ang={["race:Tauren"]="For tauren travelers, visiting Magatha is a reminder of the fragile balance between Cairne's united tribes and the aloof, fiercely traditional Grimtotem faction who dwell in the heart of Thunder Bluff.",["class:Shaman"]="Shaman understand the gravity of Stonetalon's elemental rebellion; consulting an elder like Magatha on Elder Rise highlights the profound spiritual crisis unfolding in Kalimdor's peaks.",["faction:Horde"]="This errand exposes the pragmatic threads binding the Horde together, linking a frontier crisis in Stonetalon directly to the high halls of Thunder Bluff's leadership."},kw={"elder crone","elder rise","grimtotem","magatha","seereth stonebreak","spirits","stonetalon","tauren","thunder bluff"},rel={"npc:magatha-grimtotem","npc:seereth-stonebreak","quest:1062","quest:1064","quest:1061","subzone:elder-rise","zone:thunderbluff","zone:stonetalon"},m={start="Seereth Stonebreak",["end"]="Magatha Grimtotem",level="18",faction="Horde",id=1063},src={"The Elder Crone"}}
E["quest:1064"] = {t="quest",n="Forsaken Aid",z="thunderbluff",s="Magatha Grimtotem sends an adventurer deep into Thunder Bluff's Pools of Vision to consult the Forsaken emissary Apothecary Zamah regarding the blighted spirits in Stonetalon Mountains. Positioning the Forsaken as experts in dealing with disease, the elder crone uses Stonetalon's crisis to foster closer cooperation between the tauren and their controversial undead allies.",h="Magatha Grimtotem sends an adventurer deep into Thunder Bluff's Pools of Vision to consult the Forsaken...",sec={{t="A Pragmatic Partnership",b="While Arch Druid Hamuul Runetotem advocated admitting the Forsaken into the Horde out of sympathy and a belief in redemption, Elder Crone Magatha Grimtotem views the undead through a lens of raw utility. When reports reach Thunder Bluff about the corrupted elemental spirits and suffering land in the Stonetalon Mountains, Magatha sees a natural application for Forsaken expertise. Arguing that one must understand disease to cure it, she directs travelers away from traditional druidic remedies and straight into the hands of the Royal Apothecary Society.",sp=0},{t="Beneath the Spirit Rise",b="Tucked away in the cavernous Pools of Vision beneath Spirit Rise, Apothecary Zamah represents Undercity interests on Kalimdor. While the cavern serves as a sacred retreat for tauren shamans, priests, and seers, the presence of the Forsaken chemist marks a subtle political shift. Magatha dispatches a serpent messenger ahead of the adventurer to alert Zamah, establishing an direct line between the Grimtotem matriarch and the Forsaken's alchemical researchers.",sp=0}},faq={{q="Why is Magatha Grimtotem consulting the Forsaken about Stonetalon?",a="Magatha argues that because the Forsaken possess an intimate understanding of plagues and disease, they are uniquely equipped to diagnose and treat the sickness plaguing the land in the Stonetalon Mountains.",al={"why forsaken aid","magatha and the undead","why ask forsaken"}},{q="Where can Apothecary Zamah be found?",a="She resides inside the Pools of Vision, an underground cavern located beneath Spirit Rise on the eastern bluffs of Thunder Bluff, accessible via a cave tunnel near the pool on the mesa above.",al={"apothecary zamah location","where is zamah","pools of vision entrance"}},{q="What happens when you accept the quest from Magatha?",a="Upon accepting the quest, Magatha summons a Serpent Messenger that slithers and flies across Thunder Bluff, traveling directly toward Apothecary Zamah to announce your arrival.",al={"serpent messenger","magatha snake"}},{q="How do the Forsaken feel about helping the tauren in Stonetalon?",a="Apothecary Zamah professes sympathy for the troubled spirits of Stonetalon despite her undead nature, expressing that the Forsaken are eager to offer assistance and solidify their bond with the Horde.",al={"forsaken motives stonetalon","why zamah helps"}},{q="What quest line follows after speaking with Zamah?",a="After meeting Zamah, the investigation deepens into Forsaken alchemy, eventually leading to 'Journey to Tarren Mill' in the Eastern Kingdoms to consult higher-ranking apothecaries.",al={"what comes next","next quest after forsaken aid"}},{q="Why are the Forsaken stationed inside the sacred Pools of Vision?",a="The Pools of Vision host various Horde scholars, mages, and seers. Apothecary Zamah operates there as an official emissary and researcher, keeping her controversial experiments safely tucked away from the main thoroughfares.",al={"why are undead in pools of vision","spirit rise undead"}}},ang={["race:Tauren"]="Traditional tauren look to druidism and the Earth Mother to heal the land; Magatha's insistence on turning to undead alchemists reveals her unconventional approach to tribal diplomacy.",["race:Undead"]="For the Forsaken, lending alchemical aid to the tauren is an important opportunity to prove their worth and secure trust within an otherwise wary Horde.",["faction:Horde"]="This task demonstrates the delicate web of alliances binding Kalimdor and Lordaeron together in the aftermath of the Third War."},kw={"apothecary zamah","forsaken aid","magatha grimtotem","pools of vision","serpent messenger","spirit rise","stonetalon mountains","thunder bluff"},rel={"npc:magatha-grimtotem","quest:853","subzone:pools-of-vision","quest:1063","quest:1065","quest:1061","zone:thunderbluff","subzone:spirit-rise"},m={start="Magatha Grimtotem",["end"]="Apothecary Zamah",level="18",faction="Horde",id=1064},src={"Forsaken Aid"}}
E["quest:1065"] = {t="quest",n="Journey to Tarren Mill",z="thunderbluff",s="Seeking an unconventional solution to drive the Venture Company out of Stonetalon Mountains without excessive bloodshed, Apothecary Zamah in Thunder Bluff dispatches an emissary across the sea to Lordaeron. The quest sends Horde travelers to Tarren Mill in the Hillsbrad Foothills, where the Royal Apothecary Society maintains a sinister laboratory under Apothecary Lydon.",h="Seeking an unconventional solution to drive the Venture Company out of Stonetalon Mountains without excessive...",sec={{t="A Plea Across the Great Sea",b="In Thunder Bluff, Apothecary Zamah represents the tenuous alliance between the newly formed Forsaken and the Earth Mother's children. When the tauren find their sacred lands in the Stonetalon Mountains defiled by the ruthless logging and mining of the Venture Company, conventional approaches fall short. Zamah proposes a different tactic: an unconventional chemical deterrent crafted by her peers in the Royal Apothecary Society. Rather than waging an outright war of attrition, she turns toward specialized alchemical concoctions engineered across the Great Sea.",sp=0},{t="The Road to Hillsbrad",b="The journey demands crossing continents, directing Kalimdor adventurers aboard zeppelinsbound for the ruins of Lordaeron and the Undercity. From the blighted meadows of Tirisfal Glades, the trail cuts southward through the shadowy forests of Silverpine before opening into the contested Hillsbrad Foothills. There, perched near human farmsteads and ruins, lies Tarren Mill—a former human hamlet now fortified as a northern stronghold for the Forsaken and an outpost for Royal Apothecary Society research.",sp=0},{t="Apothecary Lydon's Craft",b="Apothecary Lydon operates out of Tarren Mill with an eye for volatile chemistry and biological agents, often testing questionable mixtures on living subjects. Upon receiving Zamah's note outlining the Venture Company dilemma, Lydon expresses gleeful enthusiasm. The Royal Apothecary Society relishes every opportunity to field-test its compounds in new environments, and Lydon waste no time preparing dark reagents to address the goblin infestation.",sp=1}},faq={{q="Why does Apothecary Zamah send me all the way to Tarren Mill?",a="Apothecary Zamah needs a specialized concoction to dislodge the Venture Company from Stonetalon Mountains without open warfare. Her colleague in the Royal Apothecary Society, Apothecary Lydon, specializes in the necessary alchemical compounds and operates out of Tarren Mill in Lordaeron.",al={"why go to tarren mill","why send to lydon","journey to tarren mill purpose"}},{q="Where is Tarren Mill located?",a="Tarren Mill is located in the northern region of the Hillsbrad Foothills on the continent of Lordaeron. To get there from Kalimdor, take the zeppelin from Durotar to the Undercity in Tirisfal Glades, then travel south through Silverpine Forest and east into Hillsbrad.",al={"where is tarren mill","tarren mill location","how do i get to tarren mill"}},{q="Who are Apothecary Zamah and Apothecary Lydon?",a="Both are members of the Forsaken Royal Apothecary Society. Zamah acts as an emissary stationed in Thunder Bluff's Pools of Vision, studying local flora and assisting the tauren, while Lydon conducts more ruthless alchemical and plague experiments in Tarren Mill.",al={"who is zamah","who is lydon","who are the apothecaries"}},{q="Why are the Forsaken helping with the Venture Company in Stonetalon?",a="The Forsaken joined the Horde largely out of survival and convenience, relying heavily on the tauren's advocacy to secure their place in the faction. Assisting the tauren against the Venture Company helps cement this political alliance and provides a testing ground for Forsaken alchemy.",al={"why do forsaken care about stonetalon","undead helping tauren stonetalon"}},{q="What is the Royal Apothecary Society?",a="The Royal Apothecary Society is an order of Forsaken alchemists and scientists based beneath the ruins of Lordaeron in the Undercity. Guided by Lady Sylvanas Windrunner's mandates, they constantly develop new elixirs, poisons, and blight strains to defend the Forsaken and eradicate their enemies.",al={"what is the royal apothecary society","forsaken apothecaries lore"}},{q="What happens after delivering the note to Lydon?",a="Upon receiving Zamah's request, Apothecary Lydon immediately begins formulating a solution, requiring travelers to collect vials of innocent blood from the Syndicate shadow mages of Durnholde Keep to create a suitable mixture.",al={"next quest after journey to tarren mill","what does lydon need"},sp=1}},ang={["race:Tauren"]="The desecration of Stonetalon cuts deep for the tauren, but accepting Forsaken chemical solutions reveals the uneasy compromises required to protect sacred lands.",["race:Undead"]="This journey represents the reach of the Royal Apothecary Society, demonstrating how Undercity's chemical expertise is projected across the sea to assist distant Horde allies.",["faction:Horde"]="The logistical connection between Thunder Bluff and Tarren Mill serves as an early rite of passage, connecting young Horde defenders to the broader cross-continental alliance."},kw={"apothecary lydon","apothecary zamah","hillsbrad","journey to tarren mill","stonetalon","tarren mill","thunder bluff","undercity","venture company"},rel={"subzone:tarren-mill","zone:hillsbrad","quest:1064","quest:853","topic:venture-company","zone:undercity","zone:tirisfal","topic:lordaeron"},m={start="Apothecary Zamah",["end"]="Apothecary Lydon",level="18",faction="Horde",id=1065},src={"Journey to Tarren Mill"}}
E["quest:1066"] = {t="quest",n="Blood of Innocents",z="thunderbluff",s="Blood of Innocents is an errand undertaken for Apothecary Lydon in Tarren Mill to harvest sinister alchemical components. Seeking to pacify the encroaching Venture Company in Stonetalon Mountains, the Royal Apothecary Society utilizes dark ingredients gathered from regional bandits.",h="Blood of Innocents is an errand undertaken for Apothecary Lydon in Tarren Mill to harvest sinister alchemical...",sec={{t="A Chemical Solution",b="The Horde faces persistent friction in the Stonetalon Mountains, where the rapacious Venture Company ravages the wilderness without regard for the earth or its inhabitants. Rather than dispatching armies to blunt their axes, Apothecary Lydon proposes an alchemical remedy. His plan involves concocting a paralyzing, pacifying agent designed to sap the mercenaries of their aggression, leaving them weak and docile.",sp=0},{t="Stolen from the Wicked",b="Brewing such an insidious concoction demands an exceedingly rare and morally questionable reagent: the blood of innocents. Rather than forcing Horde agents to slaughter innocents directly, Lydon capitalizes on the crimes of the local Syndicate. The fallen nobles and cutthroats infesting Durnholde Keep employ rogue shadow mages who harvest innocent blood for their own profane rituals, making them an opportune target for alchemical requisition.",sp=0}},faq={{q="Why does Apothecary Lydon need innocent blood?",a="Apothecary Lydon needs it as a key reagent for an experimental concoction. He plans to brew a debilitating toxin that drains the violent drive from the Venture Company in Stonetalon Mountains, rendering the defilers subdued and easily handled.",al={"what is innocent blood for","why blood of innocents","lydon blood quest"}},{q="Who has the vials of innocent blood?",a="The vials are carried by Syndicate shadow mages. These rogue casters lurk among the ruins of Durnholde Keep southeast of Tarren Mill, hoarding the blood for their own unsavory spellwork.",al={"who drops the blood","where to get blood of innocents","innocent blood location"}},{q="Why does a Hillsbrad quest involve the Stonetalon Mountains?",a="Horde leaders in Kalimdor reached out to the Royal Apothecary Society in the Eastern Kingdoms for scientific aid. While the conflict against the Venture Company unfolds in Stonetalon, specialists like Apothecary Lydon in Tarren Mill possess the sinister craft required to brew specialized biological remedies.",al={"connection to stonetalon","why tarren mill stonetalon"}},{q="What is the Syndicate?",a="The Syndicate is an organization of former human nobility from the ruined kingdom of Alterac turned brigands, assassins, and cutthroats. Desperate to reclaim their lost lands, they stoop to extortion, dark magic, and preying upon anyone crossing through the Hillsbrad and Alterac regions.",al={"who are the syndicate","syndicate lore"}},{q="Where is Durnholde Keep located?",a="Durnholde Keep lies to the southeast of Tarren Mill in the Hillsbrad Foothills. Once a notorious human fortress and orc internment camp, it now lies half in ruins and serves as a major redoubt for the Syndicate.",al={"find durnholde keep","where is durnholde"}},{q="Is the Horde committing murder to get this blood?",a="No. While the Royal Apothecary Society rarely shies away from gruesome methods, Lydon specifically directs agents to scavenge blood that the Syndicate's shadow mages have already harvested from their own victims.",al={"did horde kill innocents","innocent blood source"}}},ang={["race:Undead"]="For the Forsaken, moral qualms take a backseat to efficiency. Lydon's calculated approach illustrates how the Royal Apothecary Society uses cold logic to solve the problems of their living allies.",["race:Tauren"]="Tauren may find the harvesting of innocent blood deeply unsettling, yet the overarching goal is ending the Venture Company's environmental devastation in Kalimdor.",["faction:Horde"]="The mission highlights the trans-continental ties holding the Horde together, utilizing Forsaken alchemical dark arts in Lordaeron to protect territories in Kalimdor."},kw={"apothecary lydon","blood of innocents","durnholde keep","shadow mages","stonetalon mountains","syndicate","tarren mill","venture company"},rel={"subzone:tarren-mill","subzone:durnholde-keep","quest:1065","topic:syndicate","topic:venture-company","topic:horde"},m={start="Apothecary Lydon",level="23",faction="Horde",id=1066},src={"Blood of Innocents (quest)"}}
E["quest:1067"] = {t="quest",n="Return to Thunder Bluff",z="thunderbluff",s="This quest charges an operative with carrying a potent chemical agent brewed by Apothecary Lydon in Tarren Mill back across the sea to Thunder Bluff. There, Apothecary Zamah awaits the compound so she can engineer a dispersal apparatus against the Venture Company. It marks a crucial step in the Royal Apothecary Society's clandestine research under the very roofs of their Tauren hosts.",h="This quest charges an operative with carrying a potent chemical agent brewed by Apothecary Lydon in Tarren...",sec={{t="A Transcontinental Delivery",b="After securing the volatile ingredients requested in the Hillsbrad Foothills, Apothecary Lydon successfully synthesizes his virulent concoction. Lydon is thoroughly thrilled to see his biological handiwork tested on live subjects, but the raw toxin alone lacks an effective delivery mechanism. To ensure maximum devastation, the vial must be brought back across the Great Sea to the crags of Mulgore, into the waiting hands of Apothecary Zamah.",sp=0},{t="Zamah's Apparatus",b="Residing in the shaded lower tier beneath Thunder Bluff's Spirit Rise, Zamah operates as an ambassador and researcher for the Royal Apothecary Society. Upon receiving Lydon's formulation, she sets to work converting the fluid into an aerosol agent, fabricating a pressurized device known as the Toxic Fogger. Her ultimate goal is to unleash this biological weapon directly upon the intrusive goblins of the Venture Company.",sp=1}},faq={{q="What is the purpose of bringing the toxin to Thunder Bluff?",a="Apothecary Lydon created the raw liquid toxin, but it requires a specialized dispersal system to maximize its lethality across a broad area. Apothecary Zamah possesses the engineering skills needed to adapt the formula into an aerosolized device called the Toxic Fogger.",al={"why thunder bluff","what does zamah do with toxin","lydons toxin use"}},{q="Who is the target of this concoction?",a="The toxin is engineered specifically for deployment against the Venture Company, the ruthless goblin mining syndicate ravaging the land in the Stonetalon Mountains and beyond.",al={"who gets poisoned","target of lydon toxin","who are we fighting"}},{q="Where is Apothecary Zamah located?",a="Apothecary Zamah is situated in the Pools of Vision, a cavern network concealed beneath the Spirit Rise in Thunder Bluff.",al={"find zamah","where is apothecary zamah","zamah location"}},{q="Why are Undercity apothecaries working in a Tauren city?",a="The Tauren granted the Forsaken asylum and supported their admission into the Horde, largely hoping to help them find a cure for their affliction. Apothecary Zamah acts as an envoy of the Royal Apothecary Society, though her work often leans far more toward pestilence and offensive bioweapons than healing.",al={"forsaken in thunder bluff","why are undead in thunder bluff","apothecaries in mulgore"}},{q="What happens after turning in the toxin?",a="Once Zamah takes the vial, she constructs the Toxic Fogger by her side. She will then dispatch you to deploy the aerosol machine directly at a Venture Company facility in the Stonetalon Mountains.",al={"next quest","what after return to thunder bluff","fogger quest"},sp=1},{q="Who created the original formula?",a="The poison was concocted by Apothecary Lydon, a researcher for the Royal Apothecary Society stationed in Tarren Mill within the Hillsbrad Foothills.",al={"who made the poison","who is lydon","apothecary lydon lore"}}},ang={["race:Undead"]="This task demonstrates the Royal Apothecary Society's far-reaching operational network, coordinating research between the Lordaeron front and research outposts on Kalimdor.",["race:Tauren"]="While Magatha Grimtotem and the elders welcomed the Forsaken to Thunder Bluff in hopes of finding redemption or healing, the Apothecaries beneath Spirit Rise spend their time developing contagious bioweapons.",["faction:Horde"]="The collaborative effort between Forsaken alchemists helps protect Horde interests by targeting the destructive operations of the Venture Company."},kw={"apothecary lydon","apothecary zamah","lydon's toxin","pools of vision","return to thunder bluff","royal apothecary society","tarren mill","toxic fogger","venture company"},rel={"quest:853","quest:1086","zone:thunderbluff","topic:venture-company"},m={start="Apothecary Lydon",["end"]="Apothecary Zamah",level="23",faction="Horde",id=1067},src={"Return to Thunder Bluff (1)"}}
E["quest:1130"] = {t="quest",n="Melor Sends Word",z="thunderbluff",s="Melor Sends Word is a summons delivered by Jorn Skyseer in the Barrens on behalf of the renowned hunter Melor Stonehoof. Rising adventurers who have proven their grit across Kalimdor are directed to Hunter's Rise in Thunder Bluff to receive a far more demanding trial.",h="Melor Sends Word is a summons delivered by Jorn Skyseer in the Barrens on behalf of the renowned hunter Melor...",sec={{t="A Summons to Thunder Bluff",b="Word travels fast across the plains. As an adventurer cuts their teeth in the Barrens and surrounding lands, notable hunters take notice of those who show true promise. Jorn Skyseer, keeping watch over the crossings and encampments, serves as an emissary for the elders of Hunter's Rise. He intercepts promising hunters and warriors to let them know that Melor Stonehoof, a revered mentor among the tauren, has marked out a specific path for them.",sp=0},{t="The Road to the Hunt",b="Upon climbing the heights of Hunter's Rise in Thunder Bluff, the seeker meets Melor himself. The elder hunter does not offer praise, but rather asks whether the adventurer possesses the resolve to venture into perilous, distant wilderness. Answering the summons unlocks testing grounds that stretch far beyond the safety of Mulgore, pitting hunters against the fiercest predators across the continent.",sp=0}},faq={{q="Who is Melor Stonehoof?",a="Melor Stonehoof is a veteran tauren hunter stationed on Hunter's Rise in Thunder Bluff. He evaluates up-and-coming trackers and warriors of the Horde, dispatching worthy candidates across Kalimdor to track and hunt notorious beasts.",al={"melor","who is melor","melor stonehoof lore"}},{q="Who delivers this summons?",a="Jorn Skyseer, a tauren seer residing at Camp Taurajo in the Barrens, carries the message. He watches over travelers and sends those who have demonstrated courage up to Thunder Bluff to speak directly with Melor.",al={"who starts quest","jorn skyseer","who sent for me"}},{q="Where can I find Melor Stonehoof?",a="Melor is located on Hunter's Rise, the southeastern mesa of Thunder Bluff dedicated to the hunters, trackers, and beastmasters of the tauren.",al={"melor location","where is melor","hunters rise thunder bluff"}},{q="What path is Melor planning for me?",a="Melor tests your endurance and hunting instincts by sending you on challenging tracking expeditions, beginning with a hunt across the Thousand Needles for the vicious hyena tyrant Steelsnap.",al={"what does melor want","next quest after melor sends word","melor chain"}},{q="Why does Melor recruit adventurers from the Barrens?",a="Surviving the harsh predators, quillboar, and centaur in the Barrens proves an adventurer has the instincts required for elite hunts. Melor seeks individuals who can track elusive and deadly prey in unfamiliar lands.",al={"why me","why does melor care"}},{q="Is this trial restricted to hunters?",a="While it originates on Hunter's Rise and tests the virtues of a tracker, Melor extends the challenge to any Horde adventurer who has proven their strength and resourcefulness in the wild.",al={"is this a hunter quest","can other classes do this"}}},ang={["race:Tauren"]="For the tauren, answering Melor's call is a traditional rite of adulthood and standing, proving one's mastery over the Hunt and bringing honor to Hunter's Rise.",["class:Hunter"]="Melor Stonehoof serves as an archetype of tauren beastcraft, demanding precision, patience, and absolute respect for dangerous quarry.",["faction:Horde"]="Camp Taurajo and Thunder Bluff rely on skilled field operatives to manage dangerous predators encroaching upon Horde supply routes and outposts."},kw={"barrens","camp taurajo","hunter's rise","jorn skyseer","melor sends word","melor stonehoof","steelsnap","thunder bluff"},rel={"npc:melor-stonehoof","quest:1131","quest:3261","zone:thunderbluff"},m={start="Jorn Skyseer",["end"]="Melor Stonehoof",level="30",faction="Horde",id=1130},src={"Melor Sends Word"}}
E["quest:1131"] = {t="quest",n="Steelsnap",z="thunderbluff",s="Steelsnap is a hunting task issued by Melor Stonehoof on Hunter Rise in Thunder Bluff. The hunt departs from traditional tauren reasons for killing, seeking the destruction of a vicious hyena whose pack terrorizes the wildlife of Thousand Needles.",h="Steelsnap is a hunting task issued by Melor Stonehoof on Hunter Rise in Thunder Bluff.",sec={{t="A Hunt Outside the Blessing",b="Tauren tradition dictates that taking a life must serve a sacred or practical purpose: hunting for sustenance, hunting to uphold honor, or hunting to glean wisdom from the Earthmother. Melor Stonehoof offers this quarry as an exception to the rule. Steelsnap is viewed as an abomination against natural balance—a brutal tyrant that sows senseless violence and fear rather than maintaining the cycle of life.",sp=0},{t="The Scourge of the Needles",b="Steelsnap roams the canyons of northern Thousand Needles, lingering south of the centaur enclave at Camp E'thok. Unlike solitary scavengers, this formidable beast draws fierce packmates into his wake, orchestrating attacks that disrupt and cull the more docile wildlife of the canyon floor. Slaying him and retrieving his rib cleanses the needles of his vicious influence.",sp=0}},faq={{q="Why does Melor Stonehoof want Steelsnap killed?",a="Melor Stonehoof considers Steelsnap an aberration that exists outside the Earthmother's blessing. Unlike hunts meant for sustenance, honor, or natural balance, this hunt is an act of cleansing to stop a tyrannical predator from terrorizing peaceful beasts.",al={"why kill steelsnap","melor stonehoof reason","steelsnap motive"}},{q="Where can Steelsnap be found?",a="Steelsnap prowls the dusty canyon floor of Thousand Needles, south of the centaur settlement at Camp E'thok in the northwestern reach of the zone.",al={"steelsnap location","where is steelsnap","find steelsnap"}},{q="What proof must be brought back to Thunder Bluff?",a="You must claim Steelsnap's Rib from the slain beast and present it to Melor Stonehoof atop Hunter Rise.",al={"steelsnap trophy","steelsnap objective","what do i loot"}},{q="Does Steelsnap fight alone?",a="No. Steelsnap travels accompanied by other hyenas that follow his lead, making confronting him a dangerous multi-target skirmish.",al={"is steelsnap solo","steelsnap pack","steelsnap adds"}},{q="How does this hunt differ from traditional tauren hunts?",a="While the tauren typically hunt solely for sustenance, martial honor, or spiritual insight, this hunt is purely preventative to remove a cruel beast that disrupts the natural harmony of the land.",al={"tauren hunting philosophy","earthmother hunting","hunt lesson"}},{q="Where does Melor Stonehoof dwell?",a="Melor Stonehoof resides on Hunter Rise in Thunder Bluff, where he instructs hunters and tests seasoned trackers.",al={"melor stonehoof location","where is melor","melor coords"}}},ang={["race:Tauren"]="For the Shu'halo, taking a beast's life is a spiritual matter. Hunting Steelsnap serves as an instructive lesson in culling elements of the wild that cause senseless cruelty and fall outside the Earthmother's grace.",["class:Hunter"]="Taking down Steelsnap tests a tracker's ability to isolate a savage alpha pack leader amidst wandering escorts on the canyon floor.",["faction:Horde"]="Carving a safer path through Thousand Needles protects vital supply lines and travelers crossing down from the Barrens toward Shimmering Flats."},kw={"camp e'thok","earthmother","hunter rise","hyena","melor stonehoof","steelsnap","thousand needles","thunder bluff"},rel={"npc:melor-stonehoof","quest:1130","zone:thousandneedles","subzone:hunter-rise","zone:thunderbluff","subzone:camp-e-thok","zone:barrens"},m={start="Melor Stonehoof",level="30",faction="Horde",id=1131},src={"Steelsnap (quest)"}}
E["quest:1195"] = {t="quest",n="The Sacred Flame",z="thunderbluff",s="The Sacred Flame is a Horde task initiated by Zangen Stonehoof in Thunder Bluff. Seeking to recover an ancient relic guarded by the Galak centaur in Thousand Needles, Zangen sends adventurers deep into Ashenvale to acquire a sacred moonwell phial from the local dryads.",h="The Sacred Flame is a Horde task initiated by Zangen Stonehoof in Thunder Bluff.",sec={{t="Centaur Relics and Elven Waters",b="The Galak tribe of centaur inhabiting the canyon floor of Thousand Needles fiercely protects an artifact dating back to the creation of their race. To pierce their defenses and extinguish their sacred flames, Zangen Stonehoof requires water touched by lunar divinity, drawing the tauren's gaze northward to the ancestral forests of Ashenvale.",sp=0},{t="Trespassing in Ashenvale",b="Obtaining pure moonwell water is no simple task. Unblessed vessels cannot hold the sacred liquid without corrupting its virtue, forcing Horde emissaries to hunt the Laughing Sisters near Raynewood Retreat to secure an etched phial. Once retrieved, the phial must be submerged into a moonwell along the western banks of the Falfarren River before being carried back to Mulgore.",sp=0}},faq={{q="Why does Zangen Stonehoof need moonwell water?",a="The water is intended for Zangen's associate, Rau Cliffrunner, in Thousand Needles. Rau plans to use the potent magical properties of the moonwell water to extinguish the sacred flame guarded by the hostile Galak centaur, allowing the Horde to recover an ancient relic.",al={"why moonwell water","purpose of moonwell water","why get water from ashenvale"}},{q="Where can the etched phial be found?",a="The etched phial is carried by dryads known as Laughing Sisters, who wander the woods around Raynewood Retreat in central Ashenvale, just off the northern road leading west from Splintertree Post.",al={"where is etched phial","how to get etched phial","phial location"}},{q="Which moonwell should be used to fill the phial?",a="The required moonwell sits near the western bank of the Falfarren River, south of the main road that runs across central Ashenvale.",al={"which moonwell","moonwell location","where to fill phial"}},{q="Who are the Galak centaur?",a="The Galak are an aggressive centaur clan residing in the dusty expanses of Thousand Needles. They possess an ancient relic from the founding era of their kind, surrounded by a sacred bonfire that Zangen and Rau intend to douse.",al={"galak tribe","galak centaur","who are galak"}},{q="Who receives the filled phial after Zangen?",a="Once Zangen inspects the filled phial in Thunder Bluff, he instructs the adventurer to travel south to Thousand Needles and deliver the vessel directly to Rau Cliffrunner, who requested it.",al={"who is rau","where does the water go next","next step after zangen"}},{q="Why kill dryads for their phials?",a="Dryad vessels are specially crafted to hold pure, enchanted liquids without tainting them. Ordinary bottles cannot safely transport water imbued with the celestial energies of a night elf moonwell.",al={"why attack dryads","why laughing sisters","dryad vessels"}}},ang={["race:Tauren"]="Centaur hostility has plagued the tauren for generations. Securing a relic from their race's genesis gives the tribes of Mulgore valuable insight and leverage against their bitterest foes.",["class:Druid"]="Tauren druids face an uneasy paradox on this assignment: slaying nature's daughters, the dryads, to harvest sanctified waters for a strike against the elemental flames of the centaur.",["faction:Horde"]="Stirring up trouble around Raynewood Retreat risks inflaming night elf tensions in Ashenvale, but claiming centaur relics in Thousand Needles bolsters the Horde's southern frontiers."},kw={"ashenvale","etched phial","falfarren river","galak centaur","laughing sisters","moonwell","rau cliffrunner","raynewood retreat","the sacred flame","thousand needles","zangen stonehoof"},rel={"npc:zangen-stonehoof","subzone:raynewood-retreat","subzone:falfarren-river","subzone:moonwell-ashenvale","zone:thousandneedles","zone:ashenvale","zone:thunderbluff","topic:centaur"},m={start="Zangen Stonehoof",level="25",faction="Horde",id=1195},src={"The Sacred Flame (quest)"}}
E["quest:1196"] = {t="quest",n="The Sacred Flame",z="thunderbluff",s="Following a perilous excursion to an Ashenvale moonwell, a phial of sanctified waters must be ferried south to Freewind Post. The tauren mystic Rau Cliffrunner needs this lunar essence to breach an eternal flame warding an ancient centaur relic in Thousand Needles.",h="Following a perilous excursion to an Ashenvale moonwell, a phial of sanctified waters must be ferried south...",sec={{t="A Long Journey South",b="Zangen Stonehoof's mission demands swift transit through central Kalimdor. With the etched phial brimmed with purified moonwell water, you are instructed to cross the sun-baked expanse of the Barrens, descend the towering Great Lift, and reach the high mesa settlement of Freewind Post. Waiting perched above the canyon floor is Rau Cliffrunner, who monitors the brazen centaur clans below.",sp=0},{t="Shared Blood and Ancient Wards",b="Upon receiving the phial, Rau Cliffrunner reveals why night elven holy water is vital to a tauren operation against the centaur. Because dryads and centaur share common ancestry through the demigod Cenarius, whose son Zaetar fathered the centaur, the sacred water of the moonwells carries an arcane resonance. This connection makes it the only element capable of piercing the protective eternal flame shielding a guarded centaur artifact.",sp=1}},faq={{q="Where is Rau Cliffrunner located?",a="Rau Cliffrunner resides atop Freewind Post in Thousand Needles. To reach him, head south through the Barrens, descend via the Great Lift into the canyon, and follow the southeastern trail to the elevator hoisted high onto the sheer mesa needle.",al={"where is rau","rau cliffrunner location","find rau cliffrunner","freewind post turn in"}},{q="Why does Rau need moonwell water to combat centaur?",a="Centaur and dryads share a common lineage tracing back to the offspring of Cenarius. Because of this ancestral kinship, the sanctified waters of a night elf moonwell possess the specific magical harmony needed to dismantle the eternal flame defending the centaurs' sacred relic.",al={"why moonwell water","moonwell and centaur connection","dryad centaur relationship"}},{q="Who sent me with the phial?",a="Zangen Stonehoof tasked you with transporting the Filled Etched Phial after obtaining water from the guarded moonwell in Ashenvale.",al={"who gave this quest","zangen stonehoof","quest giver sacred flame 2"}},{q="What happens after giving the phial to Rau?",a="Once Rau confirms the waters are intact, he tasks you with using the phial's power directly to quench the flame and retrieve the centaur relic from the nearby canyon.",al={"next quest","what after rau","sacred flame part 3"},sp=1},{q="How do I get down into Thousand Needles?",a="Follow the main southern road through the Barrens until you hit the cliff edge. There you will find the Great Lift, a pair of wooden elevators operated by tauren pulleys that carry travelers down onto the canyon floor.",al={"how to reach thousand needles","getting past the barrens cliff","great lift directions"}},{q="Why are the tauren seeking a centaur relic?",a="The tauren and centaur have fought a brutal war across Kalimdor for generations. Disrupting their rites and seizing their sacred artifacts weakens the warlike clans entrenched across the Thousand Needles canyon.",al={"tauren centaur war","why steal centaur relic"}}},ang={["race:Tauren"]="Every blow against the centaur protects Mulgore and the newly secured borders of your homeland.",["class:Druid"]="Rau Cliffrunner relies on deep knowledge of Cenarion bloodlines to untangle the magical resonance between dryads and centaur.",["faction:Horde"]="Delivering this phial reinforces Freewind Post, the Horde's high outpost in the perilous canyon passes of Thousand Needles."},kw={"centaur relic","etched phial","freewind post","great lift","rau cliffrunner","sacred flame","thousand needles","zangen stonehoof"},rel={"npc:rau-cliffrunner","npc:zangen-stonehoof","subzone:freewind-post","subzone:great-lift","zone:thousandneedles","topic:centaur","subzone:moonwell-ashenvale","zone:barrens"},m={start="Zangen Stonehoof",["end"]="Rau Cliffrunner",level="29",faction="Horde",id=1196},src={"The Sacred Flame (2)"}}
E["quest:1197"] = {t="quest",n="The Sacred Flame",z="thunderbluff",s="The Sacred Flame is the final task in Rau Cliffrunner's investigation into the Galak centaur of Thousand Needles. Armed with blessed waters, a Horde adventurer must penetrate Splithoof Hold, extinguish the tribe's revered brazier, and claim the ancient Cloven Hoof relic.",h="The Sacred Flame is the final task in Rau Cliffrunner's investigation into the Galak centaur of Thousand...",sec={{t="Striking the Hearth",b="North of Freewind Post lies Splithoof Crag, the heart of the Galak centaur domain in Thousand Needles. Deep within its cavernous den, Splithoof Hold, burns a fire that the centaur hold sacred. After preparing an etched phial filled with purified water, Rau Cliffrunner tasks his allies with penetrating the subterranean stronghold, using the water to momentarily quench the flame, and snatching the prize guarded within: a relic known as the Cloven Hoof.",sp=0},{t="Secrets of the Hoof",b="The Cloven Hoof is not merely an ornament of war; it radiates a strange, potent energy that catches Rau Cliffrunner's mystical senses the moment it is brought before him. Tauren scholars have long fought the marauding centaur tribes across Kalimdor, but relics such as this hint at deeper, poorly understood forces that fuel their zeal and tribal unity.",sp=1}},faq={{q="Where is the sacred flame located?",a="The flame burns at the deepest end of Splithoof Hold, a cavern situated inside the centaur camp at Splithoof Crag, directly north of Freewind Post in Thousand Needles.",al={"splithoof hold location","where is sacred flame","flame cave thousand needles"}},{q="Who asks you to douse the flame?",a="Rau Cliffrunner, an elder stationed high atop Freewind Post, commissions the mission as the culmination of his research into the Galak centaur.",al={"quest giver sacred flame","rau cliffrunner location","who gives the quest"}},{q="How do you put out the flame?",a="You must use the Filled Etched Phial provided by Rau Cliffrunner, which contains water gathered earlier in the quest chain, to temporarily douse the brazier.",al={"how to get cloven hoof","dousing flame item","quench sacred flame"}},{q="What is the Cloven Hoof?",a="The Cloven Hoof is a venerated tribal relic kept inside the flame by the Galak centaur. Rau Cliffrunner detects an unusual magical energy emanating from it, hoping it will yield secrets about centaur culture and power.",al={"cloven hoof lore","centaur relic","what did we steal"}},{q="Why do the tauren want this relic?",a="Centaur tribes have driven tauren from their ancestral hunting grounds for generations. By seizing a sacred heirloom, the tauren disrupt Galak operations while seeking to understand the arcane or spiritual nature behind their enemies' savagery.",al={"why steal cloven hoof","tauren centaur war"}},{q="Which centaur clan guards Splithoof Hold?",a="Splithoof Crag and its cavern hold are controlled by the Galak tribe, the predominant centaur clan inhabiting the Thousand Needles canyon floor.",al={"thousand needles centaur tribe","galak centaur"}}},ang={["race:Tauren"]="For the tauren, striking into the heart of a centaur den and claiming their sacred icon is both retribution for generations of raids and an invaluable scholarly prize for Freewind Post.",["class:Shaman"]="Shaman who handle the Cloven Hoof will easily detect the strange energies radiating from the talisman, proving the centaur draw on mystical forces far beyond simple brute savagery."},kw={"centaur","cloven hoof","freewind post","galak","rau cliffrunner","sacred flame","splithoof crag","splithoof hold","thousand needles"},rel={"npc:rau-cliffrunner","subzone:splithoof-hold","subzone:splithoof-crag","subzone:freewind-post","topic:centaur","quest:1195"},m={start="Rau Cliffrunner",["end"]="Rau Cliffrunner",level="29",faction="horde",id=1197},src={"The Sacred Flame (3)"}}
E["quest:1205"] = {t="quest",n="Deadmire",z="thunderbluff",s="Deadmire is a hunting rite offered by the tauren hunter Melor Stonehoof on Hunter Rise in Thunder Bluff. The task sends hunters east into Dustwallow Marsh to track and slay an ancient, suffering crocolisk named Deadmire, bringing back its tooth as proof. It serves as an exercise in both challenging tracking and the hunter's duty of mercy.",h="Deadmire is a hunting rite offered by the tauren hunter Melor Stonehoof on Hunter Rise in Thunder Bluff.",sec={{t="A Hunt of Mercy",b="On Hunter Rise in Thunder Bluff, Melor Stonehoof instructs promising trackers in the deeper spiritual traditions of the hunt. Unlike thoughtless slaughter or trophy gathering, tauren hunting philosophy teaches reverence and connection with the natural world. Melor tasks hunters with journeying far eastward to the murky wetlands of Dustwallow Marsh to seek out Deadmire, an ancient crocolisk of immense scale whose prolonged life has turned into an agonizing burden.",sp=0},{t="The Ancient of the Marsh",b="Deadmire is no ordinary beast; he is a massive, pale crocolisk who prowls the waterways north of the Stonemaul Ruins. While his youthful fury and physical power linger in sudden bursts, his aging frame is worn down by grinding bones and unrelenting pain. Melor charges hunters to grant the creature an honorable, swift end, putting its spirit to rest and claiming a single tooth as a token of the beast's release.",sp=0}},faq={{q="Who is Deadmire?",a="Deadmire is a massive, ancient white crocolisk living in the swamps of Dustwallow Marsh. Though still dangerously powerful, he suffers from excruciating physical agony due to his failing, aged body.",al={"what is deadmire","deadmire lore","who is the crocolisk"}},{q="Why does Melor Stonehoof want Deadmire killed?",a="Melor views the hunt as an act of mercy rather than conquest. Deadmire's aging bones cause him maddening pain, and the tauren hunter believes it is a sacred duty to release the noble beast's spirit and grant him peace.",al={"why kill deadmire","melor stonehoof motive","purpose of deadmire hunt"}},{q="Where can Deadmire be found?",a="Deadmire haunts the murky waters and islands of Dustwallow Marsh, typically found wandering the riverways just north of the Stonemaul Ruins.",al={"where is deadmire","deadmire location","finding deadmire"}},{q="What proof does Melor require from the hunt?",a="Melor asks you to bring back Deadmire's Tooth as proof that the mighty creature's suffering has finally been brought to an end.",al={"deadmire quest item","what does melor want","deadmire proof"}},{q="What does this hunt teach aspiring hunters?",a="The hunt teaches that the way of the hunter is not mindless killing, but spiritual communion with nature. Part of that calling involves recognizing when a creature's life has turned to suffering and delivering a merciful, honorable death.",al={"hunter philosophy","tauren hunting lesson","meaning of the hunt"}},{q="Who gives this quest?",a="The quest is offered by Melor Stonehoof, a hunter trainer found on Hunter Rise overlooking the city of Thunder Bluff.",al={"deadmire quest giver","who starts deadmire","melor stonehoof location"}}},ang={["class:Hunter"]="For hunters, tracking Deadmire embodies the balance between martial prowess and spiritual responsibility, emphasizing that an honorable kill can be an act of grace.",["race:Tauren"]="The hunt reflects core tauren values of harmony with the Earth Mother's creatures, teaching that a true hunter honors the prey and respects the natural cycles of life and death.",["faction:Horde"]="Undertaking hunts for the elders of Thunder Bluff helps bind Horde travelers to the land and the spiritual traditions of their tauren allies."},kw={"crocolisk","deadmire","dustwallow marsh","hunter rise","melor stonehoof","stonemaul ruins","thunder bluff"},rel={"npc:melor-stonehoof","zone:thunderbluff","zone:dustwallow","subzone:stonemaul-ruins"},m={start="Melor Stonehoof",faction="Horde",id=1205},src={"Deadmire (quest)"}}
E["quest:1529"] = {t="quest",n="Call of Water",z="thunderbluff",s="Call of Water is an initiation rite that directs rising Horde shaman from the heights of Thunder Bluff toward the eastern shores of the Barrens. To commune with the cleansing element of water, an initiate must seek out the recluse Islen Waterseer. This meeting marks the first step on a spiritual journey to earn the Water Totem.",h="Call of Water is an initiation rite that directs rising Horde shaman from the heights of Thunder Bluff toward...",sec={{t="A Summons from the Bluff",b="Having mastered the unyielding earth and the untamed flame, an aspiring shaman is eventually deemed ready to study the deeper mysteries of the elements. In Thunder Bluff, trainers like Xanis Flameweaver recognize when a student has shown enough discipline to approach the fluid, cleansing spirit of water. The journey requires leaving the windswept mesas of Mulgore behind and traveling east across the sun-scorched plains of the Barrens.",sp=0},{t="The Hermit of the Coast",b="The path leads to Islen Waterseer, a quiet mystic who lives away from the bustling settlements, residing in a humble fishing shack on the eastern coast south of Ratchet and the mouth of the Southfury River. Standing at the edge of the great ocean, Islen reads the readiness of travelers by how the elements linger about them. Seeing the steady earth, the brisk wind, and the warmth of fire already bound to the seeker's spirit, she prepares them for the trials required to understand water's purity.",sp=0}},faq={{q="Who sends me on this journey?",a="Shaman trainers in Thunder Bluff, such as Xanis Flameweaver, bestow this quest once an initiate has advanced far enough in their spiritual training to pursue the rites of water.",al={"quest giver","who starts call of water","where to get call of water tb"}},{q="Where is Islen Waterseer located?",a="Islen Waterseer lives in a lonely fishing hut on the eastern coast of the Barrens. Her dwelling sits along the shore south of Ratchet and south of where the Southfury River meets the sea.",al={"where is islen waterseer","islen location","find islen"}},{q="What is the purpose of the Call of Water trial?",a="The trial is an essential rite of passage for every shaman seeking communion with water. It tests the initiate's understanding of elemental purity and leads directly to earning their Water Totem.",al={"why do call of water","call of water purpose","shaman water totem quest"}},{q="Do other Horde races receive this same instruction?",a="While the introductory summons in Thunder Bluff is typically taken by tauren, orc and troll shaman in Orgrimmar and Sen'jin receive similar calls to seek out Islen Waterseer on the Barrens coast.",al={"is this only for tauren","orc call of water","troll call of water"}},{q="What elements must a shaman master before water?",a="A shaman communes with the steady earth and the destructive yet life-giving fire before seeking the fluid nature of water. As Islen notes upon your arrival, earth, wind, and fire must already touch your spirit before water will reveal its purity.",al={"prerequisites","which totems first","elemental order"}},{q="What happens after finding Islen Waterseer?",a="Speaking with Islen concludes the initial journey from Thunder Bluff. She will immediately challenge you with further tasks across Kalimdor to understand and purify the element of water directly.",al={"what next","after finding islen","call of water part 2"}}},ang={["class:Shaman"]="This rite marks the transition from early elemental trials toward mastering the fluid powers of cleansing, restoration, and tide.",["race:Tauren"]="Starting in Thunder Bluff, this task carries young shu'halo shaman out from Mulgore's sheltered plains into the wider expanse of Kalimdor.",["faction:Horde"]="Shamanism remains a bedrock of the new Horde, linking ancient traditions across orc, troll, and tauren spiritualists."},kw={"barrens","call of water","islen waterseer","ratchet","shaman","southfury river","thunder bluff","water totem","xanis flameweaver"},rel={"npc:islen-waterseer","zone:barrens","subzone:ratchet","subzone:southfury-river"},m={start="Xanis Flameweaver",["end"]="Islen Waterseer",level="20",faction="Horde",id=1529},src={"Call of Water (Thunder Bluff)"}}
E["quest:1532"] = {t="quest",n="Call of Air",z="thunderbluff",s="Call of Air marks a major milestone in a Horde shaman's spiritual path, directing them to seek communion with the unpredictable element of wind. Offered by Xanis Flameweaver in Thunder Bluff, this quest bids seasoned initiates journey south into Thousand Needles to learn from Prate Cloudseer. Mastering air grants a shaman the sacred totem required to channel the swiftest forces of nature.",h="Call of Air marks a major milestone in a Horde shaman's spiritual path, directing them to seek communion with...",sec={{t="The Whispering Winds",b="Having already attuned to the stability of earth, the ferocity of fire, and the restorative depths of water, a shaman reaches the final elemental pillar: air. Xanis Flameweaver, guiding practitioners from the heights of Thunder Bluff, acknowledges that the winds are far more fickle and difficult to control than the previous elements. The trial demands humility, focus, and an innate respect for the sky's tempestuous nature.",sp=0},{t="A Pilgrimage South",b="To attune to the winds, the shaman must travel south past the vast plains of the Barrens and descend into the wind-carved canyons of Thousand Needles. There, far to the east, dwells the hermit mystic Prate Cloudseer. Tucked away in a secluded cliffside cave where the canyon drafts howl day and night, she tests the initiate's preparedness before bestowing the Air Totem, the instrument essential for summoning gusts, lightning, and swift wind spirits.",sp=0}},faq={{q="Who sends me on this quest?",a="Xanis Flameweaver, a shaman trainer situated in Thunder Bluff, offers this quest once an initiate reaches sufficient experience to attune to the element of air.",al={"quest giver","who starts call of air","xanis flameweaver"}},{q="Where is Prate Cloudseer located?",a="Prate Cloudseer resides in a sheltered cave far to the east within the windblown canyon of Thousand Needles, just south of the Barrens.",al={"prate cloudseer location","where is prate","find prate cloudseer"}},{q="Why is the element of air sought last?",a="Air is notoriously erratic, sudden, and elusive. Shamanic tradition requires an initiate to first master the grounded stability of earth, the volatile warmth of fire, and the fluidity of water before attempting to anchor the wild, invisible currents of wind.",al={"why air last","shaman air totem lore","elemental order"}},{q="What do I receive upon finding Prate Cloudseer?",a="Prate Cloudseer presents you with the Air Totem, the spiritual conduit that allows you to focus your elemental magic and call upon the air spirits for support.",al={"air totem reward","what does prate give","quest reward call of air"}},{q="Is this quest exclusive to Tauren?",a="While started in the Tauren capital of Thunder Bluff, any Horde shaman who has attuned to the first three elements may take this path to Thousand Needles to claim their Air Totem.",al={"can orcs do this","is this tauren only","horde shaman air quest"}},{q="What happens after finishing this quest?",a="Prate Cloudseer bestows your Air Totem upon arrival, allowing you to invoke wind-based totems immediately, and offers further training and trials to hone your connection with the sky.",al={"what comes next","after call of air","prate cloudseer quests"}}},ang={["class:Shaman"]="The completion of your elemental set is a profound turning point, giving you access to the swift currents and lightning-wreathed powers of the Air Totem.",["faction:Horde"]="By binding the wild winds of Kalimdor into a sacred totem, Horde shamans strengthen the spiritual backbone of their fledgling alliance.",["race:Tauren"]="Gazing down from the towering bluffs of Mulgore, the shu'halo revere the winds as sacred messengers, carrying the whispers of the Earth Mother across the plains."},kw={"air totem","call of air","prate cloudseer","shaman","thousand needles","thunder bluff","xanis flameweaver"},rel={"zone:thousandneedles","zone:barrens"},m={start="Xanis Flameweaver",["end"]="Prate Cloudseer",level="30",faction="Horde",id=1532},src={"Call of Air (Thunder Bluff)"}}
E["quest:1718"] = {t="quest",n="The Islander",z="thunderbluff",s="The Islander is an invitation extended by veteran warrior trainers across Azeroth to those who have proven their basic mettle in battle. It directs rising fighters to Fray Island off the Merchant Coast, where an insular brotherhood of warriors tests their peers in raw martial combat. Meeting the chief warrior Klannoc Macleod marks a pivotal step toward mastering advanced combat disciplines.",h="The Islander is an invitation extended by veteran warrior trainers across Azeroth to those who have proven...",sec={{t="A Gathering of Blades",b="Warrior trainers in capital cities across both the Alliance and the Horde recognize when a student has outgrown basic drills. Rather than formal rank or political loyalty, martial progression demands that combatants measure themselves against true peers. The journey sends warriors away from civilized sparring yards toward a rugged isle isolated in the Great Sea.",sp=0},{t="Fray Island and the Merchant Coast",b="Fray Island sits east off the Merchant Coast, just south of the goblin port of Ratchet in the Barrens. It is reached by swimming the waters over submerged sandbar shallows. On this rock, political ties dissolve in favor of martial fraternity; fighters gather under the gaze of Klannoc Macleod, the chief warrior on the isle, awaiting whatever brutal trial he deems necessary.",sp=0}},faq={{q="What is Fray Island?",a="Fray Island is a rocky outcrop located off the Merchant Coast of the Barrens, south of Ratchet. It serves as an isolated proving ground where warriors from across Azeroth gather to hone their craft, spar, and face grueling combat trials away from civil authority.",al={"where is fray island","fray island lore","fray isle"}},{q="Who is Klannoc Macleod?",a="Klannoc Macleod is the chief warrior presiding over Fray Island. He assesses hopeful contenders who make the journey to the island, deciding whether their spirit and skill are worthy of being guided further along the warrior's path.",al={"who is klannoc","klannoc macleod role","macleod warrior"}},{q="Why do trainers from both Horde and Alliance send warriors here?",a="True martial mastery transcends faction boundaries. Master trainers in Orgrimmar, Stormwind, Thunder Bluff, and Ironforge recognize that raw martial skill must be tested in unbridled combat, and Fray Island exists as an unspoken proving ground for any warrior capable of surviving its challenges.",al={"why do both factions go here","is fray island neutral","horde and alliance fray island"}},{q="How do you reach Fray Island from the mainland?",a="Travel south along the Merchant Coast from the port town of Ratchet in the Barrens. From the shoreline, navigate the sandbar shallows and swim east across the open water toward the island.",al={"how to get to fray island","fray island directions","finding fray island"}},{q="What happens after meeting Klannoc Macleod?",a="Once Klannoc confirms you have made the journey and evaluates your resolve, he invites you to participate in The Affray—a gauntlet designed to test your combat stamina against waves of challengers.",al={"what comes after the islander","klannoc macleod next quest"},sp=1}},ang={["class:Warrior"]="This rite of passage is exclusive to warriors, marking the crucial transition from learning basic maneuvers to unlocking the full ferocity and tactical versatility of veteran stances.",["faction:Horde"]="Starting from Thunder Bluff or Orgrimmar, Horde warriors journey down to the Barrens to prove their strength beyond the watchful eyes of their chieftains.",["faction:Alliance"]="Alliance warriors must journey across the sea or through Kalimdor's wilderness to reach Fray Island, demonstrating martial devotion in a rugged frontier far from human and dwarven strongholds."},kw={"fray island","klannoc macleod","merchant coast","ratchet","the affray","the barrens","the islander","warrior"},rel={"subzone:fray-island","npc:klannoc-macleod","quest:1719","subzone:merchant-coast","subzone:ratchet","zone:barrens","quest:92532"},m={start="Wu Shen, Kelv Sternhammer  Baltus Fowler, Torm Ragetotem, Sorek",["end"]="Klannoc Macleod",level="30",id=1718},src={"The Islander"}}
E["quest:1840"] = {t="quest",n="Orm Stonehoof and the Brutal Helm",z="thunderbluff",s="This errand directs rising Horde warriors to Thunder Bluff to consult with Orm Stonehoof, an artisan smith. Recommended by Thun'grim Firegaze, Orm possesses the specialized craft required to forge the Brutal Helm.",h="This errand directs rising Horde warriors to Thunder Bluff to consult with Orm Stonehoof, an artisan smith.",sec={{t="A Recommendation in Iron",b="After proving their mettle and assembling pieces of the Brutal Armor in the Barrens, warriors are directed higher into the mesa city of Thunder Bluff. Thun'grim Firegaze, an accomplished armorsmith himself, recognizes his limits and refers his champions to Orm Stonehoof. Orm's craft is renowned throughout Kalimdor, specifically his ability to mold resilient battlefield helms from rare, savage trophies.",sp=0},{t="The Artisan by the Pool",b="Orm makes his home and workplace on the high bluffs of Mulgore, standing near the tranquil waters beneath the city's towering central totem. When a warrior arrives carrying word from Thun'grim, Orm steps away from routine work to discuss the demanding components needed to forge headgear truly worthy of the Horde's front lines.",sp=0}},faq={{q="Who is Orm Stonehoof?",a="Orm Stonehoof is a skilled tauren armorsmith residing in Thunder Bluff. Known for his craftsmanship, he aids warriors sent by Thun'grim Firegaze in crafting specialized battle headgear.",al={"orm stonehoof","who is orm"}},{q="Where can Orm Stonehoof be found?",a="He is located in the heart of Thunder Bluff, standing near the pool of water close to the city's massive central totem.",al={"where is orm","orm stonehoof location","find orm"}},{q="Why does Thun'grim Firegaze send you to Thunder Bluff?",a="While Thun'grim can craft the chestpiece and other elements of the Brutal set, he acknowledges that Orm Stonehoof possesses the precise expertise needed to fashion the Brutal Helm.",al={"why thunder bluff","why see orm"}},{q="What is the Brutal Helm?",a="The Brutal Helm is an iconic piece of headgear forged for Horde warriors reaching veteran standing. It requires dangerous materials sourced from beasts across Kalimdor.",al={"brutal helm quest","what is brutal helm"}},{q="What does Orm ask for next?",a="Once you speak with Orm, he directs you to gather the necessary beast trophies for the helm, beginning with hunting chimaeras in the wild to claim a Chimaeric Horn.",al={"next quest","after orm stonehoof","chimaeric horn quest"},sp=1},{q="Can any class take this quest?",a="No. This quest line is exclusive to warriors who have advanced far enough in their martial training and completed Thun'grim's initial armor tasks.",al={"is this warrior only","who can do this quest"}}},ang={["class:Warrior"]="This quest marks the transition into heavyweight head protection, sending warriors to one of the Horde's finest master smiths.",["faction:Horde"]="The quest illustrates the cooperation between orcish weaponmasters in the Barrens and tauren craftsmen high atop Thunder Bluff."},kw={"armor quest","brutal helm","orm stonehoof","thun'grim firegaze","thunder bluff","warrior"},rel={"quest:1838","quest:1845","quest:1844","quest:1502","zone:thunderbluff"},m={start="Thun'grim Firegaze",["end"]="Orm Stonehoof",level="30",faction="Horde",id=1840},src={"Orm Stonehoof and the Brutal Helm"}}
E["quest:1844"] = {t="quest",n="Chimaeric Horn",z="thunderbluff",s="As part of the warrior rite to craft the Brutal Helm, Orm Stonehoof tasks an aspiring champion with journeying into the ruined Charred Vale. There, the warrior must hunt a maddened chimaera matriarch to claim her galvanized horn as both an act of mercy and proof of strength.",h="As part of the warrior rite to craft the Brutal Helm, Orm Stonehoof tasks an aspiring champion with...",sec={{t="A Test of Resolve",b="Orm Stonehoof is willing to forge the legendary Brutal Helm for Horde warriors, but martial tradition demands that the wearer prove their mettle first. Orm does not simply ask for raw metal or coin; he demands proof of martial prowess and a willingness to confront the grim scars left behind by devastating conflict.",sp=0},{t="The Scars of the Charred Vale",b="The quest directs warriors to the southwestern reaches of the Stonetalon Mountains, into the ashen desolation known as the Charred Vale. Once lush and green, the valley was burned into a smoking wasteland. The surviving beasts wandering its soot-covered craters are twisted by agony and fury, particularly the mighty chimaeras that make their nests amid the dead trees and searing steam vents.",sp=0},{t="Mercy in Combat",b="Slaying a chimaera matriarch serves two purposes in the tauren smith's eyes. It claims the hardened, galvanized horn required for crafting the headpiece, but it also ends the creature's torment. By felling the matriarch, the warrior acts both as an executioner and an instrument of mercy for a wild spirit driven mad by the destruction of its home.",sp=0}},faq={{q="Who is Orm Stonehoof?",a="Orm Stonehoof is a skilled tauren blacksmith residing in Thunder Bluff who assists veteran Horde warriors in crafting iconic pieces of their class armor, including the Brutal Helm.",al={"orm stonehoof lore","who is orm stonehoof","thunder bluff blacksmith orm"}},{q="Why does Orm want the galvanized horn?",a="The galvanized horn serves as both a durable physical component for the Brutal Helm and tangible proof that the warrior possesses the courage to track and defeat a dangerous alpha predator in hazardous terrain.",al={"galvanized horn use","why get galvanized horn","brutal helm horn"}},{q="What are chimaeras in Stonetalon?",a="Chimaeras are large, two-headed winged drakes native to the wilds of Kalimdor, often bound to ancient night elf sanctuaries. The ones surviving in the Charred Vale have been driven violently insane by the fire and destruction of their nesting grounds.",al={"stonetalon chimaeras","chimaera lore","what are chimaeras"}},{q="How does this quest fit into warrior training?",a="Around their thirtieth season, Horde warriors are directed toward specialists like Orm Stonehoof to undergo dangerous trials. Completing these challenges allows them to wear the heavy, spiked Brutal armor set designed for battlefield champions.",al={"warrior brutal helm chain","level 30 warrior quest thunder bluff","brutal armor questline"}},{q="Why does Orm frame the hunt as an act of mercy?",a="Tauren culture emphasizes harmony with the earth and its creatures. Because the Charred Vale's inhabitants are in unrelenting agony from the devastation of their land, slaying the matriarch is seen as putting a suffering beast out of its unending misery rather than mindless slaughter.",al={"why mercy for the matriarch","free her of her misery"}}},ang={["class:Warrior"]="This trial tests a warrior's ability to hunt down solitary alpha beasts in brutal environments, earning the right to bear the Brutal Helm.",["race:Tauren"]="Orm Stonehoof approaches warfare with tauren reverence, reminding warriors that even in violence, putting a tormented beast out of its suffering honors the Earth Mother.",["faction:Horde"]="Horde warriors operating out of Sun Rock Retreat push deep into Stonetalon's contested wilds to forge the arms needed for Kalimdor's defense."},kw={"brutal helm","charred vale","chimaera matriarch","chimaeric horn","galvanized horn","orm stonehoof","stonetalon","thunder bluff","warrior quest"},rel={"quest:1840","zone:thunderbluff","subzone:charred-vale","zone:stonetalon","subzone:sun-rock-retreat"},m={start="Orm Stonehoof",level="30",faction="Horde",id=1844},src={"Chimaeric Horn"}}
E["quest:1845"] = {t="quest",n="Brutal Helm",z="thunderbluff",s="Brutal Helm marks the culmination of an arduous warrior trial overseen by Orm Stonehoof atop Thunder Bluff. Having collected rare beast trophies across Kalimdor, an aspiring warrior is recognized with a formidable horned helm as a testament to their strength.",h="Brutal Helm marks the culmination of an arduous warrior trial overseen by Orm Stonehoof atop Thunder Bluff.",sec={{t="A Warrior's Rite",b="Orm Stonehoof serves as a stern smith in Thunder Bluff, guiding Horde warriors through grueling rites of passage. These trials demand proof of martial capability, pushing initiates into treacherous territory to hunt ferocious creatures and claim rare trophies. Only those who have met Orm's exacting standards are granted audience for the completion of their armor.",sp=0},{t="The Gift of the Earthmother",b="By bringing the rare chimaeric horn to Orm Stonehoof, the warrior proves their resolve against the wilderness. In recognition, Orm presents the Brutal Helm—a heavy, menacing piece of plate crafted to honor the beast and bolster the wearer in frontline combat. As he bestows it, Orm invokes the blessings of the Earthmother, looking forward to the greater deeds the warrior is bound to undertake across Azeroth.",sp=0}},faq={{q="Who offers the Brutal Helm?",a="Orm Stonehoof, a venerable tauren blacksmith in Thunder Bluff, presents the Brutal Helm to Horde warriors who complete his trials.",al={"who gives brutal helm","brutal helm npc","orm stonehoof quest"}},{q="What task must be finished before receiving the helm?",a="You must complete the trial 'Chimaeric Horn', which requires hunting ferocious beasts across the wilderness and delivering their horn to Orm Stonehoof in Thunder Bluff.",al={"prereq for brutal helm","chimaeric horn quest"}},{q="Where is Orm Stonehoof located?",a="Orm Stonehoof is located near the pool by the great central totem in the high mesa city of Thunder Bluff.",al={"orm stonehoof location","where is orm stonehoof"}},{q="Why does Orm Stonehoof invoke the Earthmother?",a="As a tauren, Orm honors the Earthmother as the creator and spiritual guardian of the world. Offering her blessing over a warrior's finished helm reflects the traditional tauren belief that strength in battle must remain balanced with spiritual reverence.",al={"why mention earthmother","earthmother lore"}},{q="Is this trial open to any adventurer?",a="No. The trial and its Brutal Armor rewards are exclusive to Horde warriors proving their mettle through dedicated class quests.",al={"can anyone get brutal helm","brutal helm class"}},{q="What is the significance of the Brutal Armor set?",a="The Brutal Armor pieces represent a warrior's progression from a novice soldier to an elite champion of the Horde, crafted using materials gathered from the fiercest predators in Kalimdor.",al={"brutal armor lore","why is it called brutal helm"}}},ang={["class:Warrior"]="This rite serves as a key milestone for Horde warriors, transitioning them into heavy armor forged from ferocious beasts and blessed by seasoned veteran trainers.",["race:Tauren"]="Bestowed in Thunder Bluff, the helm reflects the tauren tradition of crafting hunting trophies into protective wargear under the grace of the Earthmother.",["faction:Horde"]="The Brutal Armor trial ensures that champions fighting beneath the Horde banner possess the raw physical endurance and hunting prowess demanded by their leaders."},kw={"brutal helm","chimaeric horn","earthmother","hunter rise","orm stonehoof","thunder bluff","warrior"},rel={"quest:1844"},m={start="Orm Stonehoof",level="30",faction="Horde",id=1845},src={"Brutal Helm (quest)"}}
E["quest:1959"] = {t="quest",n="Report to Anastasia",z="thunderbluff",s="Report to Anastasia is a summons issued to developing Horde mages across Kalimdor and the Eastern Kingdoms. Anastasia Hartwell, a prominent arcanist in the Undercity's Magic Quarter, has detected an unknown magical disturbance within the city and requires capable spellcasters to investigate.",h="Report to Anastasia is a summons issued to developing Horde mages across Kalimdor and the Eastern Kingdoms.",sec={{t="A Call to the Arcane",b="Word travels quickly through the ranks of Horde spellcasters. Whether studying atop the bluffs of Thunder Bluff, in the dusty heat of Durotar, or amid the ruins of Lordaeron, mages of sufficient talent receive a clear directive. The arcane practitioners of the Undercity have sensed an unexplainable disturbance rippling through their domain, and they require assistance on the ground.",sp=0},{t="The Mage of the Undercity",b="Anastasia Hartwell oversees matters of the arcane from the Magic Quarter of the Undercity. Upon arrival, she confirms the unsettling news: anomalous energies have been registered within the subterranean metropolis. Because the nature of the magic remains entirely unknown—neither proven to be benign nor overtly hostile—she needs an adept to quietly investigate its source, starting within the city's Apothecarium.",sp=0}},faq={{q="Who is Anastasia Hartwell?",a="Anastasia Hartwell is a Forsaken mage and arcane mentor stationed in the Magic Quarter of the Undercity. She guides fledgling practitioners and keeps a watchful eye over arcane abnormalities occurring within the Forsaken capital.",al={"anastasia hartwell lore","who is anastasia","hartwell undercity"}},{q="Where is Anastasia Hartwell located?",a="She resides in the Magic Quarter of the Undercity, located in the northern arc of the subterranean city. She can be found among the other spellcasting trainers and arcane researchers.",al={"where is anastasia","hartwell location","anastasia undercity map"}},{q="Why are mages from Thunder Bluff or the Barrens being summoned to the Undercity?",a="While the Forsaken cultivate their own arcane specialists, unusual magical anomalies threaten the entire Horde presence in Lordaeron. Mentors in Kalimdor send their promising pupils to the Undercity to offer aid and gain practical experience with complex magical phenomena.",al={"why travel to undercity","why report to anastasia","thunder bluff mage quest"}},{q="What kind of disturbance is Anastasia investigating?",a="The mages detected unexplained magical fluctuations within the city. At the time of this summons, Anastasia Hartwell has not yet determined whether the energy is hostile, accidental, or benign, prompting her to initiate a careful inquiry.",al={"what disturbance","magical disturbance undercity","what is wrong in undercity"}},{q="Who gives this quest?",a="Various Horde mage trainers can initiate this summons once a spellcaster gains enough experience, including Uthel'nay in Orgrimmar, Thurston Xane in Thunder Bluff, Cain Firesong in Brill, and Un'Thuwa in Sen'jin Village.",al={"who starts report to anastasia","quest starters report to anastasia"}},{q="What happens after reporting to Anastasia?",a="Once you speak with Anastasia and receive your briefing, she immediately directs you to look deeper into the disturbance, beginning with an inquiry into the city's Apothecarium in the quest Investigate the Alchemist Shop.",al={"next quest after report to anastasia","report to anastasia follow up"}}},ang={["class:Mage"]="This task marks an important milestone for Horde mages, drawing practitioners out of regional training outposts and introducing them to the deeper arcane mysteries—and hazards—brewing beneath the ruins of Lordaeron.",["faction:Horde"]="The summons demonstrates the collaborative exchange between the Forsaken and the broader Horde, utilizing magical talents across all member races to safeguard their shared interests.",["race:Undead"]="Forsaken mages are called home to the Undercity's Magic Quarter to help secure their young kingdom against unseen arcane threats inside its own walls."},kw={"anastasia hartwell","cain firesong","investigate the alchemist shop","mage","magic quarter","report to anastasia","thurston xane","un'thuwa","undercity","uthel'nay"},rel={"npc:anastasia-hartwell","quest:1960","subzone:magic-quarter","zone:undercity","quest:1881","topic:horde"},m={start="Uthel'nay, Cain Firesong, Thurston Xane, or Un'Thuwa",["end"]="Anastasia Hartwell",level="15",faction="Horde",id=1959},src={"Report to Anastasia"}}
E["quest:26"] = {t="quest",n="A Lesson to Learn",z="thunderbluff",s="A Lesson to Learn is a rite of passage for young tauren druids ready to claim command over the water. Issued atop the heights of Thunder Bluff by Turak Runetotem, the quest directs students to Nighthaven in Moonglade to begin their trials under the tutelage of the Cenarion Circle.",h="A Lesson to Learn is a rite of passage for young tauren druids ready to claim command over the water.",sec={{t="Mastery of the Depths",b="After gaining command of raw physical might through the bear, a druid's studies turn toward adaptability. The waterways of Azeroth present perilous hazards to landbound travelers, demanding an aspect suited to cold depths and crushing currents. Turak Runetotem watches his students closely, choosing only those who have proven their dedication to nature before sending them north to study the aquatic form.",sp=0},{t="The Road to Nighthaven",b="Because aquatic shape-shifting requires deep spiritual insight, initiates must seek guidance outside the bluffs of Mulgore. Turak bids his pupils travel to Moonglade, the sacred sanctuary sheltered beneath Mount Hyjal. There, in the peaceful haven of Nighthaven, ancient night elf mentors of the Cenarion Circle welcome tauren brothers and sisters, transcending factional strife to preserve the shared teachings of Cenarius.",sp=0},{t="The Dual Trials",b="Reaching Dendrite Starblaze in Nighthaven marks only the beginning. The night elf elder cautions that mastery over the waters cannot simply be given—it must be earned through trial. He warns candidates that two grueling tests await them: one testing endurance and composure while working under watery pressure, and another demanding a deep spiritual understanding of the aquatic aspect itself.",sp=0}},faq={{q="Who gives the quest A Lesson to Learn?",a="The quest is given by Turak Runetotem, the druid trainer residing on the Elder Rise in Thunder Bluff. Once an initiate reaches sufficient experience, he sends them to seek advanced training.",al={"who starts a lesson to learn","where do i get a lesson to learn","turak runetotem quest"}},{q="Where must I go to complete this quest?",a="You must travel to the village of Nighthaven, nestled within the sacred forest of Moonglade, and speak with Dendrite Starblaze of the Cenarion Circle.",al={"where do i turn in a lesson to learn","dendrite starblaze location","where is nighthaven"}},{q="What ability does this quest chain lead to?",a="This quest is the opening step in the questline that rewards druids with Aquatic Form, granting rapid underwater swimming and the ability to breathe beneath the surface indefinitely.",al={"what form does this give","aquatic form quest","why do this quest"}},{q="Why do tauren druids go to a night elf for training?",a="The Cenarion Circle operates as a neutral brotherhood dedicated to Cenarius and the preservation of nature. Within Moonglade, political tensions between the Horde and Alliance are set aside so night elves and tauren can learn the sacred arts together.",al={"why moonglade","why dendrite starblaze","cenarion circle tauren"}},{q="What trials does Dendrite Starblaze speak of?",a="Dendrite explains that you must face two specific challenges: one that tests your physical composure while working under pressure underwater, and another that tests your spiritual resolve to understand the aspect itself.",al={"what are the two trials","dendrite tests","aquatic trials"}},{q="How does a druid reach Moonglade at this stage?",a="Druids possess a innate spiritual bond granting them the spell Teleport: Moonglade, allowing them to shift directly from anywhere in Azeroth to the serene village of Nighthaven.",al={"how to get to moonglade","teleport to moonglade","getting to nighthaven"}}},ang={["class:Druid"]="This rite marks the transition from terrestrial survival to true elemental versatility, opening the way toward mastering breathing and moving underwater.",["race:Tauren"]="The quest represents the strong bond between the tauren druids of Thunder Bluff and the broader Cenarion brotherhood seated in Moonglade.",["faction:Horde"]="Though loyal to the Horde, tauren druids must honor the sacred neutrality of Moonglade, walking alongside night elves under the shared canopy of Cenarius."},kw={"aquatic form","cenarion circle","dendrite starblaze","elder rise","lesson to learn","moonglade","nighthaven","thunder bluff","turak runetotem"},rel={"npc:dendrite-starblaze","npc:turak-runetotem","quest:31","subzone:nighthaven","quest:5921","topic:cenarion-circle","topic:druid","topic:cenarius"},m={start="Turak Runetotem",["end"]="Dendrite Starblaze",level="16",faction="Horde",id=26},src={"A Lesson to Learn (Horde)"}}
E["quest:31"] = {t="quest",n="Aquatic Form",z="thunderbluff",s="This quest marks the final step in a young Horde druid's journey to master the waters. After proving their worthiness and attuning to the sea lion aspect in Moonglade, the druid returns home to Thunder Bluff to receive formal recognition and master their aquatic form.",h="This quest marks the final step in a young Horde druid's journey to master the waters.",sec={{t="Return of the Sea Lion",b="Having braved the trials in the sacred haven of Moonglade, an aspiring tauren druid is directed back to Mulgore by Dendrite Starblaze. Bearing the Pendant of the Sea Lion, the initiate carries physical proof of their balance and dedication across Kalimdor's waters. It serves as tangible evidence that they have respected the ancient traditions required to adopt an aquatic aspect.",sp=0},{t="Communion with the Waters",b="Upon ascending to the heights of Thunder Bluff, the traveler presents the pendant to their mentor, Turak Runetotem. Delighted by the initiate's honoring of their ancestors and natural balance, Turak imparts the secret of the aquatic form. With this teaching, the druid gains the innate ability to slip beneath rivers and oceans, breathing freely and navigating the depths as a sea creature.",sp=0}},faq={{q="What is the purpose of this quest?",a="This quest concludes the rite of passage for young Horde druids, allowing them to turn in their hard-earned Pendant of the Sea Lion in Thunder Bluff to finally unlock their shapeshifting Aquatic Form.",al={"why do this quest","aquatic form purpose","what does this quest do"}},{q="Who do I bring the Pendant of the Sea Lion to?",a="You must bring the pendant to Turak Runetotem, the druid trainer located on the upper rises of Thunder Bluff in Mulgore.",al={"who turns this in","where to turn in aquatic form","turak runetotem location"}},{q="Who sends you back to Thunder Bluff?",a="Dendrite Starblaze, a night elf druid keeper stationed in the neutral sanctuary of Moonglade, sends you back once your aquatic trials are complete.",al={"who gives aquatic form quest","dendrite starblaze quest"}},{q="Can non-druids complete this quest?",a="No. This quest line is strictly restricted to druids as part of their spiritual and magical progression to unlock animal forms.",al={"is this druid only","can other classes do aquatic form"}},{q="Why does a night elf in Moonglade help a Horde druid?",a="Moonglade is a neutral sanctuary overseen by the Cenarion Circle. When teaching the ancient arts of the Cenarion path, night elf mentors guide tauren druids without political hostility, focusing purely on keeping nature in balance.",al={"why does dendrite help horde","moonglade horde alliance","druid neutrality"}},{q="What ability does completing this quest grant?",a="Upon turning in the quest to Turak Runetotem, you are taught Aquatic Form, granting increased swimming speed and underwater breathing while shapeshifted.",al={"what form do i get","aquatic form spell","water form"}}},ang={["class:Druid"]="Achieving your aquatic form bridges the gap between land and sea, allowing you to traverse bodies of water effortlessly and escape predators in the deep.",["race:Tauren"]="Turak Runetotem reminds you that mastering the beasts of the sea honors your ancestors, solidifying the tauren's sacred resurgence in druidic ways.",["faction:Horde"]="Tauren druids represent the Horde's spiritual link to the Cenarion Circle, walking between ancient neutral sanctuaries and their own tribal capitals."},kw={"aquatic form","dendrite starblaze","druid","moonglade","pendant of the sea lion","sea lion","thunder bluff","turak runetotem"},rel={"npc:turak-runetotem","npc:dendrite-starblaze","topic:druid","zone:thunderbluff","quest:5921","quest:1067"},m={start="Dendrite Starblaze",["end"]="Turak Runetotem",level="16",faction="Horde",id=31},src={"Aquatic Form (Horde)"}}
E["quest:3369"] = {t="quest",n="In Nightmares",z="thunderbluff",s="In Nightmares is a Horde quest that tasks an adventurer with carrying a disturbing relic, the Nightmare Shard, to Arch Druid Hamuul Runetotem atop Elder Rise in Thunder Bluff. Originally recovered as a glowing fragment from the Wailing Caverns, the shard reveals a deeply unsettling corruption seeping into the Emerald Dream.",h="In Nightmares is a Horde quest that tasks an adventurer with carrying a disturbing relic, the Nightmare...",sec={{t="A Disturbing Discovery",b="After examining the strange crystal retrieved from the depths of the Wailing Caverns, Falla Sagewind recognizes that it is made from the pure essence of the Emerald Dream. Yet the vision dwelling inside is dark and chaotic, bearing the hallmark not of peaceful slumber, but of a waking nightmare. Reluctant to speak openly about such alarming omens, she entrusts the shard to you with instructions to seek out Thunder Bluff's most venerated elder druid, Arch Druid Hamuul Runetotem.",sp=0},{t="A Secret in the Dream",b="When presented with the Nightmare Shard on Elder Rise, Hamuul Runetotem's usual composure falters upon peering inside. Confronted with tangible evidence that the Emerald Dream is unraveling into nightmare, the archdruid chooses his words carefully. He firmly counsels discretion, warning that these delicate matters are far beyond the understanding of ordinary travelers, and quietly resolves to investigate the unseen affliction threatening the slumbering realm.",sp=1}},faq={{q="What is the Nightmare Shard?",a="The Nightmare Shard is the purified form of the glowing shard retrieved from the mutated beasts in the Wailing Caverns. Though forged from the pure spiritual essence of the Emerald Dream, it carries a foul, twisted vision indicating that something in the Dream has gone terribly wrong.",al={"what is nightmare shard","glowing shard nightmare","what did falla find"}},{q="Who is Falla Sagewind?",a="Falla Sagewind is a knowledgeable tauren druid located on the mountainside overlooking the Wailing Caverns in the Barrens. She studies the anomalous phenomena emerging from the corrupted oasis caverns and sends Horde couriers to Hamuul Runetotem when dangerous relics are discovered.",al={"falla sagewind","who gave me this quest","quest giver"}},{q="Where can I find Arch Druid Hamuul Runetotem?",a="Arch Druid Hamuul Runetotem resides on Elder Rise, one of the elevated mesas of Thunder Bluff. He can be found standing within the druidic circle alongside his fellow Cenarion Circle practitioners.",al={"where is hamuul","hamuul runetotem location","elder rise hamuul"}},{q="Why does Hamuul want to keep the shard a secret?",a="The Emerald Dream is the sacred sanctuary of nature and the slumbering druids. Tangible evidence that it is being twisted into a nightmare could cause widespread panic among the Cenarion Circle and undermine fragile spiritual restoration efforts across Kalimdor, prompting Hamuul to urge silence.",al={"why keep it quiet","hamuul secret","why does hamuul hide the shard"}},{q="Does the Alliance have a version of this quest?",a="Yes. While Horde champions take the Nightmare Shard to Arch Druid Hamuul Runetotem in Thunder Bluff, Alliance players who investigate the Wailing Caverns are directed to take their shard across the sea to Darnassus, presenting it to the druid Mathrengyl Bearwalker of the Cenarion Circle.",al={"alliance version","in nightmares alliance","can alliance do this"}},{q="How does this relate to the Wailing Caverns?",a="The shard originates within the Wailing Caverns, where the druid Naralex entered a deep trance to channel underground springs into the Barrens. Instead of healing the land, Naralex's slumber twisted into a waking nightmare, mutating the cavern fauna and bleeding into crystal shards like this one.",al={"wailing caverns connection","naralex connection","how does this relate to naralex"}}},ang={["class:Druid"]="For druids, the shard is deeply alarming evidence that the pristine sanctity of the Emerald Dream is compromised, validating the whispers of corruption creeping through Cenarion circles.",["race:Tauren"]="Returning to Arch Druid Hamuul Runetotem emphasizes the growing prominence of tauren druids within the Cenarion Circle as they confront ancient cosmological threats alongside their night elven teachers.",["faction:Horde"]="Delivering the shard safeguards the spiritual well-being of central Kalimdor, demonstrating that the Horde plays a crucial role in containing the fungal and dream-born corruption spilling from the Barrens."},kw={"elder rise","emerald dream","falla sagewind","glowing shard","hamuul runetotem","in nightmares","nightmare shard","thunder bluff","wailing caverns"},rel={"quest:6981","quest:1489","npc:falla-sagewind","subzone:elder-rise","zone:thunderbluff","topic:emerald-dream","topic:druid","topic:horde"},m={start="Falla Sagewind",["end"]="Arch Druid Hamuul Runetotem",level="25",faction="Horde",id=3369},src={"In Nightmares (Horde)"}}
E["quest:5062"] = {t="quest",n="Sacred Fire",z="thunderbluff",s="Sacred Fire is a Horde rite of passage that bridges the jagged canyons of Thousand Needles with the heights of Thunder Bluff. To summon and banish the vengeful wind serpent Arikara, hunters must gather rare Incendia Agave from the Boiling Pool so that Magatha Grimtotem can enchant it into ritual powder.",h="Sacred Fire is a Horde rite of passage that bridges the jagged canyons of Thousand Needles with the heights...",sec={{t="Kindling the Spirit",b="The monstrous wind serpent Arikara cannot simply be tracked across the canyon floor; she must be called. Motega Firemane instructs hunters to prepare the sacred fire of life, an ancient ritual flame that acts as a beacon to the spirit beast. Feeding this fire requires more than ordinary kindling, calling for the rare Incendia Agave that sprouts only around the scalding waters of Thousand Needles.",sp=0},{t="The Boiling Pool",b="Incendia Agave thrives near the Boiling Pool, a geothermally heated lake tucked below Darkcloud Pinnacle. Harvesting the spiky succulent requires braving the blistering waters and the volatile steam elementals that drift through the mists. Many bushels grow submerged beneath the surface, demanding resilience from any hunter sent to gather them.",sp=0},{t="The Elder's Blessing",b="Raw agave alone cannot ignite the ritual brazier. Once harvested, the plants must be carried high above the plains to Elder Rise in Thunder Bluff. There, the elder shaman Magatha Grimtotem lends her craft to grind and enchant the leaves into a potent ritual powder, outwardly eager to see the vengeful beast challenged.",sp=1}},faq={{q="What is the sacred fire of life?",a="It is a ritual flame used to summon the vengeful spirit serpent Arikara. Without lighting this sacred fire, the beast remains hidden and unreachable.",al={"sacred fire","what does the fire do","why light the sacred fire"}},{q="Where does Incendia Agave grow?",a="Incendia Agave is found in and around the Boiling Pool in Thousand Needles, near the base of Darkcloud Pinnacle. Many of the spiky plants grow submerged beneath the hot lake water.",al={"where to find agave","incendia agave location","boiling pool agave"}},{q="Why must Magatha Grimtotem enchant the agave?",a="The raw plant lacks the magical potency needed to ignite the sacred fire. As a powerful shaman, Magatha weaves elemental energy into the leaves, transforming them into a powder that can awaken the dormant flame.",al={"why magatha","who enchants the agave","what does magatha do"}},{q="Who is Arikara?",a="Arikara is a formidable wind serpent born to deliver vengeance against those who commit terrible crimes. Motega Firemane views her presence as an imminent peril that requires swift hunters to confront.",al={"what is arikara","arikara lore","wind serpent boss"}},{q="Who gives the quest Sacred Fire?",a="Motega Firemane offers the quest in Thousand Needles after you assist him with his initial tasks regarding the local serpent threat.",al={"quest giver sacred fire","where to start sacred fire"}},{q="Why does Magatha smile when she hears of Arikara?",a="Magatha finds amusement or satisfaction in the mention of a creature born solely to punish heinous acts, hinting at her dark perspective on vengeance and tribal politics.",al={"magatha smiling","magatha reaction","why does magatha smile"}}},ang={["race:Tauren"]="For tauren hunters, honoring the spirits through ritual hunting and navigating the elder politics on Elder Rise is a fundamental rite of adulthood.",["class:Shaman"]="The quest highlights the practical application of shamanic magic, demonstrating how elemental power can be infused into natural flora like Incendia Agave.",["profession:Herbalism"]="Herbalists have a distinct advantage in tracking down the submerged spiky bushels of Incendia Agave across the Boiling Pool.",["faction:Horde"]="Carrying out trials for the elders strengthens Horde ties across the arid flatlands of Kalimdor."},kw={"arikara","boiling pool","darkcloud pinnacle","elder rise","incendia agave","magatha grimtotem","motega firemane","sacred fire","thousand needles"},rel={"quest:4865","quest:5088","npc:motega-firemane","npc:magatha-grimtotem","zone:thousandneedles","zone:thunderbluff","subzone:elder-rise","subzone:darkcloud-pinnacle"},m={start="Motega Firemane",["end"]="Magatha Grimtotem",level="27",faction="Horde",id=5062},src={"Sacred Fire"}}
E["quest:5088"] = {t="quest",n="Arikara",z="thunderbluff",s="\"Arikara\" is the culmination of an ominous task given by Magatha Grimtotem in Thunder Bluff. Convinced that an ancient wind serpent is stalking High Chieftain Cairne Bloodhoof, the elder shaman sends Horde adventurers to summon and slay the beast upon the burial spires of Thousand Needles.",h="\"Arikara\" is the culmination of an ominous task given by Magatha Grimtotem in Thunder Bluff.",sec={{t="A Beast in the Smoke",b="After securing refined Incendia powder, Magatha Grimtotem enchants the reagent to serve as a summoning catalyst. She warns that ancient tauren traditions have shifted too rapidly under the new Horde alliance, provoking the vengeance of Arikara, a ferocious wind serpent spirit. Magatha directs heroes southward into the windswept canyon of Thousand Needles, instructing them to throw the powder onto a ritual pyre situated among the elevated burial sites of Darkcloud Pinnacle.",sp=0},{t="Doubt at Whitereach Post",b="Upon slaying the serpent on the burial needle and claiming its skin, adventurers deliver the remains to Motega Firemane at Whitereach Post. Rather than relief, Motega expresses genuine bewilderment. He finds it unbelievable that a primal spirit like Arikara would harbor malice toward Cairne Bloodhoof. Yet, unwilling to openly question Magatha's status as the tribe's most venerable shaman, Motega sets aside his suspicions and rewards the champion for protecting the chieftain.",sp=1}},faq={{q="Who is Arikara?",a="Arikara is a powerful wind serpent summoned atop Darkcloud Pinnacle in Thousand Needles. Magatha Grimtotem claims the beast was stirred to vengeance by modern deviations from traditional tauren lore.",al={"what is arikara","arikara lore","who is the serpent"}},{q="Why does Magatha Grimtotem want Arikara dead?",a="Magatha claims Arikara is hunting Cairne Bloodhoof, the High Chieftain of the tauren. She sends you to destroy the serpent using enchanted Incendia powder before it can threaten Thunder Bluff's leader.",al={"magatha motivation","why kill arikara","why summon arikara"}},{q="Where is the sacred fire located to summon her?",a="The unlit sacred fire of life is found atop an isolated spire within Darkcloud Pinnacle in Thousand Needles, an elevated mesa used by the local tauren to bury their dead.",al={"arikara location","where to summon arikara","sacred fire of life location"}},{q="Why is Motega Firemane skeptical of the hunt?",a="Motega Firemane struggles to understand why a spirit like Arikara would ever stalk Cairne Bloodhoof, as the High Chieftain is deeply revered by the earth and ancestral spirits. However, he hesitates to doubt Magatha Grimtotem's word.",al={"motega reaction","why is motega confused","cairne arikara make sense"},sp=1},{q="Is Cairne actually in danger from Arikara?",a="While Magatha insists Cairne's life was at risk, local shamans like Motega Firemane find the accusation bizarre, raising quiet doubts about whether Magatha is using Horde adventurers for her own mysterious agenda.",al={"was cairne really hunted","did arikara want cairne","magatha lying"},sp=1},{q="What is the previous quest in this chain?",a="This quest directly follows \"Sacred Fire,\" in which adventurers gather Incendia Agave from the Boiling Pool in Thousand Needles for Magatha Grimtotem to enchant into Incendia powder.",al={"arikara prereq","quest before arikara","sacred fire quest"}}},ang={["race:Tauren"]="For the tauren, the quest touches on the tension between ancient ancestral rites and the political shifts occurring under Cairne Bloodhoof's leadership, mediated by the ever-calculating Grimtotem.",["class:Shaman"]="Shaman adventurers will notice the friction between elemental ritual and political intrigue, as well as Motega's reluctance to dispute Magatha's peerless spiritual authority.",["faction:Horde"]="Sworn to protect Cairne Bloodhoof, Horde warriors readily march into Thousand Needles to neutralize any threat to the venerable High Chieftain."},kw={"arikara","cairne bloodhoof","darkcloud pinnacle","incendia powder","magatha grimtotem","motega firemane","thousand needles","whitereach post","wind serpent"},rel={"npc:magatha-grimtotem","npc:motega-firemane","quest:5062","subzone:darkcloud-pinnacle","subzone:whitereach-post","zone:thousandneedles","npc:cairne-bloodhoof","topic:tauren"},m={start="Magatha Grimtotem",["end"]="Motega Firemane",level="28",faction="Horde",id=5088},src={"Arikara (quest)"}}
E["quest:5644"] = {t="quest",n="Devouring Plague",z="thunderbluff",s="Devouring Plague is a rite of passage quest for Forsaken priests journeying far from Lordaeron. Guided by the Forsaken priest trainer Miles Welsh in Thunder Bluff, the adept is directed back across the seas to Aelthalyste in the Undercity to unlock a signature manifestation of Shadow magic.",h="Devouring Plague is a rite of passage quest for Forsaken priests journeying far from Lordaeron.",sec={{t="A Summons Home",b="While visiting Thunder Bluff, Forsaken priests who have honed their mastery over divine and shadowy disciplines are evaluated by Miles Welsh, an envoy of the Cult of Forgotten Shadow among the tauren. Recognizing that an acolyte has grown sufficiently in power, Miles bids them return to the Ruins of Lordaeron rather than attempt to impart these higher mysteries himself in Kalimdor.",sp=0},{t="The Secrets of Aelthalyste",b="Awaiting beneath the city ruins within the Undercity's War Quarter is Aelthalyste, one of the foremost mentors of Forsaken priesthood. She watches over the development of shadow-weaving acolytes, ensuring that the potent, draining blight known as the Devouring Plague is entrusted only to those capable of wielding its corruptive force without succumbing to it.",sp=0}},faq={{q="Who sends you on this quest?",a="Miles Welsh, a Forsaken priest trainer stationed in the Pools of Vision beneath Spirit Rise in Thunder Bluff, sends you on this journey once your abilities have developed sufficiently.",al={"who starts devouring plague quest","quest giver devouring plague","miles welsh role"}},{q="Where is Aelthalyste located?",a="Aelthalyste resides in the War Quarter of the Undercity, standing among the training rings and dark conduits where Forsaken priests gather.",al={"aelthalyste location","where is aelthalyste","devouring plague turn in"}},{q="Why can't Miles Welsh teach the spell himself?",a="Certain foundational mysteries of the Forsaken shadow faith are reserved for master mentors like Aelthalyste in the heart of the Undercity. Welsh honors this hierarchy by sending worthy adepts home to be tested.",al={"why travel to undercity","why see aelthalyste","undercity priest trainer"}},{q="What is Devouring Plague from a lore perspective?",a="It is a devastating curse practiced by the Cult of Forgotten Shadow, afflicting the victim with a virulent magical affliction that consumes their vitality to restore the caster.",al={"what is devouring plague","lore of devouring plague","forsaken disease spell"}},{q="Is this quest available to other races?",a="No. The Devouring Plague quest is tied exclusively to the Forsaken priesthood, reflecting the unique philosophy and magical practices born of Lordaeron's undead survivors.",al={"can trolls do devouring plague quest","can orcs do devouring plague","is this quest undead only"}},{q="Why is a Forsaken trainer in Thunder Bluff in the first place?",a="Following the Forsaken's admission into the Horde, diplomats and mentors were exchanged across capitals. Priests like Miles Welsh represent the Undercity's spiritual traditions and offer guidance to Forsaken traveling through Kalimdor.",al={"why are undead in thunder bluff","forsaken in thunder bluff lore","miles welsh thunder bluff"}}},ang={["class:Priest"]="This quest marks an important milestone in a Forsaken priest's education, transitioning them from basic tenets into the dread Shadow traditions unique to the undead.",["race:Undead"]="Unlike the Light practiced in life, Forsaken priests embrace harsh afflictions and Shadow magic, with Devouring Plague representing their distinct cultural magic.",["faction:Horde"]="The quest illustrates the logistical and spiritual bonds linking the distant Horde outposts in Mulgore directly back to the dark heart of the Undercity."},kw={"aelthalyste","devouring plague","forsaken","miles welsh","shadow priest","thunder bluff","undercity","war quarter"},rel={"npc:aelthalyste","npc:miles-welsh","zone:undercity","subzone:war-quarter"},m={start="Miles Welsh",["end"]="Aelthalyste",level="20",faction="Horde",id=5644},src={"Devouring Plague (Thunder Bluff)"}}
E["quest:5922"] = {t="quest",n="Moonglade",z="thunderbluff",s="This quest marks a young tauren druid's introduction to Moonglade, the sacred sanctuary of Cenarion druidism. Guided by Turak Runetotem in Thunder Bluff, the initiate learns to traverse the waking world to commune directly with nature's ancient keepers.",h="This quest marks a young tauren druid's introduction to Moonglade, the sacred sanctuary of Cenarion druidism.",sec={{t="A Sacred Haven Beyond Faction",b="Moonglade stands apart from the turbulent politics of Kalimdor. Sheltered beneath primeval boughs and watched over by Keeper Remulos, the son of Cenarius, this ancient valley is a neutral refuge for all who walk the path of nature. Whether night elf or tauren, any druid who enters Nighthaven does so as an equal peer under the timeless mantle of the Cenarion Circle.",sp=0},{t="The Leap Across Kalimdor",b="To aid your spiritual and martial development, Turak Runetotem teaches you a unique transport spell tied to the valley itself. By invoking the mystic bond between druids and the natural world, you step across hundreds of leagues in a heartbeat. This sanctuary will serve as both a study hall and an enduring refuge throughout your journey.",sp=0},{t="Awakening the Bear",b="Upon arriving in Nighthaven, you meet Dendrite Starblaze, an elder night elf druid awaiting new pupils. Under his guidance, the first true trial of your calling begins: seeking the perspective of the bear. Embracing the ways of the Claw requires proving one's strength, courage, and balance before the Great Bear Spirit.",sp=1}},faq={{q="Why can tauren visit a night elf haven like Moonglade?",a="Moonglade is sovereign sacred ground under the Cenarion Circle, guided by Keeper Remulos. Within its borders, devotion to nature and Cenarius completely supersedes the faction conflict between the Horde and the Alliance, permitting tauren and night elf druids to train and dwell alongside one another in peace.",al={"why tauren in moonglade","horde allowed in moonglade","is moonglade neutral"}},{q="Who is Dendrite Starblaze?",a="Dendrite Starblaze is an elder night elf druid stationed in the settlement of Nighthaven. He mentors newly arrived initiates of both races, administering their early trials as they attune to the ancient animal aspects.",al={"dendrite starblaze","who is dendrite","night elf quest giver"}},{q="Who is Keeper Remulos?",a="Keeper Remulos is a mighty Keeper of the Grove and son of the demigod Cenarius. He serves as the supreme guardian of Moonglade, watching over the sacred barrows where sleeping druids hibernate and ensuring the sanctity of the valley remains inviolate.",al={"keeper remulos","remulos moonglade","who protects moonglade"}},{q="What happens after reaching Moonglade?",a="Speaking with Dendrite Starblaze begins your trial with the Great Bear Spirit. He sends you into the wild lands to commune with the spirit and overcome a test of strength, ultimately unlocking the secrets of the bear form.",al={"what do i do next","bear questline","after moonglade quest"}},{q="How does Teleport: Moonglade work lore-wise?",a="Druids weave natural ley energies and their spiritual connection to the Cenarion Circle to instantly bridge the distance between wherever they stand and the heart of Moonglade. It serves as a spiritual anchor, letting them return for instruction and solace whenever summoned.",al={"moonglade teleport lore","teleport spell druid"}},{q="Where is Turak Runetotem located?",a="Turak Runetotem resides atop the Elder Rise in Thunder Bluff, mentoring young tauren who heed the call of the wild before sending them onward to Moonglade.",al={"turak runetotem location","where is turak"}}},ang={["class:Druid"]="This rite of passage bridges the distance between traditional tribal beliefs and the broader tenets of the Cenarion Circle, opening the door to ancient shapeshifting forms.",["race:Tauren"]="For tauren initiates, arriving in Moonglade is a profound awakening: proof that their ancient ties to the Earth Mother align deeply with the teachings of Cenarius.",["faction:Horde"]="Though tensions simmer across Kalimdor, Horde druids find Moonglade to be one of the rare places in the world where they can cross paths peacefully with their night elf counterparts."},kw={"bear form","cenarius","dendrite starblaze","moonglade","nighthaven","remulos","teleport moonglade","turak runetotem"},rel={"npc:turak-runetotem","npc:dendrite-starblaze","subzone:nighthaven","npc:remulos","topic:druid","topic:cenarius","topic:tauren","quest:5921"},m={start="Turak Runetotem",["end"]="Dendrite Starblaze",level="10",faction="Horde",id=5922},src={"Moonglade (Horde)"}}
E["quest:5926"] = {t="quest",n="Heeding the Call",z="thunderbluff",s="Heeding the Call marks a novice druid's summoning to Elder Rise in Thunder Bluff for advanced personal instruction. Relayed by innkeepers and kin across Horde settlements, the summons directs aspiring shapeshifters to Turak Runetotem. This meeting sets off the sacred trials required to master the form and spirit of the bear.",h="Heeding the Call marks a novice druid's summoning to Elder Rise in Thunder Bluff for advanced personal...",sec={{t="A Word in the Inn",b="Word travels quickly across the plains of Mulgore and through the dusty thoroughfares of Orgrimmar. Whether heard from Innkeeper Gryshka among the orcs, Innkeeper Pala in Thunder Bluff, or Gennia Runetotem in Bloodhoof Village, the message is the same: Turak Runetotem has noticed your early progress. The Cenarion Circle does not summon practitioners lightly, and this invitation signals that your days of elementary herb-gathering and basic spellweaving have earned you deeper communion with nature's wild spirits.",sp=0},{t="The Circle on Elder Rise",b="Turak Runetotem serves as an assistant to Archdruid Hamuul Runetotem, guiding young tauren toward their ancestral duty inside the large Cenarion tent on Elder Rise. Welcoming initiates into a broader understanding of Cenarius's legacy, Turak instructs them that animals and plants are both allies and solemn charges. Meeting him is the opening threshold of the rite: stepping beyond basic mentorship to confront the trials of body and heart required to commune directly with the Great Bear Spirit.",sp=0}},faq={{q="Who sends me to speak with Turak Runetotem?",a="The summons can be delivered by several different contacts: Gennia Runetotem in Bloodhoof Village, Innkeeper Pala in Thunder Bluff, or Innkeeper Gryshka in Orgrimmar. Each has received word that Turak wishes to guide your training personally.",al={"who gives heeding the call","quest giver heeding the call","where do i start heeding the call"}},{q="Where can I find Turak Runetotem?",a="Turak resides on the Elder Rise of Thunder Bluff. He makes his home inside the prominent Cenarion Circle tent, near the city's other druidic mentors.",al={"turak runetotem location","where is turak","how to find turak"}},{q="Why is this summons so important for young druids?",a="This summons begins your formal shapeshifting trials. Turak Runetotem directs you to sacred ground in Moonglade so you can learn the way of the bear and acquire your first animal form.",al={"why do i need turak","what is this quest for","druid level 10 quest horde"}},{q="Who is Turak Runetotem in the Cenarion hierarchy?",a="Turak is a respected tauren druid and a trusted assistant to Archdruid Hamuul Runetotem. He is known for his patience and wisdom when teaching young initiates the balance of nature.",al={"who is turak runetotem","turak lore"}},{q="Can other classes accept this quest?",a="No. This quest is exclusively offered to druids who have reached their tenth season of experience, serving as their rite of passage into shapeshifting.",al={"is heeding the call druid only","can shaman do this quest"}},{q="What happens after I speak to Turak?",a="Turak welcomes you into Cenarius's service and sends you to the sacred druidic haven of Moonglade to seek out Dendrite Starblaze and begin communion with the Great Bear Spirit.",al={"what comes after heeding the call","next quest after turak"},sp=1}},ang={["class:Druid"]="This quest is the vital first step on your path to mastering animal forms, beginning the sacred journey toward earning the spirit and fortitude of the bear.",["race:Tauren"]="For the tauren, studying under Turak on Elder Rise reaffirms their deep, ancestral reconnection with the Cenarion Circle and the wild spirits of Kalimdor.",["faction:Horde"]="Innkeepers across both orcish and tauren lands help ensure that rising druids receive their calling, fostering the Horde's vital connection to the wild earth."},kw={"bear form","bloodhoof village","cenarion circle","druid","elder rise","gennia runetotem","heeding the call","thunder bluff","turak runetotem"},rel={"npc:turak-runetotem","subzone:elder-rise","zone:thunderbluff","topic:druid","topic:cenarion-circle","topic:cenarius","subzone:bloodhoof-village","npc:innkeeper-gryshka"},m={start="Gennia RunetotemInnkeeper GryshkaInnkeeper Pala",["end"]="Turak Runetotem",level="10",faction="Horde",id=5926},src={"Heeding the Call (Horde)"}}
E["quest:5932"] = {t="quest",n="Back to Thunder Bluff",z="thunderbluff",s="\"Back to Thunder Bluff\" is an essential rite of passage for young tauren druids returning from the sacred glades of Moonglade. Having communed with the Great Bear Spirit, the initiate is sent by Dendrite Starblaze back to Elder Rise to continue training under Turak Runetotem.",h="\"Back to Thunder Bluff\" is an essential rite of passage for young tauren druids returning from the sacred...",sec={{t="A Bridged Fellowship",b="Moonglade stands apart from the factional divides of the mortal world, serving as a sanctuary where night elf and tauren practitioners of nature magic gather as the Cenarion Circle. After communion with the Great Bear Spirit, night elf mentor Dendrite Starblaze sends the young tauren back to their people. While night elves often view tauren as fledglings in the formalized teachings of Cenarius, Starblaze readily acknowledges the profound wisdom and balance maintained by Turak Runetotem.",sp=0},{t="Return to the Bluffs",b="Upon climbing back to the sweeping heights of Elder Rise in Thunder Bluff, the novice stands before Turak Runetotem transformed. Communing with ancient totemic spirits like the Great Bear Spirit is deeply ingrained in tauren culture, yet undertaking the Path of the Claw marks a serious commitment. With the spiritual connection forged, Turak prepares the druid to put that newfound strength and endurance into active practice.",sp=0}},faq={{q="Why was a night elf teaching a tauren in Moonglade?",a="The Cenarion Circle is neutral and devoted entirely to the preservation of nature. Within Moonglade, political hostility between the Horde and the Alliance is strictly set aside, allowing night elf elders like Dendrite Starblaze to guide fledgling tauren druids.",al={"dendrite starblaze horde","why night elf mentor","cenarion circle tauren"}},{q="Who is Turak Runetotem?",a="Turak Runetotem is an esteemed tauren druid, one of the Arch Druid's assistants, stationed on Elder Rise in Thunder Bluff. He oversees the training of young tauren seeking to walk the path of nature and the claw, serving as a key liaison to the Cenarion Circle.",al={"turak runetotem role","elder rise druid leader"}},{q="What did the young druid do right before this quest?",a="Prior to being sent back to Mulgore, the initiate traveled to Moonglade to seek out and commune with the ancient Great Bear Spirit, gaining its blessing and learning the spiritual core of bear form.",al={"what came before back to thunder bluff","great bear spirit quest"}},{q="How do young druids travel back to Thunder Bluff from Moonglade?",a="Bunthen Plainswind, located in southwestern Nighthaven, provides specialized flight master services specifically to carry tauren druids back to Thunder Bluff safely after their rites.",al={"how to get back from moonglade","moonglade flight back"}},{q="What comes next in the druid's training?",a="Upon returning, Turak Runetotem gives the initiate the quest 'Body and Heart,' sending them to face a physical challenge at the Moonkin Stone where the Barrens meet Mulgore to prove they can channel the spirit's strength into actual beast form.",al={"next druid quest","after back to thunder bluff"}},{q="Why does Dendrite Starblaze call tauren 'young in the ways of Cenarius'?",a="While tauren legends trace ancient communion with Cenarius in the dawn of the world, formal Cenarion druidism was developed and sustained by night elves over ten thousand years. The tauren only recently re-established structured study under the Cenarion Circle.",al={"are tauren new druids","tauren druid history cenarius"}}},ang={["class:Druid"]="This leg of your journey links the ancient secluded haven of Moonglade with the windswept heights of Thunder Bluff, marking your growth along the Path of the Claw.",["race:Tauren"]="Returning to Elder Rise brings the wisdom of the ancient spirits back home to benefit and protect your tribes across Mulgore.",["faction:Horde"]="The knowledge brought back from Moonglade ensures that the Horde counts powerful shapeshifting defenders among its ranks on the plains of Kalimdor."},kw={"back to thunder bluff","bear form","dendrite starblaze","elder rise","great bear spirit","moonglade","nighthaven","turak runetotem"},rel={"npc:turak-runetotem","npc:dendrite-starblaze","zone:thunderbluff","subzone:elder-rise","subzone:nighthaven","topic:druid","topic:cenarius","topic:tauren"},m={start="Dendrite Starblaze",["end"]="Turak Runetotem",level="10",faction="Horde",id=5932},src={"Back to Thunder Bluff"}}
E["quest:6002"] = {t="quest",n="Body and Heart",z="thunderbluff",s="Body and Heart is the culminating trial for young tauren druids seeking to master Bear Form. Dispatched by Turak Runetotem in Thunder Bluff, the initiate must travel to the border of Mulgore and the Barrens to summon and best Lunaclaw at the Moonkin Stone.",h="Body and Heart is the culminating trial for young tauren druids seeking to master Bear Form.",sec={{t="The Way of the Claw",b="To truly follow the path of the Druid of the Claw, tauren initiates must unite spiritual conviction with physical resilience. After communion with the Great Bear Spirit in Moonglade, a druid's training is put to an active test. Turak Runetotem, the elder druid trainer atop the Elder Rise in Thunder Bluff, bestows Cenarion Lunardust upon worthy aspirants, charging them to seek out a sacred stone resting near the arid frontier where Mulgore meets the Barrens.",sp=0},{t="The Trial of Lunaclaw",b="Resting west of Camp Taurajo, the Moonkin Stone marks a rare Cenarion site in southern Kalimdor. Moonkin are not native to the sun-scorched plains of central Kalimdor, making the presence of the guardian beast Lunaclaw deeply significant. By scattering the lunardust across the ancient monument, the druid calls forth Lunaclaw in battle. Defeating the creature proves the aspirant commands both strength of body and clarity of heart, earning the beast's blessing and unlocking the inner essence of the bear.",sp=0}},faq={{q="What is the purpose of this trial?",a="This quest is the final step in earning Bear Form for Horde druids. By completing the challenge, you prove yourself ready to take on the mantle of a Druid of the Claw under the tutelage of Turak Runetotem.",al={"why do body and heart","what does body and heart do","what do i get from body and heart"}},{q="Where is the Moonkin Stone located?",a="The Moonkin Stone is located in the Barrens, west of Camp Taurajo along the road leading toward the Mulgore gate. Just south of the road, tucked behind a tree near a lone tent, lies the sacred stone.",al={"moonkin stone location","where is moonkin stone","where to find moonkin stone"}},{q="Who is Lunaclaw?",a="Lunaclaw is a fierce moonkin guardian bound to the Moonkin Stone. Summonsed with Cenarion Lunardust, it tests whether a druid possesses the raw tenacity and emotional temperance required to wield the power of the bear.",al={"who is lunaclaw","what is lunaclaw"}},{q="What happens if I lose the battle against Lunaclaw?",a="If you are defeated, your Cenarion Lunardust is expended. You must return to Turak Runetotem atop the Elder Rise in Thunder Bluff to receive another pouch of dust before attempting the summoning again.",al={"failed lunaclaw","lost lunardust","died to lunaclaw"}},{q="Are moonkin native to the Barrens?",a="No. As Turak Runetotem notes, moonkin are not native to the Barrens or Mulgore. The creature is an unnatural sight on the savannah, tied specifically to Cenarion rites and ancient sites of celestial power.",al={"moonkin in barrens","why are moonkin here","barrens moonkin"}},{q="Who gives the quest Body and Heart?",a="The quest is given by Turak Runetotem, the senior druid trainer located on the Elder Rise in Thunder Bluff, following the initiate's return from Moonglade.",al={"who starts body and heart","body and heart questgiver"}}},ang={["class:Druid"]="This rite of passage bridges the gap between night elven Cenarion teachings and tauren heritage, allowing young druids to finally manifest the ferocious resilience of Bear Form.",["race:Tauren"]="For the Shu'halo, awakening the bear within is both a holy communion with nature spirits and a practical means to protect the plains of Mulgore from encroaching threats.",["faction:Horde"]="Tauren druids bring vital resilience to the Horde's front lines, grounding the faction's magical power in deep wilderness guardianship."},kw={"barrens","bear form","body and heart","camp taurajo","cenarion lunardust","lunaclaw","moonkin stone","mulgore","thunder bluff","turak runetotem"},rel={"quest:5932","npc:turak-runetotem","zone:thunderbluff","zone:barrens","subzone:camp-taurajo","zone:mulgore","quest:6001","topic:druid"},m={start="Turak Runetotem",level="10",faction="Horde",id=6002},src={"Body and Heart (Horde)"}}
E["quest:6126"] = {t="quest",n="Lessons Anew",z="thunderbluff",s="Lessons Anew is a rite of passage for young tauren druids, initiated by Turak Runetotem on the Elder Rise of Thunder Bluff. It directs apprentices to travel to the sacred haven of Moonglade to begin mastering the art of cleansing natural and unnatural poisons. Guided by the night elf Dendrite Starblaze, this lesson sets aside mock trials in favor of confronting an urgent, real-world poisoning crisis.",h="Lessons Anew is a rite of passage for young tauren druids, initiated by Turak Runetotem on the Elder Rise of...",sec={{t="The Gift of Cenarius",b="Druids hold a sacred mandate to protect the wilds, which includes the miraculous ability bestowed by Cenarius to purge virulent toxins with a simple incantation. However, such potent magic is not handed over without grounding. Turak Runetotem insists that before channeling divine energies to effortlessly dispel blights, a druid must understand the physical toll of venom and learn to treat it through grounded, mundane means.",sp=0},{t="Summons to Nighthaven",b="Rather than conducting training solely on the bluffs of Mulgore, promising acolytes are sent north through sacred pathways to Moonglade. There, within the peaceful village of Nighthaven, ancient night elf mentors such as Dendrite Starblaze oversee the education of both elf and tauren practitioners. This shared instruction highlights the delicate truce that exists within the Cenarion Circle, rising above the political strife separating Horde and Alliance.",sp=0},{t="A Real Crisis in the Barrens",b="While past initiates practiced their cleansing rites in controlled conditions, Starblaze has no time for manufactured exercises. An uncontrolled rash of animal poisonings has broken out near the Crossroads in the arid Barrens. The desperate plea for aid from the crossroads transforms an academic rite of passage into an urgent field mission, demanding that young druids directly confront the suffering of wild beasts.",sp=1}},faq={{q="Who offers this quest and where do I find them?",a="The quest is offered by Turak Runetotem, the tauren druid trainer located on the Elder Rise in Thunder Bluff. He calls upon initiates who have proven their early commitment to the Cenarion teachings.",al={"who gives lessons anew","where to get lessons anew","lessons anew quest giver"}},{q="Who is Dendrite Starblaze?",a="Dendrite Starblaze is an elder night elf druid residing in Nighthaven within Moonglade. Despite the broader faction tensions between night elves and tauren, he mentors young druids of both races in the traditions of the Cenarion Circle.",al={"who is dendrite","dendrite starblaze role","who is the night elf in moonglade"}},{q="What power is this quest teaching me?",a="This quest line initiates your instruction in Cure Poison. It teaches druids to understand the physical and magical nature of venom, enabling them to purge harmful afflictions from their allies and the wild creatures under their care.",al={"what ability do i learn","what spell is this for","curing poison quest"}},{q="Why does a tauren have to study under a night elf?",a="The Cenarion Circle operates as a neutral brotherhood dedicated to the balance of nature. While night elves were the first to formalize modern druidism under Cenarius, they welcomed the tauren back into the order, sharing sacred grounds like Moonglade despite the faction war.",al={"why night elf trainer","tauren night elf druids","cenarion circle faction"}},{q="What is happening at the Crossroads?",a="The local wildlife around the Crossroads in the Barrens is suffering from an aggressive wave of poisonings that local handlers cannot contain. Dendrite Starblaze redirects your training directly into the field to discover the source and synthesize a remedy.",al={"crossroads problem","what is poisoning the animals","crossroads sickness"}},{q="What is the fastest way to get to Moonglade for this quest?",a="As a druid, you possess the innate spell Teleport: Moonglade, which whisks you directly into the sanctuary of Nighthaven without needing to travel through treacherous contested lands on foot.",al={"how to get to moonglade","travel to nighthaven","teleport moonglade"}}},ang={["class:Druid"]="This quest marks your transition from basic shapeshifting and skirmishing into true stewardship of the wilds, initiating the journey toward mastering the Cure Poison spell.",["race:Tauren"]="For tauren, this pilgrimage demonstrates how deeply the Earth Mother's children have reconnected with Cenarius's teachings alongside their night elf peers.",["faction:Horde"]="While Horde warriors clash with night elves in Ashenvale, Horde druids are granted safe harbor in Moonglade under the sacred auspices of the Cenarion Circle."},kw={"cenarion circle","crossroads","cure poison","dendrite starblaze","lessons anew","moonglade","nighthaven","turak runetotem"},rel={"quest:6125","npc:turak-runetotem","npc:dendrite-starblaze","subzone:nighthaven","quest:5921","zone:barrens","subzone:crossroads","topic:cenarius"},m={start="Turak Runetotem",["end"]="Dendrite Starblaze",level="14",faction="Horde",id=6126},src={"Lessons Anew (Horde)"}}
E["quest:6130"] = {t="quest",n="Power over Poison",z="thunderbluff",s="Power over Poison is the concluding rite in a young Horde druid's trial to master restorative nature magic. Having cured afflicted gazelles around the Crossroads using only herbal mixtures, the initiate returns to Turak Runetotem on Thunder Bluff's Elder Rise to receive the true gift of Cure Poison.",h="Power over Poison is the concluding rite in a young Horde druid's trial to master restorative nature magic.",sec={{t="A Lesson in Suffering",b="Before granting a fledgling druid the innate magical power to cleanse venoms, the Cenarion Circle demands they understand the physical reality of affliction. Dendrite Starblaze sent the novice to the Crossroads, where Tonga Runetotem had them gather earthly reagents for a curative salve made by hand. Only by treating the poisoned plains gazelles of the Barrens without spiritual aid does the student witness the agonizing struggle ordinary creatures face against natural and unnatural toxins.",sp=0},{t="Return to the Elder Rise",b="With the trial complete, Dendrite sends the initiate back to Turak Runetotem, the grand druid trainer residing on the Elder Rise in Thunder Bluff. Turak observes that the strange, virulent poisons surfacing near the Crossroads threaten the natural balance of the plains and warrant grave concern. Commending the initiate's grace under pressure, Turak permanently imparts the spiritual art of curing poisons, entrusting them to safeguard Kalimdor's living creatures.",sp=0}},faq={{q="What is the purpose of this quest?",a="This quest marks the completion of the Horde druid trial for curing venoms. After demonstrating discipline by preparing mundane remedies to save suffering gazelles, the initiate returns to Turak Runetotem to learn the Cure Poison spell directly through druidic communion.",al={"why do power over poison","what does this quest do","druid poison quest purpose"}},{q="Where is Turak Runetotem located?",a="Turak Runetotem resides atop the Elder Rise in Thunder Bluff. He makes his home within the tent and hollowed roosts where the tauren druids commune and train.",al={"turak runetotem location","where is turak","find turak runetotem"}},{q="Who sends the druid back to Thunder Bluff?",a="Dendrite Starblaze, a night elf druid of the Cenarion Circle stationed in the sacred haven of Moonglade, sends the initiate back to their mentor once they successfully heal the wildlife near the Crossroads.",al={"who gives power over poison","quest giver","dendrite starblaze"}},{q="Why did the Cenarion Circle make the druid cure beasts manually first?",a="Dendrite Starblaze emphasizes that a druid must understand what it means to cure venom through sheer labor and mortal limitations before wielding effortless spiritual magic. Experiencing the plight of afflicted creatures teaches empathy and respect for the natural balance.",al={"why cure sick manually","why use salves first","druid poison lesson"}},{q="What concerns Turak Runetotem about the Crossroads?",a="Turak notes with deep concern that unnatural, aggressive venoms are being introduced to the Barrens wildlife near the Crossroads. He considers such pollution a grave disruption to the balance of the land that demands future vigilance.",al={"turak crossroads concern","crossroads poison balance"}},{q="Is this quest available to Alliance druids?",a="Alliance druids undertake a parallel trial with the same name. Instead of reporting to Turak Runetotem on the Elder Rise, night elf initiates conclude their lesson by returning to Mathrengyl Bearwalker in Darnassus.",al={"can night elves do this","alliance power over poison"}}},ang={["class:Druid"]="This rite of passage bridges the physical herbalism of Kalimdor with innate nature magic, granting druids their permanent ability to purge toxins from allies.",["race:Tauren"]="For tauren initiates, completing this quest proves their dedication to the Cenarion Circle while keeping the wisdom of the Earth Mother alive upon the Elder Rise.",["faction:Horde"]="The trials surrounding the Crossroads demonstrate the Horde's growing role in safeguarding the wild expanses of central Kalimdor from unnatural corruption."},kw={"barrens","crossroads","cure poison","dendrite starblaze","elder rise","moonglade","thunder bluff","turak runetotem"},rel={"npc:turak-runetotem","npc:dendrite-starblaze","subzone:elder-rise","zone:thunderbluff","topic:druid","subzone:crossroads","quest:6125"},m={start="Dendrite Starblaze",["end"]="Turak Runetotem",level="14",faction="Horde",id=6130},src={"Power over Poison (Horde)"}}
E["quest:6362"] = {t="quest",n="Ride to Thunder Bluff",z="thunderbluff",s="This quest sends young Horde adventurers taking their first flight path across Kalimdor aboard a wind rider. Entrusted with a shipment of cured hides, travelers depart the dry crossroads of the Barrens to deliver valuable leatherwork supplies directly to the heights of Thunder Bluff.",h="This quest sends young Horde adventurers taking their first flight path across Kalimdor aboard a wind rider.",sec={{t="Wings Across the Savannah",b="For many travelers making their way through the Barrens, booking a flight with Devrak marks their first journey through the skies on the back of a wind rider. These winged wyverns provide vital aerial links between the dispersed settlements of the fledgling Horde, avoiding the perilous ground routes prowled by quilboar and centaur packs.",sp=0},{t="Hides for the Armory",b="The shipment consists of a bundle of cured hides prepared in the Barrens and destined for Ahanu, a craftsman working out of Hewa's Armory in Thunder Bluff. Nestled right beneath the great wind rider roost on the central mesa, Ahanu relies on raw supplies brought in from hunting outposts across the plains to outfit local warriors and hunters.",sp=0}},faq={{q="Who gives the quest Ride to Thunder Bluff?",a="Devrak, the wind rider master stationed at the Crossroads in the Barrens, offers this task to travelers who have collected a bundle of hides.",al={"quest giver","where to start ride to thunder bluff","devrak location"}},{q="Who is Ahanu and where can he be found?",a="Ahanu is a tauren artisan stationed at Hewa's Armory in Thunder Bluff, situated directly near the base of the city's wind rider roost.",al={"where is ahanu","ahanu location","hewa's armory"}},{q="What is being transported in this delivery?",a="You are carrying a bundle of prepared hides sent from the Barrens, which Ahanu intends to use immediately for his leatherworking and armor crafting.",al={"what am i delivering","bundle of hides"}},{q="Why use wind riders instead of walking?",a="Wind riders easily scale the towering cliffs of Mulgore and cut straight across the Barrens, avoiding treacherous ambushes and exhausting climbs up the Great Lift.",al={"why fly to thunder bluff","flight path benefit"}},{q="Where does this delivery chain begin?",a="The delivery originates with Jahan Hawkwing at the Crossroads, who arranges the bundle of cured pelts in the preceding task, A Bundle of Hides.",al={"previous quest","hides questline"}},{q="What comes next after delivering the hides?",a="After receiving the hides, Ahanu directs travelers upstairs to speak directly with Tal, the Wind Rider Master of Thunder Bluff.",al={"next quest","followup to ride to thunder bluff"}}},ang={["race:Tauren"]="For young tauren returning from the Barrens, this flight offers an effortless ascent straight to the towering heights of their people's majestic capital.",["faction:Horde"]="Reliable aerial travel via wind riders is crucial for binding the far-flung outposts of the Barrens to the major bastions of Durotar and Mulgore."},kw={"ahanu","barrens","bundle of hides","crossroads","devrak","hewa's armory","ride to thunder bluff","wind rider"},rel={"npc:devrak","npc:ahanu","zone:thunderbluff","zone:barrens","quest:4767"},m={start="Devrak",["end"]="Ahanu",level="10",faction="Horde",id=6362},src={"Ride to Thunder Bluff (Classic)"}}
E["quest:6363"] = {t="quest",n="Tal the Wind Rider Master",z="thunderbluff",s="Tal the Wind Rider Master is a simple courier task connecting Mulgore leatherworkers with merchants in the Barrens. The leatherworker Ahanu entrusts a parcel of finished hides to be flown out of Thunder Bluff across the Great Divide. Delivered directly to Tal, the mesa's flight master, it introduces fledgling Horde travelers to the wind rider transport network.",h="Tal the Wind Rider Master is a simple courier task connecting Mulgore leatherworkers with merchants in the...",sec={{t="Supplies for the Crossroads",b="Trade between Mulgore and the arid scrub of the Barrens is essential for the young Horde. Ahanu, a leatherworker practicing his craft upon Thunder Bluff's high rises, produces durable leather goods intended for Jahan Hawkwing's trade stall at the Crossroads. Because the overland walk down the Great Lift and through the golden plains takes hours on foot, merchants rely on winged couriers to ferry fragile or urgent parcels over the craggy divide.",sp=0},{t="Master of the Mesa's Roost",b="Perched upon the highest central tier of Thunder Bluff, Tal tends to the city's flock of wind riders—also known as wyverns. These intelligent, leathery-winged beasts are ideally suited for navigating Kalimdor's unpredictable thermal drafts and rugged peaks. Tal coordinates flights departing to outposts like the Crossroads, ensuring messengers and cargo pass quickly between the tauren capital and their orcish allies.",sp=0}},faq={{q="Who is Tal?",a="Tal is Thunder Bluff's flight master, overseeing the roost of wind riders located on the central mesa. He manages aerial transport for travelers and couriers heading out into the Barrens and beyond.",al={"who is tal","tal thunder bluff","wind rider master tal"}},{q="Who is Ahanu?",a="Ahanu is a tauren leatherworking craftsman residing in Thunder Bluff. He prepares bulk leather goods and bundles them to supply vendors at outposts across Kalimdor, including Jahan Hawkwing at the Crossroads.",al={"ahanu","who is ahanu","ahanu thunder bluff"}},{q="Why do the goods need to go to the Crossroads?",a="The Crossroads serves as the vital trade and military intersection of the Barrens. Goods produced in the sheltered peace of Mulgore, such as hides and leather garments, are shipped there to supply travelers, hunters, and Horde patrols.",al={"why crossroads","leather goods crossroads","jahan leather"}},{q="Can I fly straight to the Crossroads with this parcel?",a="You can only fly to the Crossroads if you have already visited the settlement and established contact with Devrak, their local wind rider master. If you have not unlocked that route yet, you must travel overland on foot.",al={"can i fly to crossroads","tal flight path","how to fly to crossroads"}},{q="What are wind riders?",a="Wind riders, commonly called wyverns, are sentient, venomous winged predators native to the crags of Kalimdor. Allied with the Horde since the Third War, they serve as the faction's primary aerial mounts.",al={"wyverns","what is a wind rider","tauren mounts"}},{q="Where does this courier errand lead next?",a="Once you deliver the goods to Tal, he instructs you to secure a mount and deliver Ahanu's parcel across the plains to Jahan Hawkwing waiting at the Crossroads.",al={"next quest","what after tal","where do leather goods go"}}},ang={["race:Tauren"]="The wind riders nesting on Thunder Bluff's bluffs represent the vital link keeping Cairne Bloodhoof's isolated people woven into the broader Horde coalition.",["faction:Horde"]="Establishing stable flight lines between the Barrens and Thunder Bluff ensures that reinforcements, trade wares, and messages can flow swiftly across central Kalimdor."},kw={"ahanu","crossroads","devrak","flight master","jahan","leather goods","tal","thunder bluff","wind rider"},rel={"npc:tal","npc:ahanu","quest:6364","subzone:crossroads","npc:devrak","zone:thunderbluff","quest:4767"},m={start="Ahanu",["end"]="Tal",level="10",faction="Horde",id=6363},src={"Tal the Wind Rider Master (Classic)"}}
E["quest:6364"] = {t="quest",n="Return to Jahan",z="thunderbluff",s="Return to Jahan marks the concluding leg of an introduction to the Horde's wind rider flight network between Mulgore and the Barrens. After visiting Thunder Bluff to deliver hides to the skinner Ahanu, travelers take a wyvern back to the Crossroads carrying finished leather wares for the merchant Jahan Hawkwing.",h="Return to Jahan marks the concluding leg of an introduction to the Horde's wind rider flight network between...",sec={{t="Wings Over Kalimdor",b="For many travelers, this errand is their first experience soaring aboard a trained wind rider. Tal, the wind rider master perched high atop Thunder Bluff's central mesa, arranges flights across the plains of central Kalimdor. As long as a traveler has already established contact with the roost at another settlement—such as Devrak's outpost at the Crossroads—these winged beasts can effortlessly cover leagues that would otherwise demand a perilous overland trek through the Red Rocks and northern Barrens.",sp=0},{t="Commerce of the Crossroads",b="The courier run serves an economic purpose alongside flight training. Jahan Hawkwing operates out of the bustling settlement of the Crossroads, where hunters, scouts, and mercenaries gather daily. Raw hides sent to Ahanu on the high rises of Thunder Bluff are refined into durable armor and equipment, then flown back to the dusty intersection of the Barrens to supply the Horde's expanding frontier efforts.",sp=0}},faq={{q="Who is Jahan Hawkwing?",a="Jahan Hawkwing is a tauren merchant stationed at the Crossroads in the Barrens. He buys and sells leather goods, relying on artisans in Thunder Bluff to turn raw beast hides into valuable gear for traveling adventurers.",al={"jahan","jahan hawkwing lore","who is jahan"}},{q="Why do I need to take a wind rider back to the Crossroads?",a="The journey demonstrates how the flight network operates. Wind rider masters like Tal in Thunder Bluff can only dispatch couriers and passengers to settlements they have personally scouted or connected with, such as Devrak's roost at the Crossroads.",al={"why fly back","wind rider return","how do flight paths work"}},{q="Who is Ahanu?",a="Ahanu is a skilled leatherworker and skinner located on the high bluffs of Thunder Bluff. He takes raw skins shipped from hunters in the Barrens and crafts them into finished goods before returning them for sale.",al={"ahanu","ahanu thunder bluff","who crafted the goods"}},{q="Who is Devrak?",a="Devrak is the orcish wind rider master stationed at the Crossroads. He manages the flight roost that connects the Barrens to major Horde bastions like Orgrimmar and Thunder Bluff.",al={"devrak","crossroads flight master","wind rider master devrak"}},{q="Can you use a wind rider without speaking to the destination master first?",a="No. Wind riders can only be dispatched to outposts where a traveler has already met and registered with the local wind rider master, establishing the connection between roosts.",al={"flight path rules","unlock flight master","can I fly anywhere"}},{q="What happens after returning the leather goods to Jahan?",a="Delivering the finished goods concludes the courier chain between Mulgore and the Barrens, leaving travelers familiar with air transit and free to continue assisting the garrison and merchants of the Crossroads.",al={"quest followup","what next","after return to jahan"}}},ang={["faction:Horde"]="The wind rider routes between Mulgore, Durotar, and the Barrens are the vital arteries binding the Horde's central Kalimdor territories together.",["race:Tauren"]="Trade chains between Mulgore tanners and Barrens outposts demonstrate how the united tribes support the Horde's broader frontier expansion."},kw={"ahanu","barrens","crossroads","devrak","jahan hawkwing","tal","thunder bluff","wind rider"},rel={"npc:jahan-hawkwing","npc:tal","npc:devrak","npc:ahanu","zone:thunderbluff","subzone:crossroads","quest:4767"},m={start="Tal",["end"]="Jahan Hawkwing",level="10",faction="Horde",id=6364},src={"Return to Jahan"}}
E["quest:742"] = {t="quest",n="The Ashenvale Hunt",z="thunderbluff",s="The Ashenvale Hunt is a summons dispatched to young Horde champions visiting Thunder Bluff, urging them north into the dense canopy of Ashenvale. Delivered by the city's heralds, the call directs travelers to report to Senani Thunderheart at Splintertree Post to take part in a proving hunt.",h="The Ashenvale Hunt is a summons dispatched to young Horde champions visiting Thunder Bluff, urging them north...",sec={{t="A Summons from the High Rise",b="Within the serene heights of Thunder Bluff, runners keep the burgeoning Horde informed of opportunities beyond the borders of Mulgore. Bluff Runner Windstrider carries an open invitation aimed at proven adventurers looking for greater challenges. With the Horde establishing footholds deep in the ancient forest north of the Barrens, young warriors are called upon to bolster those outposts and test their survival skills in a far harsher environment.",sp=0},{t="The Northern Frontier",b="Ashenvale represents both rich resources and severe peril for the Horde. Two prominent encampments anchor the faction's presence in the territory: Splintertree Post along the main road, and a remote outpost perched upon the western coast at Zoram Strand. Arriving at Splintertree Post puts incoming recruits directly under the wing of Senani Thunderheart, a veteran outdoorswoman organizing a massive hunt designed to tame the wilderness and claim glory for the Horde.",sp=0}},faq={{q="Who offers this quest in Thunder Bluff?",a="Bluff Runner Windstrider offers this assignment to passing adventurers in Thunder Bluff. His duty is to alert capable fighters to the Horde's expansion efforts and point them toward remote outposts in need of aid.",al={"who starts ashenvale hunt","quest giver ashenvale hunt","bluff runner windstrider"}},{q="Where is Splintertree Post located?",a="Splintertree Post is a fortified Horde settlement in eastern Ashenvale. To reach it, travel straight north across the Barrens border into Ashenvale, then follow the eastern forest trail as it leads deeper into the woods.",al={"splintertree post location","how to get to splintertree post","where is splintertree"}},{q="Who is Senani Thunderheart?",a="Senani Thunderheart is a seasoned tauren tracker stationed at Splintertree Post. She coordinates the hunting efforts in Ashenvale, testing the strength and patience of Horde recruits against the local predators.",al={"senani thunderheart","who is senani","thunderheart npc"}},{q="Why is the Horde hunting in Ashenvale?",a="The Horde maintains an active expansion into Ashenvale to gather timber and secure strategic territory. The hunt itself serves to thin the perilous wild beasts threatening their camps while allowing young adventurers to prove their mettle in unfamiliar terrain.",al={"why hunt in ashenvale","ashenvale hunt purpose","horde ashenvale goals"}},{q="What is the Zoram Strand mentioned in the briefing?",a="Zoram Strand is the Horde's coastal encampment on the far western shores of Ashenvale, facing the sea. It serves as a secondary naval foothold and bastion against naga and hostile forest dwellers.",al={"what is zoram strand","zoram strand outpost","zoram outpost"}},{q="What happens after reporting to Senani?",a="Once you report to Senani Thunderheart, she welcomes you to the outpost and immediately initiates you into the broader hunting tasks, directing you to stalk and conquer Ashenvale's fiercest beasts.",al={"what follows ashenvale hunt","next quest after senani","hunt continuation"}}},ang={["race:Tauren"]="For tauren who have spent their trials upon the open plains of Mulgore, the dense and shadowed canopy of Ashenvale presents an unfamiliar, sacred challenge under the watchful eyes of their kin like Senani.",["faction:Horde"]="Splintertree Post and Zoram Strand are vital staging grounds for the Horde's northern supply lines, relying on fresh recruits to keep the wild beasts and hostile natives at bay.",["class:Hunter"]="Ashenvale's untamed prowlers offer hunters a chance to master tracking in dense woodland, far different from the dry, open savannas of the south."},kw={"ashenvale","hunt","senani","splintertree","thunder bluff","thunderheart","windstrider","zoram strand"},rel={"npc:senani-thunderheart","npc:bluff-runner-windstrider","subzone:splintertree-post","zone:ashenvale","subzone:zoram-strand","zone:barrens","quest:1008","topic:horde"},m={start="Bluff Runner Windstrider",["end"]="Senani Thunderheart",level="20",faction="Horde",id=742},src={"The Ashenvale Hunt (Thunder Bluff)"}}
E["quest:766"] = {t="quest",n="Mazzranache",z="thunderbluff",s="Maur Raincaller in Bloodhoof Village has fallen victim to a venomous bite from Mazzranache, a legendary plainstrider that terrorized his grandfather a generation ago. Struck by fever and delirious nightmares, the tauren requires a potent remedy brewed from Mulgore's wildlife before the infection claims his life.",h="Maur Raincaller in Bloodhoof Village has fallen victim to a venomous bite from Mazzranache, a legendary...",sec={{t="A Legacy of the Plains",b="For years, Maur Raincaller regarded Mazzranache as little more than a harrowing family tale passed down by his grandfather. The elder tauren spoke of an unusually savage plainstrider armed with glowing red eyes, razor-sharp talons, and a toxic bite that defied the peaceful nature of most Mulgore wildlife. When Maur crossed paths with the beast out on the open grass, the legend proved all too real, leaving him severely wounded and struggling to make it back to safety.",sp=0},{t="Racing the Infection",b="The creature's venom works swiftly, inducing high fevers and nightmarish delirium. To purge the venom before it turns fatal, traditional tauren medicine relies on the vitality of the local beasts. Maur requires a prairie wolf heart, a flatland cougar femur, a plainstrider scale, and a swoop gizzard. By combining the essences of these varied hunters and scavengers, he can brew a concoction capable of halting the necrotic spread and nursing him back to health.",sp=0}},faq={{q="What is Mazzranache?",a="Mazzranache is an infamous plainstrider roaming the grasslands of Mulgore. Unlike common striders, it is known for vivid plumage, demonic red eyes, fierce talons, and an unusually venomous bite. It has terrorized travelers across multiple generations.",al={"who is mazzranache","what kind of beast is mazzranache","mazzranache lore"}},{q="Who is Maur Raincaller?",a="Maur Raincaller is a tauren residing in Bloodhoof Village. While crossing Mulgore, he was ambushed and bitten on the shoulder by Mazzranache, leaving him bedridden with a life-threatening, venomous infection.",al={"maur raincaller","who gave me this quest","who is the sick tauren"}},{q="Why does Maur need parts from four different beasts?",a="Traditional tauren remedies draw upon the natural strengths and spiritual essences of plains animals to neutralize potent toxins. The heart of a wolf, the dense marrow of a cougar femur, a plainstrider scale, and a swoop gizzard together form an antidote strong enough to counteract Mazzranache's venom.",al={"why wolf heart cougar femur","why animal ingredients","mazzranache remedy ingredients"}},{q="Did Maur's grandfather kill Mazzranache?",a="No. Maur's grandfather fought the fierce plainstrider years ago but was unable to defeat it, surviving only to pass down warning tales about its bright colors and vicious attacks to his descendants.",al={"did grandfather defeat mazzranache","maur grandfather mazzranache","who fought mazzranache before"}},{q="Does this quest ask me to hunt down Mazzranache itself?",a="No. Maur's immediate priority is surviving the fever. The task focuses entirely on gathering the components necessary to craft his cure rather than hunting down the legendary bird.",al={"do i kill mazzranache","where is mazzranache","hunt mazzranache"}},{q="Where is Bloodhoof Village located?",a="Bloodhoof Village lies in central Mulgore, south of Thunder Bluff and just east of Stonebull Lake. It serves as the primary settlement for young tauren braves setting out into the wider plains.",al={"where is bloodhoof village","bloodhoof village location"}}},ang={["race:Tauren"]="The remedy Maur crafts reflects the ancient tauren practice of drawing cures directly from the flora and fauna of the Earth Mother.",["class:Hunter"]="Tracking prairie wolves, cougars, plainstriders, and swoops across Mulgore provides a practical lesson in reading the plains and understanding the distinct wildlife of the savannah.",["faction:Horde"]="Securing Bloodhoof Village from the harsh dangers of Mulgore is vital for establishing peace and stability in the tauren homeland."},kw={"bloodhoof village","flatland cougar","maur raincaller","mazzranache","mulgore","plainstrider","prairie wolf","swoop"},rel={"npc:maur-raincaller","subzone:bloodhoof-village"},m={start="Maur Raincaller",level="8",faction="Horde",id=766},src={"Mazzranache (Classic)"}}
E["quest:768"] = {t="quest",n="Gathering Leather",z="thunderbluff",s="Gathering Leather is a straightforward trade request offered by Veren Tallstrider on the rises of Thunder Bluff. To sustain the capital and test young hunters, Veren exchanges a bundle of cured light leather skins for crafted goods. It highlights the deeply ingrained tauren tradition of turning the fruits of the plains hunt into essential clothing and armor.",h="Gathering Leather is a straightforward trade request offered by Veren Tallstrider on the rises of Thunder...",sec={{t="Sustaining Thunder Bluff",b="In the newly settled capital atop the high mesas of Mulgore, craftsmanship and survival walk hand in hand. Veren Tallstrider works skins into clothing and protective armor needed by the growing population of Thunder Bluff. Rather than harvesting everything himself, he encourages young adventurers heading out into the plains to bring back their quarry, turning mundane hunting into honorable civic service.",sp=0},{t="The Way of the Hunt",b="For the tauren, hunting beasts across the grasslands is not sport; it is an honorable endeavor that feeds, clothes, and shelters the tribe. Veren Tallstrider looks for hunters with a hunger to bring honor to their clan, asking specifically for light leather stripped from the local wildlife. In return for twelve well-kept hides, he repays the hunter with sturdy goods, reinforcing the mutual support that binds tauren society together.",sp=0}},faq={{q="Who is Veren Tallstrider?",a="Veren Tallstrider is a leatherworker residing in Thunder Bluff. He crafts garments and protective armor for the tauren people and trades his finished work with hunters who bring him fresh skins from the plains.",al={"veren tallstrider","who gives gathering leather","leather questgiver thunder bluff"}},{q="What does Veren Tallstrider need?",a="Veren asks for twelve pieces of light leather, harvested from the beasts roaming Mulgore and neighboring territories, to fashion goods for Thunder Bluff.",al={"gathering leather requirements","what to bring veren","gathering leather materials"}},{q="Where does this quest take place?",a="The quest begins and ends with Veren Tallstrider atop Thunder Bluff, though completing it requires hunting wild beasts across the grasslands below.",al={"where is veren tallstrider","gathering leather location"}},{q="Why do the tauren place so much importance on hunting beasts?",a="Tauren culture treats the hunt as a sacred balance with the Earth Mother. Every part of a fallen beast is put to use: flesh feeds the tribe, while bone and cured hides are fashioned into tools, tents, and durable armor.",al={"tauren hunting culture","why hunt leather","tauren leather lore"}},{q="Can any Horde adventurer undertake this task?",a="Yes, any traveler loyal to the Horde whom Veren considers eager to test their mettle on the plains can assist him with gathering leather.",al={"who can do gathering leather","is gathering leather horde only"}},{q="What happens once the leather is delivered?",a="Veren inspects the quality of the hides, commends the hunter for their work, and provides a crafted piece of gear in fair trade.",al={"gathering leather turn in","veren tallstrider reward"}}},ang={["race:Tauren"]="For tauren hunters, honoring the fallen beast by turning its hide into useful goods is a vital cultural discipline passed down through generations.",["class:Hunter"]="Hunters venturing out onto the plains of Mulgore naturally excel at tracking prey and harvesting the light hides Veren requires.",["faction:Horde"]="Providing raw materials to artisans in Thunder Bluff strengthens the young capital as it solidifies its defenses and trade networks."},kw={"gathering leather","leatherworking","light leather","mulgore","tauren hunt","thunder bluff","veren tallstrider"},rel={"zone:thunderbluff"},m={start="Veren Tallstrider",faction="Horde",id=768},src={"Gathering Leather"}}
E["quest:769"] = {t="quest",n="Kodo Hide Bag",z="thunderbluff",s="Kodo Hide Bag is a trade quest offered by Veren Tallstrider, a skilled tauren leatherworker atop the high mesas of Thunder Bluff. In exchange for fundamental crafting supplies, he passes on the traditional plains technique for stitching durable travel packs from sturdy beast hide. It serves as an early rite of passage for apprentice leathercrafters in Mulgore.",h="Kodo Hide Bag is a trade quest offered by Veren Tallstrider, a skilled tauren leatherworker atop the high...",sec={{t="A Lesson on the Mesa",b="Perched on Thunder Bluff's crafting rises, Veren Tallstrider upholds the long-standing nomadic tradition of wasting nothing from the hunt. To earn his tutelage, an aspiring leatherworker must present him with cured light leather and sturdy thread. By demonstrating their competence with foundational materials, apprentices prove they are ready to craft goods worthy of carrying survival gear across Kalimdor's rugged expanses.",sp=0},{t="Spirit of the Kodo",b="To the tauren, the kodo beast is an emblem of endurance, strength, and steady resolve. Its thick hide shields against brambles, biting wind, and beast claws alike. Crafting bags and garments from kodo hide is not merely a utilitarian act, but an expression of reverence for the animal that has nourished and carried the Shu'halo through countless generations across the plains of Mulgore.",sp=0}},faq={{q="Who offers the Kodo Hide Bag quest?",a="The quest is offered by Veren Tallstrider, a tauren leatherworking trainer and merchant located in Thunder Bluff.",al={"quest giver","where to get kodo hide bag quest","veren tallstrider location"}},{q="Who is eligible to undertake this task?",a="Only adventurers trained in Leatherworking who have reached at least apprentice skill level 10 can receive this training task from Veren Tallstrider.",al={"who can take this quest","quest requirements","profession requirement"}},{q="What materials does Veren Tallstrider require?",a="He requires four pieces of Light Leather and four spools of Coarse Thread to replenish his trade supplies before sharing his pattern.",al={"what items are needed","kodo hide bag materials","quest turn-in items"}},{q="Why is kodo hide considered significant to tauren crafters?",a="Kodos embody resilience and physical might, qualities deeply cherished by the tauren. Crafting durable equipment from their hides honors the creature's spirit while providing sturdy utility for travelers crossing the plains.",al={"why kodo hide","tauren kodo meaning","kodo importance"}},{q="What does Veren Tallstrider teach upon completion?",a="Upon receiving the supplies, Veren teaches the crafter the specialized knowledge required to stitch together a Kodo Hide Bag.",al={"quest reward","what do i get","bag pattern"}},{q="Where can the necessary materials be acquired?",a="Light Leather is obtained by skinning low-level beasts throughout Mulgore and adjacent territories, while Coarse Thread can be bought directly from trade and tailoring vendors.",al={"where to get light leather","where to get coarse thread"}}},ang={["race:Tauren"]="For the Shu'halo, learning to craft reliable gear from the mighty kodo is an essential step in honoring the Earth Mother's bounty and preserving ancestral ways.",["faction:Horde"]="Thunder Bluff's craftsmen supply essential logistical goods that keep Horde hunters, scouts, and warriors equipped across central Kalimdor."},kw={"coarse thread","kodo","kodo hide bag","leatherworking","light leather","mulgore","thunder bluff","veren tallstrider"},rel={"zone:thunderbluff","zone:mulgore"},m={start="Veren Tallstrider",faction="Horde",id=769},src={"Kodo Hide Bag (quest)"}}
E["quest:776"] = {t="quest",n="Rites of the Earthmother",z="thunderbluff",s="This trial, set directly by High Chieftain Cairne Bloodhoof, tasks rising heroes with hunting down the great kodo beast Arra'chea across the plains of Mulgore. Though an initiate may have completed the traditional rites of passage, Cairne expects his people to continually reaffirm their strength, tracking, and devotion to the tribe. Returning with Arra'chea's horn proves an adventurer is ready to serve the wider Horde beyond the mesas.",h="This trial, set directly by High Chieftain Cairne Bloodhoof, tasks rising heroes with hunting down the great...",sec={{t="A Chieftain's Measure",b="Reaching Thunder Bluff marks the end of simple youth for a tauren, but High Chieftain Cairne Bloodhoof does not let young hunters rest on their laurels. To Cairne, earning a place among the high bluffs is merely the beginning of one's responsibility to the United Tauren Tribes. Rather than sending initiates against petty pests, he demands proof of real fieldcraft: the tracking and clean harvest of one of Mulgore's most renowned wandering beasts.",sp=0},{t="The Hunt for Arra'chea",b="The quarry is Arra'chea, a massive, legendary kodo whose looping trek winds across the golden grasses northeast of Thunder Bluff. To fell such a creature takes more than brute force; it demands patient stalking across the open savannah and respect for a titan of the plains. Bringing Arra'chea's horn back to the high rise earns not just personal glory, but provisions for the city, as Cairne immediately dispatches skinners and gatherers to ensure nothing of the sacred beast goes to waste.",sp=0}},faq={{q="Who gives this quest?",a="High Chieftain Cairne Bloodhoof himself assigns this task from his seat atop the high rise of Thunder Bluff.",al={"quest giver","who gives rites of the earthmother","cairne quest"}},{q="What is Arra'chea?",a="Arra'chea is a formidable, renowned kodo who wanders the plains of Mulgore. His great horn serves as proof of a hunter's tracking capability and martial prowess.",al={"who is arrachea","what is arrachea","arrachea lore"}},{q="Where can I find Arra'chea?",a="Arra'chea typically roams in a broad circular path northeast of the bluffs of Thunder Bluff, slowly circling the open rolling plains in a clockwise route.",al={"where is arrachea","arrachea location","arrachea path"}},{q="Why does Cairne ask for this hunt after I already completed the earlier rites?",a="In tauren culture, earning one's initial place is not the end of duty. Cairne teaches that strength, humility, and hunting skill must be continually demonstrated to sustain the tribe.",al={"why do this quest","why kill arrachea","point of rites"}},{q="What happens to Arra'chea's body after the horn is taken?",a="In keeping with tauren traditions of honoring their prey, Cairne sends a gathering party to retrieve the fallen beast's meat and hide so that the kill feeds and clothes Thunder Bluff.",al={"arrachea meat","what happens to the kodo","carcass lore"}},{q="Is this the same quest as the early starter rites?",a="No. While the early trials in Camp Narache teach an initiate the foundational Rites of the Earthmother, this culminating trial in Thunder Bluff is Cairne's personal test of your ongoing worth as a hunter.",al={"rites of the earthmother differences","which rites quest","camp narache rites"}}},ang={["race:Tauren"]="Standing before Cairne Bloodhoof to claim the horn of Arra'chea is the ultimate rite of passage for a young shu'halo, proving that your prowess honors both your ancestors and the herds of Mulgore.",["class:Hunter"]="Stalking a solitary, wandering behemoth like Arra'chea across the golden plains embodies the ancient hunting philosophies that tauren trackmasters pass down through generations.",["faction:Horde"]="Felling Arra'chea provides essential sustenance, leather, and materials for Thunder Bluff, demonstrating the collective survival mindset that sustains the nascent Horde."},kw={"arra'chea","arrachea","bloodhoof","cairne","earthmother","horn","hunt","kodo","mulgore","thunder bluff"},rel={"npc:cairne-bloodhoof","zone:thunderbluff","zone:mulgore","quest:763","quest:421"},m={start="Cairne Bloodhoof",level="14",faction="Horde",id=776},src={"Rites of the Earthmother (3)"}}
E["quest:8360"] = {t="quest",n="Dancing for Marzipan",z="thunderbluff",s="Dancing for Marzipan is a festive Hallow's End quest offered by Innkeeper Pala in Thunder Bluff. To gather a sweet treat for a sick orphan, adventurers must put aside their battle-hardened dignity and perform a joyful dance for the innkeeper. It highlights the playful, community-focused spirit of the holiday even high upon the windswept mesas of Mulgore.",h="Dancing for Marzipan is a festive Hallow's End quest offered by Innkeeper Pala in Thunder Bluff.",sec={{t="A Dance on the Bluff",b="During the autumn festival of Hallow's End, spirits run high across Azeroth, even in the serene heights of Thunder Bluff. Innkeeper Pala, overseeing the hospitality of the high mesas, gets into the festive spirit by demanding a trick before handing out any treats. Even when an adventurer arrives on behalf of an ailing child, tradition holds firm: Pala insists on seeing some festive dancing before parting with her prized Thunder Bluff Marzipan.",sp=0},{t="Tricks for Treats",b="The holiday custom of exchanging amusement for confections brings out a rare, lighthearted side of Horde culture. Pala's request requires nothing more than stepping forward, shaking loose the road weariness, and busting out your best moves. Upon being thoroughly entertained, the innkeeper gladly surrenders the marzipan and offers her warm wishes for the sick youth awaiting the treat.",sp=0}},faq={{q="What is the purpose of Dancing for Marzipan?",a="The quest tasks you with performing a dance emote for Innkeeper Pala in Thunder Bluff. In return, she gives you a piece of Thunder Bluff Marzipan, which is part of a broader collection of holiday treats gathered for a sick orphan during Hallow's End.",al={"why dance for marzipan","marzipan quest goal","dancing for marzipan objective"}},{q="Who gives this quest?",a="Innkeeper Pala, the tauren innkeeper serving visitors and locals within Thunder Bluff, offers this quest during the Hallow's End holiday.",al={"who starts dancing for marzipan","pala quest","innkeeper pala thunder bluff"}},{q="Why does Pala insist on a dance if the candy is for a sick child?",a="Pala emphasizes that holiday traditions must be respected, even for noble errands. In the spirit of trick-or-treating, one must perform a trick to earn the sweet reward, ensuring that Hallow's End remains joyous and lively.",al={"why do i have to dance","why does pala want a dance"}},{q="What reward do you receive for dancing?",a="You receive a piece of Thunder Bluff Marzipan, a local festive confection required to complete the overarching Hallow's End treat collection for the sick child.",al={"marzipan reward","dancing for marzipan item"}},{q="Can Alliance players complete this quest?",a="No. Innkeeper Pala is a Horde vendor residing in the heart of Thunder Bluff, making this specific stop on the holiday treat run accessible only to members of the Horde.",al={"is this horde only","alliance dancing for marzipan"}},{q="When is this quest available?",a="This quest is only available during the annual autumn holiday of Hallow's End, when innkeepers across Azeroth offer special confectionery and festive games.",al={"when can i get marzipan","hallows end marzipan quest"}}},ang={["race:Tauren"]="Innkeeper Pala brings traditional holiday cheer straight to Mulgore, proving that even towering, stoic tauren can enjoy a good dance for a sweet cause.",["faction:Horde"]="A lighter moment in the Horde's harsh daily struggles, showing the faction's heart as travelers roam across capital cities to bring holiday joy to an orphan."},kw={"dancing for marzipan","hallow's end","innkeeper pala","marzipan","mulgore","thunder bluff","trick-or-treat"},rel={"npc:innkeeper-pala","zone:thunderbluff"},m={start="Innkeeper Pala",faction="Horde",id=8360},src={"Dancing for Marzipan (Horde)"}}
E["quest:853"] = {t="quest",n="Apothecary Zamah",z="thunderbluff",s="This errand sends an adventurer racing from the arid Barrens to Thunder Bluff carrying a volatile, rendered fungal emulsion. Apothecary Helbrim needs the potent mixture delivered swiftly to his colleague, Apothecary Zamah, tucked away in the shadowy depths beneath Spirit Rise.",h="This errand sends an adventurer racing from the arid Barrens to Thunder Bluff carrying a volatile, rendered...",sec={{t="A Fragile Cargo",b="After studying the peculiar fungal blooms thriving across the oases of the Barrens, Apothecary Helbrim cooks down a batch into a delicate emulsion. The unstable brew degrades rapidly once prepared. Lacking the time to travel to Mulgore himself, Helbrim entrusts the flask to a reliable runner to make the climb up the bluffs before the solution loses its chemical potency.",sp=0},{t="Under the Gazes of the Shamans",b="Apothecary Zamah maintains her laboratory far from the open plains of Mulgore, sequestered inside the Pools of Vision. This subterranean cavern rests deep beneath the sacred heights of Spirit Rise, shared with secretive warlocks and contemplative seers. Here, beneath the floor of the tauren sanctuary, the Royal Apothecary Society quietly conducts its research using raw materials gathered throughout the continent.",sp=0}},faq={{q="Why is there a time limit on this delivery?",a="Helbrim's rendered fungal emulsion is chemically volatile. Left exposed or untreated for too long, the compounds break down and lose their potency, rendering the mixture useless for Zamah's work.",al={"why timed","quest timer","rendered spores timer"}},{q="Where can I find Apothecary Zamah?",a="Apothecary Zamah is located inside the Pools of Vision in Thunder Bluff. The entrance to this cavern is somewhat concealed on Spirit Rise, leading down beneath the tents of the shamans.",al={"where is zamah","zamah location","find zamah"}},{q="Who is Apothecary Helbrim?",a="Apothecary Helbrim is an alchemist representing the Royal Apothecary Society stationed at the Crossroads in the Barrens. He analyzes local flora and fauna to see how Kalimdor's native organisms might serve the Forsaken.",al={"who is helbrim","helbrim crossroad"}},{q="What is the Royal Apothecary Society doing in Thunder Bluff?",a="As allies within the Horde, the Forsaken station representatives like Zamah in Thunder Bluff. Operating quietly in the subterranean Pools of Vision, they analyze specimens gathered across Kalimdor and maintain supply links with other outposts.",al={"why forsaken in thunder bluff","apothecaries in pools of vision"}},{q="What were the fungal spores originally used for?",a="The spores grow around the lush oases in the Barrens, flourishing unnaturally in the desert. Helbrim rendered them down to study their biological traits and alchemical applications before handing them off to Zamah.",al={"why spores","barrens fungi use"}},{q="What happens if the timer runs out?",a="If the timer expires, the emulsion degrades and spoils. You must return to Apothecary Helbrim at the Crossroads to acquire a fresh batch to deliver to Thunder Bluff.",al={"failed timer","spores expired"}}},ang={["race:Undead"]="Carrying Helbrim's work to Zamah strengthens the clandestine research network the Royal Apothecary Society maintains across the dusty frontier of central Kalimdor.",["race:Tauren"]="While welcoming their new allies, traditional tauren often look askance at the strange bubbling concoctions the Forsaken brew deep inside the sacred Pools of Vision.",["faction:Horde"]="Swift communication between outposts in the Barrens and the high mesa of Thunder Bluff ensures regional supply chains stay linked."},kw={"apothecary helbrim","apothecary zamah","fungal spores","pools of vision","rendered spores","royal apothecary society","spirit rise","the barrens","thunder bluff"},rel={"quest:848","npc:apothecary-helbrim","subzone:pools-of-vision","subzone:spirit-rise","zone:thunderbluff","zone:barrens"},m={level="15",faction="Horde",id=853},src={"Apothecary Zamah (quest)"}}
E["quest:860"] = {t="quest",n="Sergra Darkthorn",z="thunderbluff",s="Having proven their basic tracking and stalking skills in the rolling hills of Mulgore, young tauren are directed outward into the arid wilderness of the Barrens. Melor Stonehoof sends aspiring hunters north of the border to report to Sergra Darkthorn at the Crossroads. This journey marks the hunter's formal transition from local trials to the demanding predatory hierarchy of Kalimdor's broader plains.",h="Having proven their basic tracking and stalking skills in the rolling hills of Mulgore, young tauren are...",sec={{t="Leaving the Sacred Hills",b="For a novice tauren hunter, completing initial rites in Mulgore is only the beginning. The lush valleys of their ancestral homeland are protected and familiar, nurturing beasts that test patience rather than sheer survival. Melor Stonehoof recognizes when a hunter's spirit has grown enough to require harsher trials. He instructs his pupils to pack their gear, leave the safety of Bloodhoof Village, and venture east across the mountain pass into the baked scrublands of the Barrens.",sp=0},{t="The Road to the Crossroads",b="The path through the red rock canyons leads straight into the wide, sun-scorched savanna where the young Horde stakes its claim. At the intersection of Kalimdor's central trade routes lies the Crossroads, a fortified settlement bustling with orcs, trolls, and tauren. There waits Sergra Darkthorn, an experienced orc shaman renowned for her unforgiving standards. She acts as a mentor to any bold enough to stalk the Barrens' fierce fauna, promising to temper raw eagerness into hardened wilderness discipline.",sp=0}},faq={{q="Who gives this quest and where do I find them?",a="The quest is given by Melor Stonehoof, a tauren hunter mentor who resides on the Hunter Rise in Thunder Bluff.",al={"who gives sergra darkthorn quest","melor stonehoof location","where to start"}},{q="Where is Sergra Darkthorn located?",a="Sergra Darkthorn is stationed at the Crossroads in the central Barrens, standing near the eastern side of the settlement near the watchtowers and corrals.",al={"sergra darkthorn location","where is sergra","find sergra"}},{q="How do I get to the Crossroads from Mulgore?",a="Leave Thunder Bluff heading south past Bloodhoof Village, then take the eastern road out of Mulgore through the canyon pass into the Barrens. Once past the border gate, follow the main dirt road east until it forks, then head north until you reach the Crossroads.",al={"directions to crossroads","mulgore to barrens","how to get to crossroads from thunder bluff"}},{q="What is the purpose of this quest?",a="It serves as a breadcrumb quest guiding players who began their journey in Mulgore toward the next major leveling hub at the Crossroads in the Barrens, connecting them with local hunting questlines.",al={"why do this quest","sergra darkthorn purpose","is this a breadcrumb"}},{q="Do orcs and trolls get this quest?",a="Orcs and trolls receive a parallel breadcrumb quest called 'Conscript of the Horde' in Durotar, which sends them to the Barrens from Razor Hill, though they can still meet and take quests from Sergra once they arrive.",al={"orc version","troll version","durotar breadcrumb"}},{q="What does Sergra Darkthorn teach hunters?",a="Sergra tests incoming hunters against the indigenous fauna of the Barrens, starting with plainstriders and prowlers, teaching that true mastery requires endurance, respect for the land, and mental resilience rather than brute force.",al={"sergra role","what does sergra do","sergra hunting"}}},ang={["race:Tauren"]="For tauren who grew up in the verdant pastures of Mulgore, reporting to Sergra marks their first significant venture beyond their ancestral borders into the demanding service of the broader Horde.",["class:Hunter"]="This journey represents the graduation from simple local game tracking to mastering the aggressive predators and harsh conditions of Kalimdor's interior savannas.",["faction:Horde"]="The Crossroads serves as the beating logistical heart of the young Horde, binding together orcish resilience, darkspear cunning, and tauren tradition under the gaze of veterans like Sergra."},kw={"crossroads","hunter's way","melor stonehoof","mulgore","plainstrider","sergra darkthorn","the barrens","thunder bluff"},rel={"npc:melor-stonehoof","subzone:crossroads","zone:barrens","zone:mulgore","quest:840","topic:tauren","topic:horde","subzone:bloodhoof-village"},m={start="Melor Stonehoof",["end"]="Sergra Darkthorn",level="10",faction="Horde",id=860},src={"Sergra Darkthorn (quest)"}}
E["quest:8678"] = {t="quest",n="Wheathoof the Elder",z="thunderbluff",s="Wheathoof the Elder is an ancestral tauren spirit honored during the Lunar Festival atop the heights of Thunder Bluff. Visiting him is an act of deep reverence, acknowledging the wisdom of the ancestors who watch over Mulgore and the Horde.",h="Wheathoof the Elder is an ancestral tauren spirit honored during the Lunar Festival atop the heights of...",sec={{t="A Spirit of Mulgore",b="Perched high on the windblown mesas of Thunder Bluff, Wheathoof the Elder manifests as an ancestral presence during the Lunar Festival. Tauren culture holds the voices of their ancestors in the highest regard, believing that the spirits of ancient leaders and sages linger to offer guidance and strength to the living.",sp=0},{t="Homage and Ancestral Blessing",b="Travelers who climb the heights to pay their respects to Elder Wheathoof are greeted not as strangers, but as vital flames of life. In exchange for the traveler's homage, the elder bestows a Coin of Ancestry, symbolizing communion between the enduring past and the living champions fighting for the world's future.",sp=0}},faq={{q="Who is Wheathoof the Elder?",a="He is an honored tauren ancestral spirit manifested atop the city of Thunder Bluff during the Lunar Festival to receive homage from champions across Azeroth.",al={"wheathoof","elder wheathoof","who is wheathoof"}},{q="Where can I find Wheathoof the Elder?",a="Elder Wheathoof resides in the tauren capital of Thunder Bluff, located on the sweeping central mesas overlooking the plains of Mulgore.",al={"where is elder wheathoof","wheathoof location","thunder bluff elder"}},{q="What is the purpose of visiting him?",a="Visiting Elder Wheathoof allows players to honor the spirits of the past during the Lunar Festival, receiving his blessing and a Coin of Ancestry in return.",al={"why visit wheathoof","wheathoof quest","lunar festival elder"}},{q="Can Alliance players visit Elder Wheathoof?",a="While the spirit will bestow his blessing upon any respectful traveler, entering Thunder Bluff as an Alliance adventurer is extremely perilous due to the vigilant city guards and Horde defenders.",al={"can alliance talk to wheathoof","alliance thunder bluff elder"}},{q="What is a Coin of Ancestry?",a="It is a ceremonial token granted by the ancient spirits during the Lunar Festival, symbolizing respect and communion between the living and the ancestors.",al={"coin of ancestry","lunar festival coin"}},{q="How do the tauren view their elders?",a="Tauren revere their ancestors as guardians and teachers whose spiritual presence remains woven into the land, offering continuous guidance to those attuned to the Earth Mother.",al={"tauren ancestor worship","tauren elders lore"}}},ang={["race:Tauren"]="Honoring Elder Wheathoof is a sacred homecoming for tauren champions, reaffirming their eternal bond with the spirits watching over Mulgore.",["faction:Horde"]="Located at the heart of tauren power, this elder welcomes all allies of the Horde who ascend Thunder Bluff to pay homage.",["class:Shaman"]="For a shaman, communing with an ancestral elder is a profound ritual of communion with the enduring spirit world."},kw={"ancestor","coin of ancestry","elder","lunar festival","mulgore","spirit","thunder bluff","wheathoof"},m={id=8678},src={"Wheathoof the Elder"}}
E["quest:886"] = {t="quest",n="The Barrens Oases",z="thunderbluff",s="High on the Elder Rise of Thunder Bluff, Arch Druid Hamuul Runetotem senses an unsettling surge of power flowing into the arid soils of the Barrens. To uncover the truth, he dispatches promising travelers eastward past Mulgore's gates to rendezvous with his kinsman, Tonga Runetotem, at the Crossroads. This mission marks the beginning of an investigation into the unnatural waters springing up across the sun-baked plains.",h="High on the Elder Rise of Thunder Bluff, Arch Druid Hamuul Runetotem senses an unsettling surge of power...",sec={{t="A Disturbance in the Drought",b="While the plains of Mulgore flourish under the watchful gaze of the Earth Mother, the vast savannas of the Barrens to the east have remained harsh, scorched, and dry for generations. Recently, however, the tauren druids meditating atop Thunder Bluff's Elder Rise have detected strange currents of energy waking deep beneath the parched plains. Life is stirring where it ought not to be, and the Cenarion Circle fears that whatever force is causing this surge may harbor hidden peril for the land and its creatures.",sp=0},{t="East Beyond the Great Gate",b="To investigate these strange occurrences, Arch Druid Hamuul Runetotem dispatched Tonga Runetotem into the field. Recognizing that the vast wilderness holds dangers too great for one investigator alone, Hamuul enlists travelers leaving Mulgore to hasten after Tonga. Following the road east past Bloodhoof Village and through the mountain passes leads straight to the Crossroads—the dusty, bustling heart of Horde territory in the Barrens—where Tonga awaits answers.",sp=0}},faq={{q="Why is Hamuul Runetotem concerned about the Barrens?",a="Hamuul and the druids of Thunder Bluff have sensed an unnatural surge of power bleeding into the soil of the Barrens. The sudden quickening of life in such a dry, unforgiving climate suggests that unusual forces are at work beneath the surface.",al={"why barrens oases","hamuul concern","why send to cross roads"}},{q="Where can I find Tonga Runetotem?",a="Tonga Runetotem is stationed at the Crossroads in the central Barrens. To find him, follow the main eastern road leading out of Mulgore, cross into the Barrens, and take the northern branch of the trail until reaching the settlement.",al={"tonga runetotem location","where is tonga","tonga crossroads"}},{q="Is this quest only available to tauren?",a="Arch Druid Hamuul Runetotem offers this quest primarily to travelers emerging from Mulgore. However, adventurers of any Horde race can meet Tonga directly at the Crossroads to assist in investigating the oases.",al={"can non tauren get barrens oases","who gives the barrens oases"}},{q="What awaits at the end of the road from Bloodhoof Village?",a="Leaving Bloodhoof Village to the east leads past the Great Gate separating Mulgore from the Barrens. Once past the mountains, turning north at the fork brings you safely through the harsh wilderness into the Crossroads.",al={"road to crossroads","mulgore to barrens path"}},{q="What are the strange powers Hamuul senses?",a="The druids sense magical currents creating verdant, spring-fed oases across a desert landscape known for bitter drought. Tonga Runetotem was sent to find whether this growth is a blessing or a dangerous corruption.",al={"what powers in barrens","oases mystery","unnatural energy barrens"}},{q="Why are the Barrens considered so dangerous for young adventurers?",a="The Barrens is an expansive, predator-infested frontier prowled by raptors, plainstriders, and hostile centaur tribes. Hamuul warns travelers to stick strictly to the patrolled trade paths to avoid being overwhelmed by the harsh wilderness.",al={"barrens danger","why stay on road"}}},ang={["race:Tauren"]="For tauren venturing beyond the sacred meadows of Mulgore for the first time, this task represents their rite of passage into the broader duties of protecting the balance of Kalimdor.",["class:Druid"]="As the first students trained under Hamuul Runetotem, young druids are entrusted by their Arch Druid to heed the whispers of the earth and heal wounds in the fragile balance of nature.",["faction:Horde"]="The Crossroads serves as the vital lifeline connecting the Horde's western holdings to the coast, making any magical disruption nearby a matter of deep strategic and spiritual concern."},kw={"bloodhoof village","cenarion circle","crossroads","elder rise","hamuul runetotem","mulgore","oases","the barrens","thunder bluff","tonga runetotem"},rel={"npc:tonga-runetotem","quest:870","zone:barrens","subzone:crossroads","zone:thunderbluff","topic:druid","topic:tauren","zone:mulgore"},m={start="Arch Druid Hamuul Runetotem",["end"]="Tonga Runetotem",level="10",faction="Horde",id=886},src={"The Barrens Oases"}}
E["quest:9264"] = {t="quest",n="Investigate the Scourge of Thunder Bluff",z="thunderbluff",s="Investigate the Scourge of Thunder Bluff is a defensive mission issued by the Argent Dawn outside the tauren capital. As the Lich King's airborne necropolises menace the skies of Kalimdor, defenders are tasked with culling invading undead and discovering the purpose of strange glowing runic circles on the bluffs below.",h="Investigate the Scourge of Thunder Bluff is a defensive mission issued by the Argent Dawn outside the tauren...",sec={{t="A Plague on the Mesas",b="The Scourge invasion does not discriminate between the fractured kingdoms of Lordaeron and the peaceful plains of Mulgore. When the Lich King dispatches necropolises to hover menacingly over major settlements across the world, Thunder Bluff finds itself directly threatened. Lieutenant Lisande of the Argent Dawn calls upon able-bodied Horde champions to confront the encroaching horrors encamped beneath the great city's shadows.",sp=0},{t="Runic Whispers",b="Beyond simply cutting down ranks of marching corpses and gathering dim necrotic stones as trophies of war, investigators must inspect the glowing runic circles that hum with foul power near the enemy camps. Stepping near these arcane conduits exposes the mind to eerie voices carrying across vast distances, revealing that the circles serve as dark telepathic relays linking the field forces to the grim minds directing the invasion.",sp=1}},faq={{q="Who offers this quest?",a="Lieutenant Lisande, an officer serving with the Argent Dawn stationed near Thunder Bluff, assigns this mission to help repel the surrounding Scourge forces.",al={"quest giver","who gives quest","lieutenant lisande"}},{q="Why is the Scourge attacking Thunder Bluff?",a="The Lich King has mobilized floating necropolises to strike simultaneously at population centers across Azeroth, seeking to overwhelm and eradicate the living on every continent, including the Horde bastions in Kalimdor.",al={"why mulgore","why attack tauren","scourge in thunder bluff"}},{q="What are the glowing runic circles used for?",a="The glowing runic circles function as dark magical relays used by the Scourge to communicate directly with distant necropolises or the necromancers and overseers commanding the assault.",al={"runic circles","what do circles do","glowing runes purpose"}},{q="What are Dim Necrotic Stones?",a="Dim Necrotic Stones are fragments carried by lesser Scourge invaders that thrum with necromantic energy. The Argent Dawn collects them as proof of the dead being slain and to study the foul magic sustaining them.",al={"necrotic stones","dim necrotic stone","what are stones"}},{q="Why is the Argent Dawn here in Mulgore?",a="The Argent Dawn is a neutral organization devoted entirely to stopping the Scourge. Because the invasion threatens every living mortal, Argent Dawn officers coordinate defense efforts alongside both the Horde and the Alliance.",al={"argent dawn mulgore","argent dawn horde"}},{q="Do I have to climb the floating necropolis for this mission?",a="No. The investigation takes place entirely on the ground near the encampments beneath the floating necropolis, where the runic circles and foot soldiers are gathered.",al={"go inside necropolis","enter necropolis"}}},ang={["race:Tauren"]="The Earth Mother's sacred plains are violated by floating citadels and rotting corpses, making the defense of the bluffs a sacred duty for every tauren.",["faction:Horde"]="With the war front spreading to Mulgore, Horde defenders must demonstrate that their territory will not collapse under the Lich King's sudden offensive.",["class:Shaman"]="The vile necromantic circles pervert the natural spirits of the earth, demanding that shamanic protectors cleanse the corruption spreading across the soil."},kw={"argent dawn","lich king","lisande","mulgore","necrotic stone","runic circle","scourge","thunder bluff"},rel={"npc:lieutenant-lisande","topic:argent-dawn","zone:thunderbluff","topic:scourge","topic:lich-king"},m={start="Lieutenant Lisande",level="10",faction="Horde",id=9264},src={"Investigate the Scourge of Thunder Bluff"}}
E["subzone:elder-rise"] = {t="subzone",n="Elder Rise",z="thunderbluff",s="Elder Rise sits directly east of Thunder Bluff's central plateau, reachable across long suspension bridges from both the High and Middle Rises. It serves as the spiritual heart of the tauren capital, hosting the Cenarion Circle, tauren druids and priests, and the governing Council of Elders.",h="Elder Rise sits directly east of Thunder Bluff's central plateau, reachable across long suspension bridges...",sec={{t="Sanctuary of Faith and Council",b="Connected to the main mesas by swaying rope bridges, Elder Rise is dedicated to quiet reflection, sacred wisdom, and civic governance. Tauren druids and priests gather here to teach acolytes the ways of nature and spiritual devotion. High atop this mesa resides Arch Druid Hamuul Runetotem, the revered leader who brought druidism back to the tauren people and forged close ties with the Cenarion Circle. Alongside these wild sanctuaries stands the Hall of Elders, where tribal leaders convene to deliberate on matters facing their fledgling capital.",sp=0},{t="A Precarious Presence",b="Despite its role as a peaceful sanctuary, political tension lingers over the rise. Magatha Grimtotem, elder matriarch of the secretive and haughty Grimtotem tribe, maintains her residence in a hut positioned between the two bridges. While Cairne Bloodhoof extends hospitality and formal council seats to all tauren lineages, her watchful presence serves as a constant reminder that not every tribe embraces the Bloodhoof's pacifist ideals or unquestioning alliance with the Horde.",sp=0}},faq={{q="What is Elder Rise used for?",a="Elder Rise serves as the center for spiritual learning and civic deliberation in Thunder Bluff. It houses the Cenarion Circle's druids, tauren priests, the governing Council of Elders, and tribal leaders.",al={"purpose of elder rise","what is on elder rise","elder rise buildings"}},{q="Who leads the druids on Elder Rise?",a="Arch Druid Hamuul Runetotem resides here. A close friend and advisor to Cairne Bloodhoof, Hamuul is the highest-ranking tauren in the Cenarion Circle and trains those called to walk the path of nature.",al={"archdruid thunder bluff","tauren druid leader","hamuul location"}},{q="Why does Magatha Grimtotem stay here?",a="Magatha Grimtotem occupies a tent situated between the bridges. As the elder crone and chieftain of the Grimtotem tribe, she attends the Council of Elders to represent her people in Thunder Bluff, despite mutual distrust between her clan and Cairne's allies.",al={"where is magatha","magatha grimtotem location","grimtotem on elder rise"}},{q="How do you reach Elder Rise?",a="Elder Rise lies directly east of the city's central plateau. It can be reached via large wooden rope bridges connected to both the High Rise and the lower plateau.",al={"getting to elder rise","elder rise bridges","directions elder rise"}}},ang={["class:Druid"]="Elder Rise is the paramount home for Horde druids, serving as Arch Druid Hamuul Runetotem's sanctuary and the Cenarion Circle's regional seat in Kalimdor.",["race:Tauren"]="The rise houses the Council of Elders and spiritual guides who steer your tribes through peace, tradition, and the complex realities of the Horde."},kw={"cenarion circle","elder rise","hall of elders","hamuul runetotem","magatha grimtotem","mulgore","thunder bluff"},rel={"zone:thunderbluff","quest:1489","npc:magatha-grimtotem","topic:cenarion-circle","topic:druid","subzone:high-rise","topic:tauren","topic:grimtotem-tribe"},src={"Elder Rise"}}
E["subzone:high-rise"] = {t="subzone",n="High Rise",z="thunderbluff",s="The High Rise is the uppermost tier of Thunder Bluff's central mesa, crowning the tauren capital. It hosts a bustling amphitheater centered around a communal bonfire alongside seasoned artisans, weapon merchants, and culinary masters. Unlike the lower tiers, this summit relies entirely on suspension rope bridges and the wind rider roost for travel.",h="The High Rise is the uppermost tier of Thunder Bluff's central mesa, crowning the tauren capital.",sec={{t="Summit of the Mesa",b="The High Rise perches atop Thunder Bluff's core plateau, catching the open winds high above the rolling plains of Mulgore. A focal gathering point for the united tribes, it centers around an open-air amphitheater and fire pit where citizens listen to important tribal announcements and fateful decisions. The surrounding tents and wooden stalls house renowned merchants, armories, and culinary trainers, including Aska's Kitchen and Mountaintop Bait & Tackle. While the lower tiers connect directly to Mulgore's prairie floor via massive wooden elevators, the High Rise stays aloft, accessible primarily through the wind rider roost and sweeping rope bridges linking to the neighboring Elder Rise and Hunter Rise.",sp=0}},faq={{q="How do you reach the High Rise?",a="You can reach the High Rise by taking the central tower elevators from the lower tiers of the city up to the wind rider roost, or by crossing the great wooden suspension bridges that stretch across the open sky from Elder Rise and Hunter Rise. Unlike the lower bluffs, there are no ground lifts running directly from the Mulgore plains to the High Rise.",al={"how to get to high rise","high rise access","getting up to high rise"}},{q="What services are found on the High Rise?",a="The tier is known for its tradesfolk and outdoor gathering places. Notable establishments include Aska's Kitchen for cooking instruction, Mountaintop Bait & Tackle for fishing gear, and various weapon merchants like Ragetotem Arms and Thunderhoof's Firearms.",al={"trainers on high rise","shops high rise","what is on high rise"}},{q="What is the amphitheater on the High Rise used for?",a="The open-air amphitheater surrounds a central bonfire, serving as a communal gathering area. Here, the tauren people assemble beneath the open sky to hear news, deliberate tribal affairs, and witness important proclamations delivered atop the mesa.",al={"high rise bonfire","high rise auditorium","tauren meeting place"}}},ang={["profession:Cooking"]="The High Rise is home to Aska's Kitchen and renowned pit masters, making it the primary destination in Thunder Bluff to hone your culinary skills over open flame.",["race:Tauren"]="As the crest of your capital city, the High Rise represents unity among the tribes, gathering hunters, shamans, and elders around its high communal fire."},kw={"amphitheater","aska's kitchen","bonfire","high rise","mulgore","thunder bluff","wind rider roost"},rel={"zone:thunderbluff","zone:mulgore","subzone:elder-rise","subzone:hunter-rise","quest:4767"},src={"High Rise"}}
E["subzone:hunter-rise"] = {t="subzone",n="Hunter Rise",z="thunderbluff",s="Hunter Rise is one of the elevated mesas making up the city of Thunder Bluff, situated just south of the central bluff. It serves as the primary training and gathering ground for the tauren's warriors, hunters, trackers, and skinners. Across its windswept platforms, young braves hone their martial skills and prepare for combat.",h="Hunter Rise is one of the elevated mesas making up the city of Thunder Bluff, situated just south of the...",sec={{t="The Gathering of Braves",b="Connected to the neighboring bluffs by swaying rope bridges, Hunter Rise is dedicated to the martial traditions of the tauren. It is anchored by the Hunter's Hall, where experienced marksmen, trackers, and warriors pass down their discipline to younger generations. Surrounding the lodge are practice grounds outfitted with training dummies, weapon racks, and skinning posts, making it a bustling center for those who live by spear, bow, and hide.",sp=0},{t="Martial Duty and Defense",b="Beyond hunting wild game across the plains of Mulgore, the inhabitants of Hunter Rise help ensure the defense of Thunder Bluff and the wider Horde. Battlemasters stationed along the rise recruit seasoned fighters to answer the call of skirmishes against Alliance incursions across contested battlegrounds. It remains an essential rallying point for anyone sworn to protect the herd.",sp=0}},faq={{q="Where is Hunter Rise located?",a="Hunter Rise is located on the southern side of Thunder Bluff. It is reached by crossing the wooden rope bridges that connect it to the lower rise and high rise mesas of the city.",al={"where is hunter rise","hunter rise location","how to get to hunter rise"}},{q="Who lives and trains on Hunter Rise?",a="The mesa is home to tauren hunters, warriors, trackers, trappers, and leatherworkers. In addition to class and profession trainers, Horde battlemasters make their stand here to recruit fighters for the faction's wars.",al={"who is on hunter rise","hunter rise trainers","what is on hunter rise"}},{q="What is the Hunter's Hall?",a="The Hunter's Hall is the primary longhouse on the rise where seasoned hunters and warriors congregate. It serves as an armory, school, and hearth for those learning the ways of tracking, marksmanship, and close combat.",al={"hunters hall","hunters lodge thunder bluff","thunder bluff hunter hall"}},{q="Can members of the Alliance visit Hunter Rise?",a="No. Thunder Bluff is a major Horde capital city, and Hunter Rise is guarded by seasoned tauren braves. Any Alliance adventurer attempting to cross its bridges will be attacked immediately by city guards.",al={"alliance on hunter rise","can alliance go to hunter rise"}}},ang={["class:Hunter"]="For young tauren hunters, this rise is the natural heart of your calling in the capital, providing training, pet supplies, and guidance from master trackers.",["class:Warrior"]="The grounds of Hunter Rise provide training dummies, combat mentors, and battlemasters eager to test your strength in the ongoing defense of the Horde."},kw={"battlemasters","hunter rise","hunter's hall","mulgore","thunder bluff","trackers"},rel={"zone:thunderbluff","subzone:high-rise","topic:tauren","topic:alliance"},src={"Hunter Rise"}}
E["subzone:pools-of-vision"] = {t="subzone",n="Pools of Vision",z="thunderbluff",s="The Pools of Vision are a subterranean cavern nestled beneath Spirit Rise in Thunder Bluff. Marked by still waters and dim caverns, this secluded subterranean space serves as the primary enclave for the Forsaken within the tauren capital.",h="The Pools of Vision are a subterranean cavern nestled beneath Spirit Rise in Thunder Bluff.",sec={{t="A Haven Beneath the Mesa",b="While the sunlit peaks of Thunder Bluff belong to the wind, earth, and sky, the Pools of Vision plunge directly beneath Spirit Rise into shadowy seclusion. Accessible from a discreet cave path off the bridge leading to the rise, this subterranean grotto offers subterranean respite quite unlike the open-air lodges above. Here, misty waters pool in the dark, creating an isolated atmosphere where Horde spellcasters gather far from the bustling central mesas.",sp=0},{t="The Undead Outpost",b="Within Thunder Bluff, the Pools of Vision function as the de facto base of operations for the Forsaken. Travelers from the eastern continent find kindred souls here: undead priests practicing their shadowed arts, mages conjuring arcane portals, and emissaries of the Defilers seeking recruits for their campaigns in the Arathi Highlands. Whether tucked away by tauren skepticism or by the Forsaken's own natural preference for the dark, this quiet refuge bridges Lordaeron's undead with their Kalimdor allies.",sp=0}},faq={{q="Where is the entrance to the Pools of Vision?",a="The entrance is a cave mouth located on Spirit Rise, situated immediately to the right just after crossing the wooden rope bridge leading from the lower mesa.",al={"how to get to pools of vision","pools of vision entrance","where are pools of vision"}},{q="Why are the Forsaken living down here?",a="The cavern serves as the central hub for Forsaken stationed in Thunder Bluff. It provides shelter away from the harsh Kalimdor sunlight and accommodates practices that may make traditional tauren spiritualists uneasy.",al={"why undead here","why forsaken in cave","thunder bluff undead"}},{q="What services can you find inside the Pools of Vision?",a="The cavern hosts trainers and practitioners for priests and mages, along with emissaries for the Defilers who muster soldiers for the war effort in the Arathi Highlands.",al={"trainers in pools of vision","what is in pools of vision","pools of vision trainers"}},{q="Where do mages arrive when they teleport to Thunder Bluff?",a="Mages casting a teleport or opening a portal to Thunder Bluff manifest directly inside the sheltered waters of the Pools of Vision beneath Spirit Rise.",al={"mage teleport thunder bluff spot","tb teleport location"}}},ang={["race:Undead"]="For the Forsaken traversing the plains of Kalimdor, this cavern provides a familiar, shaded haven complete with arcane resources, priestly guidance, and fellowship.",["class:Mage"]="The cavern anchors the arcane ley connections to the city; any teleportation spell weaving into Thunder Bluff delivers its caster right beside these secluded pools."},kw={"defilers","forsaken","mage portal","pools of vision","spirit rise","thunder bluff","undead enclave"},rel={"zone:thunderbluff","subzone:spirit-rise","topic:forsaken","topic:horde","topic:tauren"},src={"Pools of Vision"}}
E["subzone:spirit-rise"] = {t="subzone",n="Spirit Rise",z="thunderbluff",s="Spirit Rise is the northwest mesa of Thunder Bluff, serving as the tauren capital's premier sanctum for spiritual and shamanic study. Overseen by spiritual guides such as the Skychaser tribe, it features sacred training halls above and descends into the cavernous Pools of Vision below.",h="Spirit Rise is the northwest mesa of Thunder Bluff, serving as the tauren capital's premier sanctum for...",sec={{t="A Sanctuary of the Spirits",b="Perched high upon the bluffs overlooking the plains of Mulgore, Spirit Rise is devoted to communion with the elements and ancestor spirits. Connected to the central mesa by rope bridges, it houses the Hall of Spirits and the Spiritual Healing pavilion, where young and veteran shaman gather to deepen their connection with the earth, air, fire, and water. The Skychaser tribe maintains a strong presence across the rise, guiding seekers through ancient traditions.",sp=0},{t="Caves and Crossings",b="Beneath the breezy huts and open-air totem shrines lies an entrance burrowing into the mesa itself: the steamy Pools of Vision, a sacred subterranean cavern where seers peer into spirit-touched waters. In addition to its contemplative quiet, the rise serves as a vital transit hub, linking Thunder Bluff across the continent via zeppelin towers that connect travelers directly to Orgrimmar.",sp=0}},faq={{q="What is Spirit Rise known for?",a="Spirit Rise is the spiritual heart of Thunder Bluff, primarily dedicated to shamanic practice, healing, and communing with nature spirits and ancestors. It also serves as the entryway to the Pools of Vision and hosts the city's zeppelin dock.",al={"what is spirit rise","spirit rise purpose","why visit spirit rise"}},{q="Which tauren tribe leads activities on Spirit Rise?",a="The Skychaser tribe holds prominent influence here, fostering the spiritual traditions, divination rituals, and shamanic training that define the rise.",al={"who runs spirit rise","spirit rise tribe","skychaser tribe"}},{q="What can I find underneath Spirit Rise?",a="A descent through the rise leads into the Pools of Vision, a humid subterranean cavern filled with steaming waters where seers and spiritual practitioners meditate and seek visions.",al={"spirit rise cave","below spirit rise","pools of vision entrance"}},{q="How do I travel to Orgrimmar from Spirit Rise?",a="Spirit Rise features a zeppelin dock servicing airships that ferry Horde travelers across the Barrens and directly into the orcish capital of Orgrimmar.",al={"zeppelin to orgrimmar","spirit rise zeppelin","thunder bluff zeppelin"}}},ang={["class:Shaman"]="For shaman of the Horde, Spirit Rise serves as an essential gathering place to consult trainers, perform elemental rites, and commune with ancestral spirits.",["race:Tauren"]="The rise embodies the deep spiritual roots of your people, offering solace away from secular duties alongside the mystical waters of the Pools of Vision."},kw={"hall of spirits","mulgore","pools of vision","shaman","skychaser","spirit rise","thunder bluff","zeppelin"},rel={"zone:thunderbluff","subzone:pools-of-vision","zone:orgrimmar"},src={"Spirit Rise"}}
E["zone:thunderbluff"] = {t="city",n="Thunder Bluff",z="thunderbluff",s="Thunder Bluff is the magnificent capital city of the tauren, perched atop windswept red-rock mesas rising above the grasslands of Mulgore. Founded by High Chieftain Cairne Bloodhoof after uniting the nomadic tribes with the aid of the New Horde, it serves as the cultural, spiritual, and mercantile heart of his people. Connected by swaying rope bridges and wooden lifts, the city offers safety from centaur marauders and a peaceful sanctuary for travelers across Kalimdor.",h="Thunder Bluff is the magnificent capital city of the tauren, perched atop windswept red-rock mesas rising...",sec={{t="A Permanent Haven",b="For countless generations, the tauren lived as nomadic wanderers across Kalimdor, locked in a brutal struggle for survival against ravenous centaur tribes. That desperate era ended during the Third War when Cairne Bloodhoof joined forces with Warchief Thrall. Together, the orcs and tauren broke the centaur assaults and secured the lush pastures of Mulgore. To protect their future, Cairne led the allied tribes to the safety of these natural stone bastions, founding Thunder Bluff as the first unified, permanent home the tauren had possessed in centuries.",sp=0},{t="A City in the Clouds",b="Spanning several high mesas linked by suspended rope bridges, Thunder Bluff seamlessly blends natural architecture with tauren practicality. The central bluffs host the bustling markets, bank, inn, and towering Wind Rider roost, while three specialized mesas branch out across the abyss. Hunter Rise serves the city's scouts and trackers; Elder Rise hosts lorekeepers and the Cenarion Circle under Archdruid Hamuul Runetotem; and Spirit Rise is devoted to spiritual communion, sheltering shamans, priests, and the mysterious subterranean caverns known as the Pools of Vision.",sp=0},{t="Uneasy Unity",b="While Cairne Bloodhoof commands immense respect from almost every tribe, governing a recently settled, proud people is not without friction. Notably, the Grimtotem tribe—led by the shrewd and sharp-tongued Elder Crone Magatha Grimtotem—maintains a brooding presence on Elder Rise. Magatha openly questions Cairne's conciliatory methods and allegiance to the foreign races of the Horde. Though peace endures beneath the chieftain's watchful gaze, ideological rifts murmur among the council fires above the plains.",sp=1}},faq={{q="Who rules Thunder Bluff?",a="High Chieftain Cairne Bloodhoof rules Thunder Bluff and leads the united tauren tribes. Revered for his wisdom, patience, and mighty strength, Cairne founded the city after allying with Thrall's Horde and driving the centaur from Mulgore.",al={"leader of thunder bluff","who is in charge","thunder bluff chieftain","cairne"}},{q="How do you get up to Thunder Bluff?",a="Visitors arriving on foot or kodo must ride massive wooden platform elevators located on the southwestern and northeastern sides of the central mesa. Alternatively, the city features a Wind Rider roost with flight paths across Kalimdor, as well as a direct zeppelin tower on Spirit Rise connecting to Orgrimmar.",al={"thunder bluff elevator","how to get in","thunder bluff entrance","getting up"}},{q="Why did the tauren build on high mesas instead of the ground?",a="Centuries of nomadic existence were marked by relentless hit-and-run attacks from aggressive centaur clans. The sheer cliffs of Mulgore's bluffs provide natural defense, shielding the tauren's dwellings, smiths, and sacred elders from ground ambushes and allowing them to permanently settle in peace.",al={"why mesas","why are they on cliffs","thunder bluff cliffs","tauren high ground"}},{q="What are the different rises of the city?",a="The city spans a central mesa (divided into lower, middle, and high tiers) surrounded by three outer mesas. Hunter Rise is dedicated to warriors, hunters, and tracking lodges. Elder Rise is home to druids, wisemen, and the Grimtotem faction. Spirit Rise holds shrines to the Earth Mother, trainers of shamans, priests, and mages, and the cavernous Pools of Vision.",al={"thunder bluff areas","what are the rises","districts of thunder bluff"}},{q="What are the Pools of Vision?",a="The Pools of Vision are sacred underground caverns tucked beneath Spirit Rise. Tauren seers, spiritwalkers, and practitioners of the arcane gather in these quiet, mist-shrouded waters to commune with the elements and interpret omens regarding the future of their people.",al={"pools of vision","spirit rise cave","thunder bluff cave"}},{q="Who is Magatha Grimtotem?",a="Magatha Grimtotem is the matriarch and Elder Crone of the formidable Grimtotem clan. While she resides on Elder Rise and outwardly participates in Cairne's council, she is fiercely traditional, distrusting outsiders and quietly challenging the Bloodhoof tribe's soft stance toward the Horde.",al={"magatha","elder crone","who is the grimtotem leader"}}},ang={["race:Tauren"]="Thunder Bluff represents the hard-won unity and rebirth of your people after generations of nomadic wandering and centaur harassment under High Chieftain Cairne Bloodhoof.",["class:Druid"]="Elder Rise serves as the Horde's supreme sanctuary of nature magic, headed by Archdruid Hamuul Runetotem, the first tauren druid taught in thousands of years.",["class:Shaman"]="Spirit Rise and the subterranean Pools of Vision provide a serene nexus where the elemental spirits and spirits of tauren ancestors are revered and heard.",["faction:Horde"]="Far more tranquil and spiritual than the harsh battlements of Orgrimmar, Thunder Bluff serves as the pastoral anchor of the New Horde's southern influence in Kalimdor."},kw={"cairne bloodhoof","elder rise","elevators","hamuul runetotem","hunter rise","magatha grimtotem","mulgore","pools of vision","spirit rise","thunder bluff"},rel={"npc:cairne-bloodhoof","zone:mulgore","npc:magatha-grimtotem","subzone:pools-of-vision","subzone:elder-rise","subzone:hunter-rise","subzone:spirit-rise"},src={"Thunder Bluff"}}
